def _codex_install_admission_capability_manager():
    """Return one process-local, identity-based installed admission gate.

    The public globals above remain compatibility telemetry.  They are not an
    authority: only the exact opaque object registered here after the complete
    pre-bootstrap admission can recover its retained reader and command kind.
    """
    issued = None

    class _Capability:
        __slots__ = ()

        def __copy__(self):
            raise TypeError("installed admission capability is not copyable")

        def __deepcopy__(self, _memo):
            raise TypeError("installed admission capability is not copyable")

    def issue(*, reader, command_kind, installed_root, codex_home):
        nonlocal issued
        if issued is not None:
            raise RuntimeError("installed admission capability was already issued")
        capability = _Capability()
        issued = (
            capability,
            reader,
            command_kind,
            Path(installed_root).absolute(),
            Path(codex_home).absolute(),
        )
        return capability

    def replay(capability):
        if issued is None or capability is not issued[0]:
            raise RuntimeError("installed admission capability is absent")
        return issued[1:]

    return issue, replay


(
    _issue_codex_install_admission_capability,
    _replay_codex_install_admission_capability,
) = _codex_install_admission_capability_manager()
