def _borrowed_reader_canonical_bytes(value):
    return (json.dumps(value, sort_keys=True, separators=(",", ":")) + "\n").encode("utf-8")


def _borrowed_reader_environment_sha256(environment):
    sealed = {
        str(key): str(value)
        for key, value in environment.items()
        if str(key) not in _PLAMEN_BORROWED_READER_ENV
    }
    return hashlib.sha256(_borrowed_reader_canonical_bytes(sealed)).hexdigest()


def _borrowed_reader_process_started_100ns(process_handle=None):
    if os.name != "nt":
        return _posix_process_started_100ns(os.getpid())
    import ctypes
    from ctypes import wintypes

    kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
    kernel32.GetCurrentProcess.restype = wintypes.HANDLE
    kernel32.GetProcessTimes.argtypes = [
        wintypes.HANDLE, ctypes.POINTER(wintypes.FILETIME),
        ctypes.POINTER(wintypes.FILETIME), ctypes.POINTER(wintypes.FILETIME),
        ctypes.POINTER(wintypes.FILETIME),
    ]
    kernel32.GetProcessTimes.restype = wintypes.BOOL
    handle = process_handle or kernel32.GetCurrentProcess()
    created = wintypes.FILETIME()
    exited = wintypes.FILETIME()
    kernel = wintypes.FILETIME()
    user = wintypes.FILETIME()
    if not kernel32.GetProcessTimes(handle, ctypes.byref(created), ctypes.byref(exited), ctypes.byref(kernel), ctypes.byref(user)):
        raise RuntimeError("borrowed reader process identity unavailable")
    return (int(created.dwHighDateTime) << 32) | int(created.dwLowDateTime)


def _borrowed_reader_parent_started_100ns(parent_pid):
    if os.name != "nt":
        return _posix_process_started_100ns(parent_pid)
    import ctypes
    from ctypes import wintypes

    kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
    kernel32.OpenProcess.argtypes = [wintypes.DWORD, wintypes.BOOL, wintypes.DWORD]
    kernel32.OpenProcess.restype = wintypes.HANDLE
    kernel32.CloseHandle.argtypes = [wintypes.HANDLE]
    handle = kernel32.OpenProcess(0x1000, False, int(parent_pid))
    if not handle:
        raise RuntimeError("borrowed reader parent identity unavailable")
    try:
        return _borrowed_reader_process_started_100ns(handle)
    finally:
        kernel32.CloseHandle(handle)


def _posix_process_started_100ns(pid):
    """Return a native, reuse-resistant process start identity on POSIX."""
    if not isinstance(pid, int) or isinstance(pid, bool) or pid <= 0:
        raise RuntimeError("borrowed reader process identity is malformed")
    if sys.platform.startswith("linux"):
        try:
            return int(os.stat(f"/proc/{pid}").st_ctime_ns // 100)
        except OSError as exc:
            raise RuntimeError("borrowed reader process identity unavailable") from exc
    if sys.platform == "darwin":
        import ctypes

        class _ProcBsdInfo(ctypes.Structure):
            _fields_ = [
                ("pbi_flags", ctypes.c_uint32), ("pbi_status", ctypes.c_uint32),
                ("pbi_xstatus", ctypes.c_uint32), ("pbi_pid", ctypes.c_uint32),
                ("pbi_ppid", ctypes.c_uint32), ("pbi_uid", ctypes.c_uint32),
                ("pbi_gid", ctypes.c_uint32), ("pbi_ruid", ctypes.c_uint32),
                ("pbi_rgid", ctypes.c_uint32), ("pbi_svuid", ctypes.c_uint32),
                ("pbi_svgid", ctypes.c_uint32), ("rfu_1", ctypes.c_uint32),
                ("pbi_comm", ctypes.c_char * 16), ("pbi_name", ctypes.c_char * 32),
                ("pbi_nfiles", ctypes.c_uint32), ("pbi_pgid", ctypes.c_uint32),
                ("pbi_pjobc", ctypes.c_uint32), ("e_tdev", ctypes.c_uint32),
                ("e_tpgid", ctypes.c_uint32), ("pbi_nice", ctypes.c_int32),
                ("pbi_start_tvsec", ctypes.c_uint64),
                ("pbi_start_tvusec", ctypes.c_uint64),
            ]

        try:
            libproc = ctypes.CDLL("/usr/lib/libproc.dylib", use_errno=True)
            function = libproc.proc_pidinfo
            function.argtypes = [
                ctypes.c_int, ctypes.c_int, ctypes.c_uint64,
                ctypes.c_void_p, ctypes.c_int,
            ]
            function.restype = ctypes.c_int
            info = _ProcBsdInfo()
            observed = function(
                pid, 3, 0, ctypes.byref(info), ctypes.sizeof(info),
            )
        except (OSError, AttributeError) as exc:
            raise RuntimeError("borrowed reader Darwin identity API unavailable") from exc
        if (
            observed != ctypes.sizeof(info) or info.pbi_pid != pid
            or info.pbi_start_tvsec <= 0 or info.pbi_start_tvusec >= 1_000_000
        ):
            raise RuntimeError("borrowed reader Darwin process identity unavailable")
        return int(info.pbi_start_tvsec) * 10_000_000 + int(info.pbi_start_tvusec) * 10
    raise RuntimeError("borrowed reader process identity is unsupported on this POSIX OS")


def _codex_locked_cached_api(owner, builder):
    """Publish exactly one cold-start native API/type cache across all threads."""
    cached = getattr(owner, "_cached", None)
    if cached is not None:
        return cached
    with _CODEX_NATIVE_CACHE_INIT_LOCK:
        cached = getattr(owner, "_cached", None)
        if cached is None:
            cached = builder()
            owner._cached = cached
        return cached


def _borrowed_reader_identity_api():
    """Cache ctypes identity types/functions; dynamic Structure classes leak caches."""
    return _codex_locked_cached_api(
        _borrowed_reader_identity_api, _build_borrowed_reader_identity_api,
    )


def _build_borrowed_reader_identity_api():
    import ctypes
    from ctypes import wintypes

    class _Info(ctypes.Structure):
        _fields_ = [
            ("attrs", wintypes.DWORD), ("created", wintypes.FILETIME),
            ("accessed", wintypes.FILETIME), ("written", wintypes.FILETIME),
            ("volume", wintypes.DWORD), ("size_high", wintypes.DWORD),
            ("size_low", wintypes.DWORD), ("links", wintypes.DWORD),
            ("index_high", wintypes.DWORD), ("index_low", wintypes.DWORD),
        ]

    class _Tag(ctypes.Structure):
        _fields_ = [("attrs", wintypes.DWORD), ("tag", wintypes.DWORD)]

    kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
    kernel32.GetFileInformationByHandle.argtypes = [
        wintypes.HANDLE, ctypes.POINTER(_Info),
    ]
    kernel32.GetFileInformationByHandle.restype = wintypes.BOOL
    kernel32.GetFileInformationByHandleEx.argtypes = [
        wintypes.HANDLE, ctypes.c_int, wintypes.LPVOID, wintypes.DWORD,
    ]
    kernel32.GetFileInformationByHandleEx.restype = wintypes.BOOL
    return (ctypes, kernel32, _Info, _Tag)


def _borrowed_reader_handle_identity(handle):
    if os.name != "nt":
        value = os.fstat(handle)
        return {
            "volume": int(value.st_dev), "file_id": int(value.st_ino),
            "attributes": int(getattr(value, "st_file_attributes", 0)),
            "reparse_tag": int(getattr(value, "st_reparse_tag", 0)),
            "links": int(value.st_nlink), "size": int(value.st_size),
        }
    ctypes, kernel32, _Info, _Tag = _borrowed_reader_identity_api()
    info = _Info()
    tag = _Tag()
    if not kernel32.GetFileInformationByHandle(int(handle), ctypes.byref(info)):
        raise OSError(
            ctypes.get_last_error(),
            "borrowed admission handle identity unavailable",
        )
    if not kernel32.GetFileInformationByHandleEx(int(handle), 9, ctypes.byref(tag), ctypes.sizeof(tag)):
        raise RuntimeError("borrowed admission handle tag unavailable")
    if int(info.attrs) != int(tag.attrs):
        raise RuntimeError("borrowed admission handle attribute disagreement")
    return {
        "volume": int(info.volume),
        "file_id": (int(info.index_high) << 32) | int(info.index_low),
        "attributes": int(info.attrs), "reparse_tag": int(tag.tag),
        "links": int(info.links),
        "size": (int(info.size_high) << 32) | int(info.size_low),
    }


def _borrowed_reader_handle_bytes(handle, *, maximum=1024 * 1024):
    """Read one retained ordinary file before replaceable helpers exist."""
    identity = _borrowed_reader_handle_identity(handle)
    size = identity["size"]
    if (
        not isinstance(size, int) or isinstance(size, bool)
        or size < 0 or size > maximum
    ):
        raise RuntimeError("borrowed retained file exceeds read bound")
    if os.name != "nt":
        raw = os.pread(handle, size, 0)
    else:
        import ctypes
        from ctypes import wintypes
        kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
        kernel32.SetFilePointerEx.argtypes = [
            wintypes.HANDLE, ctypes.c_longlong,
            ctypes.POINTER(ctypes.c_longlong), wintypes.DWORD,
        ]
        kernel32.SetFilePointerEx.restype = wintypes.BOOL
        kernel32.ReadFile.argtypes = [
            wintypes.HANDLE, wintypes.LPVOID, wintypes.DWORD,
            ctypes.POINTER(wintypes.DWORD), wintypes.LPVOID,
        ]
        kernel32.ReadFile.restype = wintypes.BOOL
        if not kernel32.SetFilePointerEx(int(handle), 0, None, 0):
            raise OSError(ctypes.get_last_error(), "SetFilePointerEx retained read")
        chunks = []; remaining = size
        while remaining:
            length = min(remaining, 1024 * 1024)
            buffer = ctypes.create_string_buffer(length); observed = wintypes.DWORD()
            if not kernel32.ReadFile(
                int(handle), buffer, length, ctypes.byref(observed), None,
            ):
                raise OSError(ctypes.get_last_error(), "ReadFile retained authority")
            if observed.value <= 0 or observed.value > length:
                raise RuntimeError("borrowed retained file short read")
            chunks.append(buffer.raw[:observed.value]); remaining -= observed.value
        raw = b"".join(chunks)
    if len(raw) != size or _borrowed_reader_handle_identity(handle) != identity:
        raise RuntimeError("borrowed retained file authority drifted")
    return raw


def _borrowed_reader_read_channel(raw_handle, *, maximum):
    import msvcrt
    flags = os.O_RDONLY | getattr(os, "O_BINARY", 0)
    descriptor = msvcrt.open_osfhandle(int(raw_handle), flags) if os.name == "nt" else int(raw_handle)
    try:
        chunks = []
        total = 0
        while True:
            block = os.read(descriptor, min(65536, maximum + 1 - total))
            if not block:
                break
            chunks.append(block)
            total += len(block)
            if total > maximum:
                raise RuntimeError("borrowed capability is oversized")
        return b"".join(chunks)
    finally:
        os.close(descriptor)


def _borrowed_reader_write_channel(raw_handle, raw):
    import msvcrt
    flags = os.O_WRONLY | getattr(os, "O_BINARY", 0)
    descriptor = msvcrt.open_osfhandle(int(raw_handle), flags) if os.name == "nt" else int(raw_handle)
    try:
        offset = 0
        while offset < len(raw):
            count = os.write(descriptor, raw[offset:])
            if count <= 0:
                raise RuntimeError("borrowed acknowledgment write failed")
            offset += count
    finally:
        os.close(descriptor)


def _consume_borrowed_install_reader(*, installed, codex_home, command_kinds, strict_json):
    present = [name in os.environ for name in _PLAMEN_BORROWED_READER_ENV]
    if not any(present):
        return None
    if not all(present):
        raise RuntimeError("borrowed reader channel is incomplete")
    values = []
    for name in _PLAMEN_BORROWED_READER_ENV:
        value = os.environ.pop(name, "")
        if not re.fullmatch(r"[1-9][0-9]*", value):
            raise RuntimeError("borrowed reader handle identifier is malformed")
        values.append(int(value))
    anchor_handle, capability_handle, ack_handle = values
    sys.stdout.write(
        _borrowed_reader_canonical_bytes({
            "schema": "plamen.borrowed_install_reader.ready.v1",
            "pid": os.getpid(),
            "started_100ns": _borrowed_reader_process_started_100ns(),
            "parent_pid": os.getppid(),
            "parent_started_100ns": _borrowed_reader_parent_started_100ns(
                os.getppid()
            ),
        }).decode("ascii")
    )
    sys.stdout.flush()
    raw = _borrowed_reader_read_channel(capability_handle, maximum=1024 * 1024)
    capability = strict_json(raw)
    if not isinstance(capability, dict):
        raise RuntimeError("borrowed reader capability field set is malformed")
    capability_fields = set(capability)
    if capability_fields != _PLAMEN_BORROWED_READER_FIELDS:
        raise RuntimeError(
            "borrowed reader capability field set is malformed: "
            + repr({
                "missing": sorted(_PLAMEN_BORROWED_READER_FIELDS - capability_fields),
                "extra": sorted(capability_fields - _PLAMEN_BORROWED_READER_FIELDS),
            })
        )
    unsigned = dict(capability)
    signature = unsigned.pop("signature", None)
    if not isinstance(signature, str) or not re.fullmatch(r"[0-9a-f]{64}", signature):
        raise RuntimeError("borrowed reader capability signature is malformed")
    if hashlib.sha256(_borrowed_reader_canonical_bytes(unsigned)).hexdigest() != signature:
        raise RuntimeError("borrowed reader capability authentication failed")
    now = time.time_ns()
    if capability.get("schema") != _PLAMEN_BORROWED_READER_SCHEMA:
        raise RuntimeError("borrowed reader capability schema is foreign")
    if (
        not isinstance(capability.get("nonce"), str)
        or not re.fullmatch(r"[0-9a-f]{32,}", capability["nonce"])
        or not isinstance(capability.get("issued_ns"), int)
        or isinstance(capability.get("issued_ns"), bool)
        or not isinstance(capability.get("expires_ns"), int)
        or isinstance(capability.get("expires_ns"), bool)
        or capability["issued_ns"] <= 0
        or capability["issued_ns"] > now
        or capability["expires_ns"] < now
        or capability["expires_ns"] - capability["issued_ns"] > 300_000_000_000
    ):
        raise RuntimeError("borrowed reader capability lifetime is invalid")
    if (
        capability.get("parent_pid") != os.getppid()
        or capability.get("parent_started_100ns") != _borrowed_reader_parent_started_100ns(os.getppid())
        or capability.get("child_pid") != os.getpid()
        or capability.get("child_started_100ns") != _borrowed_reader_process_started_100ns()
    ):
        raise RuntimeError("borrowed reader process authority differs")
    if capability.get("mode") != "READ_ONLY_ADMISSION" or capability.get("one_use") is not True or capability.get("nested_child_authority") is not False:
        raise RuntimeError("borrowed reader mode is not exact")
    if capability.get("expected") != {"allowed_rc": [0], "stdout": "CAPTURE", "stderr": "CAPTURE"}:
        raise RuntimeError("borrowed reader result envelope is malformed")
    if capability.get("command_kind") not in command_kinds:
        raise RuntimeError("borrowed reader command kind is not permitted")
    expected_kind = command_kinds[capability["command_kind"]]
    if not expected_kind(sys.argv[1:]):
        raise RuntimeError("borrowed reader argv does not match command kind")
    # These are initial addresses only.  Native descriptors below, rather than
    # lexical normalization, authenticate the executable and installed module.
    interpreter_path = Path(sys.executable)
    script_path = Path(__file__)
    interpreter_descriptor, _interpreter_raw = _codex_install_committed_descriptor(
        interpreter_path.parent, (interpreter_path.name,), return_raw=True,
        allow_stable_foreign_links=True,
    )
    script_descriptor, _script_raw = _codex_install_committed_descriptor(
        script_path.parent, (script_path.name,), return_raw=True,
    )
    argv = [str(interpreter_path), "-B", str(script_path), *sys.argv[1:]]
    if capability.get("argv") != argv or capability.get("argv_sha256") != hashlib.sha256(_borrowed_reader_canonical_bytes(argv)).hexdigest():
        raise RuntimeError("borrowed reader argv authority differs")
    cwd = os.getcwd()
    if capability.get("cwd") != cwd:
        raise RuntimeError("borrowed reader working directory differs")
    cwd_path = Path(cwd)
    cwd_descriptor, _cwd_names = _codex_install_committed_descriptor(
        cwd_path.parent, (cwd_path.name,), directory=True, return_raw=True,
    )
    current_environment = [
        [str(key), str(value)] for key, value in sorted(os.environ.items())
    ]
    if (
        capability.get("environment") != current_environment
        or capability.get("environment_sha256")
        != _borrowed_reader_environment_sha256(os.environ)
    ):
        raise RuntimeError("borrowed reader environment authority differs")
    if capability.get("cwd_authority") != cwd_descriptor:
        raise RuntimeError("borrowed reader working directory authority differs")
    for field, current, descriptor in (
        ("interpreter", interpreter_path, interpreter_descriptor),
        ("script", script_path, script_descriptor),
    ):
        identity = capability.get(field)
        if not isinstance(identity, dict) or set(identity) != {"path", "size", "sha256"}:
            raise RuntimeError("borrowed reader executable identity is malformed")
        if (
            identity.get("path") != str(current)
            or identity.get("size") != descriptor["size"]
            or identity.get("sha256") != descriptor["sha256"]
        ):
            raise RuntimeError("borrowed reader executable identity differs")
    if capability.get("codex_home") != str(codex_home) or capability.get("plamen_home") != str(installed):
        raise RuntimeError("borrowed reader root authority differs")
    anchor_identity = _borrowed_reader_handle_identity(anchor_handle)
    if anchor_identity != capability.get("anchor_identity") or anchor_identity["links"] != 1 or anchor_identity["reparse_tag"] != 0 or anchor_identity["attributes"] & 0x400:
        raise RuntimeError("borrowed reader native anchor authority differs")
    receipt = capability.get("receipt")
    receipt_path = Path(codex_home) / ".plamen-codex-install.json"
    _receipt_descriptor, receipt_raw = _codex_install_committed_descriptor(
        codex_home, (".plamen-codex-install.json",), return_raw=True,
    )
    if (
        not isinstance(receipt, dict)
        or set(receipt) != {"path", "state", "transaction_id", "size", "sha256"}
        or receipt.get("path") != str(receipt_path)
        or receipt.get("state") != "COMMITTED"
        or receipt.get("transaction_id") != capability.get("transaction_id")
        or receipt.get("size") != len(receipt_raw)
        or receipt.get("sha256") != hashlib.sha256(receipt_raw).hexdigest()
    ):
        raise RuntimeError("borrowed reader receipt authority differs")
    parsed_receipt = strict_json(receipt_raw)
    if (
        parsed_receipt.get("state") != "COMMITTED"
        or parsed_receipt.get("transaction_id") != capability.get("transaction_id")
        or parsed_receipt.get("source_manifest_sha256") != capability.get("source_manifest_sha256")
        or parsed_receipt.get("source_manifest_sha256") != capability.get("combined_manifest_sha256")
        or capability.get("installed_generation") != capability.get("transaction_id")
    ):
        raise RuntimeError("borrowed reader receipt generation differs")
    expected_handles = {
        "anchor": anchor_handle, "capability": capability_handle,
        "ack": ack_handle,
    }
    if capability.get("inherited_handles") != expected_handles:
        raise RuntimeError("borrowed reader inherited handle roster differs")
    acknowledgment = _borrowed_reader_canonical_bytes({
        "schema": "plamen.borrowed_install_reader.ack.v1",
        "nonce": capability["nonce"], "pid": os.getpid(),
        "started_100ns": capability["child_started_100ns"],
        "anchor_identity": anchor_identity, "state": "CONSUMED",
    })
    _borrowed_reader_write_channel(ack_handle, acknowledgment)
    if os.name == "nt":
        import ctypes
        from ctypes import wintypes
        kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
        kernel32.CloseHandle.argtypes = [wintypes.HANDLE]
        kernel32.CloseHandle.restype = wintypes.BOOL
        close = lambda: kernel32.CloseHandle(int(anchor_handle))
    else:
        close = lambda: os.close(anchor_handle)
    return anchor_handle, close, receipt_raw, capability


def _strict_json_bytes(raw):
    """Load bounded authority JSON while rejecting duplicate object keys."""
    if not isinstance(raw, (bytes, bytearray)) or len(raw) > 8 * 1024 * 1024:
        raise RuntimeError("Plamen install receipt is missing or oversized")

    def _pairs(items):
        value = {}
        for key, item in items:
            if key in value:
                raise ValueError(f"duplicate key: {key}")
            value[key] = item
        return value

    def _constant(value):
        raise ValueError("non-finite JSON constant: " + value)

    return json.loads(
        bytes(raw).decode("utf-8"), object_pairs_hook=_pairs,
        parse_constant=_constant,
    )


def _admission_sha256(path):
    digest = hashlib.sha256()
    with open(path, "rb") as stream:
        for block in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()


def _codex_install_raw_components(value):
    """Validate caller bytes before constructing any path-like object."""
    if not isinstance(value, tuple) or not value:
        raise RuntimeError("Codex install raw components require a nonempty tuple")
    forbidden = set('<>"|?*')
    reserved = {"CON", "PRN", "AUX", "NUL", "CLOCK$"} | {
        f"{prefix}{number}" for prefix in ("COM", "LPT") for number in range(1, 10)
    }
    for component in value:
        if not isinstance(component, str) or not component:
            raise RuntimeError("Codex install raw component is empty or non-string")
        stem = component.split(".", 1)[0].upper()
        if (
            component in {".", ".."}
            or component[-1] in {".", " "}
            or any(mark in component for mark in ("/", "\\", ":", "\x00"))
            or any(ord(char) < 32 or char in forbidden for char in component)
            or re.fullmatch(r"[^.]{1,6}~[0-9](?:\..{0,3})?", component, re.IGNORECASE)
            or stem in reserved
        ):
            raise RuntimeError("Codex install raw component is ambiguous")
    return value


def _codex_install_posix_committed_read(
    root, raw_components, *, directory=False, allow_stable_foreign_links=False,
    maximum=1024 * 1024 * 1024,
):
    """Dependency-closed POSIX retained-root reader used during bootstrap too."""
    import unicodedata

    components = _codex_install_raw_components(raw_components)
    required = (
        (os.open, os.supports_dir_fd),
        (os.stat, os.supports_dir_fd),
        (os.stat, os.supports_follow_symlinks),
        (os.scandir, os.supports_fd),
    )
    if (
        os.name == "nt"
        or not hasattr(os, "O_NOFOLLOW")
        or not hasattr(os, "O_DIRECTORY")
        or any(function not in support for function, support in required)
    ):
        raise RuntimeError("POSIX committed no-follow authority is unavailable")

    root_value = os.fspath(root)
    root_path = (
        os.path.normpath(os.path.abspath(root_value))
        if isinstance(root_value, str) else None
    )
    if (
        not isinstance(root_path, str)
        or not os.path.isabs(root_value)
        or root_value != root_path
        or (root_path != os.sep and root_path.startswith(os.sep * 2))
        or "\x00" in root_path
    ):
        raise RuntimeError("POSIX committed root path is not canonical")
    root_components = tuple(
        component for component in root_path.split(os.sep) if component
    )
    directory_flags = (
        os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW
        | getattr(os, "O_CLOEXEC", 0)
    )
    file_flags = os.O_RDONLY | os.O_NOFOLLOW | getattr(os, "O_CLOEXEC", 0)
    opened = []
    relationships = []

    def stable_identity(value):
        return (
            int(value.st_dev), int(value.st_ino), int(value.st_mode),
            int(value.st_nlink), int(value.st_size),
            int(value.st_mtime_ns), int(value.st_ctime_ns),
        )

    def alias_key(value):
        return unicodedata.normalize("NFC", value).casefold()

    def directory_names(descriptor, *, exact_component=None, full=False):
        names = []
        with os.scandir(descriptor) as entries:
            for entry in entries:
                name = entry.name
                if (
                    not isinstance(name, str) or not name
                    or name in {".", ".."} or "\x00" in name
                ):
                    raise RuntimeError(
                        "POSIX committed directory roster is malformed"
                    )
                names.append(name)
                if len(names) > 4096:
                    raise RuntimeError(
                        "POSIX committed directory roster exceeds bound"
                    )
        if exact_component is not None:
            aliases = [
                name for name in names
                if alias_key(name) == alias_key(exact_component)
            ]
            if not aliases:
                raise FileNotFoundError(
                    errno.ENOENT,
                    "POSIX committed component is absent",
                    exact_component,
                )
            if aliases != [exact_component]:
                raise RuntimeError(
                    "POSIX committed component case/NFC identity differs"
                )
        if full:
            folded = [alias_key(name) for name in names]
            if len(folded) != len(set(folded)):
                raise RuntimeError(
                    "POSIX committed directory roster contains aliases"
                )
        return tuple(names)

    def open_directory(parent, component):
        directory_names(parent, exact_component=component)
        descriptor = os.open(component, directory_flags, dir_fd=parent)
        opened.append(descriptor)
        opened_stat = os.fstat(descriptor)
        named_stat = os.stat(
            component, dir_fd=parent, follow_symlinks=False,
        )
        before = stable_identity(opened_stat)
        if (
            before != stable_identity(named_stat)
            or not stat.S_ISDIR(opened_stat.st_mode)
            or int(opened_stat.st_nlink) <= 0
        ):
            raise RuntimeError("POSIX committed parent identity differs")
        relationships.append((parent, component, descriptor, before))
        return descriptor

    try:
        retained_root = os.open(os.sep, directory_flags)
        opened.append(retained_root)
        parent = retained_root
        for component in root_components:
            parent = open_directory(parent, component)
        authority_root = parent
        authority_root_stat = os.fstat(authority_root)
        if (
            not stat.S_ISDIR(authority_root_stat.st_mode)
            or int(authority_root_stat.st_nlink) <= 0
        ):
            raise RuntimeError("POSIX committed root identity differs")
        authority_device = int(authority_root_stat.st_dev)

        leaf = None
        leaf_before = None
        for ordinal, component in enumerate(components):
            final = ordinal == len(components) - 1
            if not final or directory:
                descriptor = open_directory(parent, component)
            else:
                directory_names(parent, exact_component=component)
                descriptor = os.open(component, file_flags, dir_fd=parent)
                opened.append(descriptor)
                opened_stat = os.fstat(descriptor)
                named_stat = os.stat(
                    component, dir_fd=parent, follow_symlinks=False,
                )
                before = stable_identity(opened_stat)
                if (
                    before != stable_identity(named_stat)
                    or not stat.S_ISREG(opened_stat.st_mode)
                    or int(opened_stat.st_nlink) <= 0
                    or (
                        int(opened_stat.st_nlink) != 1
                        and not allow_stable_foreign_links
                    )
                ):
                    raise RuntimeError("POSIX committed file identity differs")
                relationships.append((parent, component, descriptor, before))
            observed = os.fstat(descriptor)
            if int(observed.st_dev) != authority_device:
                raise RuntimeError("committed read crossed volume")
            parent = descriptor
            if final:
                leaf = descriptor
                leaf_before = observed
        if leaf is None or leaf_before is None:
            raise RuntimeError("POSIX committed leaf is unavailable")

        attributes = 0x10 if directory else 0
        if not int(leaf_before.st_mode) & (
            stat.S_IWUSR | stat.S_IWGRP | stat.S_IWOTH
        ):
            attributes |= 0x1
        result = {
            "kind": "directory" if directory else "file",
            "device": int(leaf_before.st_dev),
            "inode": int(leaf_before.st_ino),
            "mode": int(leaf_before.st_mode),
            "links": int(leaf_before.st_nlink),
            "size": int(leaf_before.st_size),
            "attributes": attributes,
            "reparse_tag": 0,
            "name": components[-1],
        }
        if directory:
            value = directory_names(leaf, full=True)
        else:
            size = result["size"]
            if (
                type(maximum) is not int
                or maximum <= 0
                or maximum > 1024 * 1024 * 1024
                or size < 0
                or size > maximum
            ):
                raise RuntimeError("POSIX committed file size exceeds bound")
            chunks = []
            digest = hashlib.sha256()
            offset = 0
            while offset < size:
                raw = os.pread(
                    leaf, min(1024 * 1024, size - offset), offset,
                )
                if not raw or len(raw) > size - offset:
                    raise RuntimeError("POSIX committed retained read is short")
                chunks.append(raw); digest.update(raw); offset += len(raw)
            if os.pread(leaf, 1, size):
                raise RuntimeError("POSIX committed retained file grew")
            value = b"".join(chunks)
            result["sha256"] = digest.hexdigest()
            result["streams"] = []

        if stable_identity(os.fstat(leaf)) != stable_identity(leaf_before):
            raise RuntimeError("POSIX committed leaf changed during read")
        for parent, component, descriptor, before in relationships:
            opened_after = os.fstat(descriptor)
            named_after = os.stat(
                component, dir_fd=parent, follow_symlinks=False,
            )
            directory_names(parent, exact_component=component)
            if (
                stable_identity(opened_after) != before
                or stable_identity(named_after) != before
            ):
                raise RuntimeError("POSIX committed authority changed during read")
        if not directory and hashlib.sha256(value).hexdigest() != result["sha256"]:
            raise RuntimeError("committed same-handle bytes differ")
        return result, value
    except FileNotFoundError:
        # Recovery and first-install callers intentionally distinguish an
        # absent exact component from a present-but-invalid authority.
        raise
    except (OSError, RuntimeError) as exc:
        if isinstance(exc, RuntimeError):
            raise
        raise RuntimeError("POSIX committed authority is unavailable") from exc
    finally:
        for descriptor in reversed(opened):
            try:
                os.close(descriptor)
            except OSError:
                pass


def _codex_install_committed_descriptor(
    root, raw_components, *, return_raw=False, directory=False,
    allow_stable_foreign_links=False,
):
    """Open an installed leaf through a retained root with no path authorization."""
    components = _codex_install_raw_components(raw_components)
    if os.name != "nt":
        descriptor, raw = _codex_install_posix_committed_read(
            root, components, directory=directory,
            allow_stable_foreign_links=allow_stable_foreign_links,
        )
        return (descriptor, raw) if return_raw else descriptor
    late_dependencies = {
        "_codex_dispatcher_open_root", "_codex_native_open_relative",
        "_codex_native_exact_component", "_codex_native_read",
        "_codex_native_directory_names", "_codex_native_close",
        "_CodexInstallMutationDispatcher",
    }
    if any(name not in globals() for name in late_dependencies):
        # Bootstrap admission runs before the replaceable runtime is imported.
        # Retain and join every component with no delete sharing; the later
        # dispatcher implementation replaces this bootstrap adapter.
        import ctypes
        from ctypes import wintypes

        kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
        kernel32.CreateFileW.restype = wintypes.HANDLE
        kernel32.GetFinalPathNameByHandleW.argtypes = [
            wintypes.HANDLE, wintypes.LPWSTR, wintypes.DWORD, wintypes.DWORD,
        ]
        kernel32.GetFinalPathNameByHandleW.restype = wintypes.DWORD
        kernel32.SetFilePointerEx.argtypes = [
            wintypes.HANDLE, ctypes.c_longlong,
            ctypes.POINTER(ctypes.c_longlong), wintypes.DWORD,
        ]
        kernel32.SetFilePointerEx.restype = wintypes.BOOL
        kernel32.ReadFile.argtypes = [
            wintypes.HANDLE, wintypes.LPVOID, wintypes.DWORD,
            ctypes.POINTER(wintypes.DWORD), wintypes.LPVOID,
        ]
        kernel32.ReadFile.restype = wintypes.BOOL
        kernel32.GetFileInformationByHandleEx.argtypes = [
            wintypes.HANDLE, ctypes.c_int, wintypes.LPVOID, wintypes.DWORD,
        ]
        kernel32.GetFileInformationByHandleEx.restype = wintypes.BOOL
        kernel32.CloseHandle.argtypes = [wintypes.HANDLE]
        kernel32.CloseHandle.restype = wintypes.BOOL
        handles = []

        def open_exact(path, component, *, directory):
            handle = kernel32.CreateFileW(
                str(path), 0x80000000 | 0x00000080 | 0x00100000,
                0x00000001 | 0x00000002, None, 3,
                0x02000000 | (0x00200000 if directory else 0), None,
            )
            if handle == wintypes.HANDLE(-1).value:
                raise OSError(ctypes.get_last_error(), "CreateFileW committed bootstrap")
            handle = int(handle); handles.append(handle)
            length = kernel32.GetFinalPathNameByHandleW(handle, None, 0, 0)
            if length <= 0 or length > 32768:
                raise RuntimeError("committed bootstrap final name unavailable")
            buffer = ctypes.create_unicode_buffer(length + 1)
            observed = kernel32.GetFinalPathNameByHandleW(handle, buffer, len(buffer), 0)
            name = buffer.value.rstrip("\\/").rsplit("\\", 1)[-1]
            identity = _borrowed_reader_handle_identity(handle)
            if observed <= 0 or name != component:
                raise RuntimeError("committed bootstrap component identity differs")
            if bool(identity["attributes"] & 0x10) != bool(directory):
                raise RuntimeError("committed bootstrap component kind differs")
            if identity["reparse_tag"] or identity["attributes"] & 0x400:
                raise RuntimeError("committed bootstrap rejected reparse component")
            return handle, identity, name

        try:
            # `root` is only an address used to acquire a native handle.  Do
            # not normalize it: the retained identity and exact component
            # checks below are the authority.
            root_path = Path(root)
            root_handle, root_identity, _root_name = open_exact(
                root_path, root_path.name, directory=True,
            )
            current = root_path
            leaf_handle = None; leaf_identity = None; leaf_name = None
            for index, component in enumerate(components):
                current = current / component
                leaf_handle, leaf_identity, leaf_name = open_exact(
                    current, component,
                    directory=index < len(components) - 1 or directory,
                )
                if leaf_identity["volume"] != root_identity["volume"]:
                    raise RuntimeError("committed bootstrap crossed volume")
            if directory:
                raw = []
                restart = True
                while True:
                    buffer = ctypes.create_string_buffer(64 * 1024)
                    info_class = 11 if restart else 10
                    if not kernel32.GetFileInformationByHandleEx(
                        leaf_handle, info_class, buffer, len(buffer),
                    ):
                        error = ctypes.get_last_error()
                        if error == 18:
                            break
                        raise OSError(error, "bootstrap directory roster")
                    restart = False; data = buffer.raw; offset = 0
                    while True:
                        next_offset = int.from_bytes(data[offset:offset + 4], "little")
                        name_length = int.from_bytes(data[offset + 60:offset + 64], "little")
                        end = offset + 104 + name_length
                        if name_length <= 0 or name_length % 2 or end > len(data):
                            raise RuntimeError("bootstrap directory roster is malformed")
                        name = data[offset + 104:end].decode("utf-16-le")
                        if name not in {".", ".."}:
                            raw.append(name)
                        if next_offset == 0:
                            break
                        if next_offset < 104 or offset + next_offset >= len(data):
                            raise RuntimeError("bootstrap directory offset differs")
                        offset += next_offset
                if len(raw) != len(set(raw)) or len(raw) != len({name.casefold() for name in raw}):
                    raise RuntimeError("bootstrap directory roster contains aliases")
                streams = None
            else:
                raw = bytearray()
                if not kernel32.SetFilePointerEx(leaf_handle, 0, None, 0):
                    raise OSError(ctypes.get_last_error(), "SetFilePointerEx bootstrap")
                remaining = leaf_identity["size"]
                while remaining:
                    size = min(remaining, 1024 * 1024)
                    buffer = ctypes.create_string_buffer(size); observed = wintypes.DWORD()
                    if not kernel32.ReadFile(leaf_handle, buffer, size, ctypes.byref(observed), None):
                        raise OSError(ctypes.get_last_error(), "ReadFile bootstrap")
                    if observed.value <= 0 or observed.value > size:
                        raise RuntimeError("committed bootstrap short read")
                    raw.extend(buffer.raw[:observed.value]); remaining -= observed.value
                streams = []
                stream_size = 4096
                while stream_size <= 1024 * 1024:
                    buffer = ctypes.create_string_buffer(stream_size)
                    if kernel32.GetFileInformationByHandleEx(leaf_handle, 7, buffer, stream_size):
                        data = buffer.raw; offset = 0
                        while True:
                            next_offset = int.from_bytes(data[offset:offset + 4], "little")
                            name_length = int.from_bytes(data[offset + 4:offset + 8], "little")
                            size = int.from_bytes(data[offset + 8:offset + 16], "little", signed=True)
                            allocation = int.from_bytes(data[offset + 16:offset + 24], "little", signed=True)
                            name = data[offset + 24:offset + 24 + name_length].decode("utf-16-le")
                            streams.append({"name": name, "size": size, "allocation_size": allocation})
                            if next_offset == 0: break
                            offset += next_offset
                        break
                    if ctypes.get_last_error() != 234:
                        raise OSError(ctypes.get_last_error(), "bootstrap stream roster")
                    stream_size *= 2
                if [row["name"] for row in streams] not in (["::$DATA"], []):
                    raise RuntimeError("committed bootstrap rejected alternate stream")
            descriptor = {
                "kind": "directory" if directory else "file",
                "device": leaf_identity["volume"],
                "inode": leaf_identity["file_id"], "mode": leaf_identity["attributes"],
                "links": leaf_identity["links"], "size": leaf_identity["size"],
                "attributes": leaf_identity["attributes"],
                "reparse_tag": leaf_identity["reparse_tag"], "name": leaf_name,
            }
            if not directory:
                raw = bytes(raw)
                descriptor["sha256"] = hashlib.sha256(raw).hexdigest()
                descriptor["streams"] = streams
            else:
                raw = tuple(raw)
            return (descriptor, raw) if return_raw else descriptor
        finally:
            for handle in reversed(handles):
                kernel32.CloseHandle(handle)
    root_handle, root_close = _codex_dispatcher_open_root(
        root, full_mutation=False,
    )
    opened = []
    try:
        root_identity = _borrowed_reader_handle_identity(root_handle)
        parent = root_handle
        for component in components[:-1]:
            handle = _codex_native_open_relative(
                parent, component, directory=True, create=False,
                access=0x00000001 | 0x00000080 | 0x00100000,
                share_delete=False,
            )
            opened.append(handle)
            identity = _codex_native_exact_component(handle, component)
            if not identity["attributes"] & 0x10 or identity["volume"] != root_identity["volume"]:
                raise RuntimeError("committed install parent identity mismatch")
            parent = handle
        leaf = _codex_native_open_relative(
            parent, components[-1], directory=directory, create=False,
            access=(0x00000001 if directory else 0x80000000) | 0x00000080 | 0x00100000,
            share_delete=False,
        )
        opened.append(leaf)
        identity = _codex_native_exact_component(leaf, components[-1])
        descriptor = _CodexInstallMutationDispatcher._native_handle_descriptor(
            leaf, identity=identity,
            allow_stable_foreign_links=allow_stable_foreign_links,
        )
        if descriptor["name"] != components[-1] or descriptor["device"] != root_identity["volume"]:
            raise RuntimeError("committed install leaf identity mismatch")
        if return_raw:
            raw = (
                _codex_native_directory_names(leaf)
                if directory else _codex_native_read(leaf)
            )
            if not directory and hashlib.sha256(raw).hexdigest() != descriptor["sha256"]:
                raise RuntimeError("committed install same-handle bytes differ")
            return descriptor, raw
        return descriptor
    finally:
        for handle in reversed(opened):
            _codex_native_close(handle)
        root_close()


def _codex_install_terminal_verification(
    *, verified_manifest_sha256, completed_ns=None,
    projection_public_key=None, projection_lock_public_key=None,
    prior_lock_authority=None, legacy_projection_migration=None,
):
    """Build the exact terminal schema consumed by both installed entrypoints."""
    if not re.fullmatch(r"[0-9a-f]{64}", verified_manifest_sha256 or ""):
        raise RuntimeError("terminal install manifest authority is malformed")
    if completed_ns is None:
        completed_ns = time.time_ns()
    if (
        not isinstance(completed_ns, int) or isinstance(completed_ns, bool)
        or completed_ns <= 0
    ):
        raise RuntimeError("terminal install completion time is malformed")
    terminal = {
        "verified_count": _CODEX_INSTALL_SOURCE_COUNT,
        "verified_manifest_sha256": verified_manifest_sha256,
        "completed_ns": completed_ns,
    }
    if projection_public_key is None:
        if any(value is not None for value in (
            projection_lock_public_key, prior_lock_authority,
            legacy_projection_migration,
        )):
            raise RuntimeError("terminal projection authority is incomplete")
        return terminal
    if not re.fullmatch(r"[0-9a-f]{64}", projection_public_key or ""):
        raise RuntimeError("terminal projection authority is malformed")
    if (
        projection_lock_public_key is None
        and prior_lock_authority is None
        and legacy_projection_migration is None
    ):
        terminal["projection_public_key"] = projection_public_key
        return terminal
    if (
        not re.fullmatch(
            r"[0-9a-f]{64}", projection_lock_public_key or ""
        )
        or not isinstance(prior_lock_authority, dict)
    ):
        raise RuntimeError("terminal projection authority is malformed")
    terminal.update({
        "projection_public_key": projection_public_key,
        "projection_lock_public_key": projection_lock_public_key,
        "projection_lock_authority_sha256": hashlib.sha256(json.dumps(
            prior_lock_authority, sort_keys=True, separators=(",", ":"),
        ).encode("utf-8")).hexdigest(),
    })
    if legacy_projection_migration is not None:
        if not isinstance(legacy_projection_migration, dict):
            raise RuntimeError("terminal legacy projection migration is malformed")
        terminal["legacy_projection_migration"] = legacy_projection_migration
    return terminal


def _validate_committed_legacy_projection_migration(
    receipt, *, claude_home,
):
    """Validate migration lineage using only pre-bootstrap dependencies."""
    terminal = (
        receipt.get("terminal_verification")
        if isinstance(receipt, dict) else None
    )
    migration = (
        terminal.get("legacy_projection_migration")
        if isinstance(terminal, dict) else None
    )
    if migration is None:
        return None

    def canonical(value):
        if not isinstance(value, str) or not value or "\x00" in value:
            raise RuntimeError("Claude projection path is malformed")
        if value.startswith("\\\\?\\") or value.startswith("\\??\\"):
            raise RuntimeError("Claude projection extended path is forbidden")
        result = os.path.normpath(os.path.abspath(value))
        if os.path.normcase(value) != os.path.normcase(result):
            raise RuntimeError("Claude projection path is not canonical")
        return result

    fields = {
        "schema", "migration_id", "prior_transaction_id",
        "prior_receipt_sha256", "legacy_source_root", "legacy_lock",
        "successor_lock_sha256", "legacy_manifest_sha256",
        "legacy_projection_count", "legacy_runtime_count",
        "legacy_projection_roster", "legacy_projection_roster_sha256",
        "prior_anchor_identity", "prepackage_intent_sha256",
    }
    legacy_fields = {
        "path", "public_key", "device", "inode", "links", "size", "sha256",
    }
    if (
        not isinstance(migration, dict) or set(migration) != fields
        or migration.get("schema") != _CLAUDE_PROJECTION_LEGACY_MIGRATION_SCHEMA
        or not re.fullmatch(r"[0-9a-f]{32}", migration.get("migration_id", ""))
        or not re.fullmatch(
            r"[0-9a-f]{32}", migration.get("prior_transaction_id", "")
        )
        or not re.fullmatch(
            r"[0-9a-f]{64}", migration.get("prior_receipt_sha256", "")
        )
        or not re.fullmatch(
            r"[0-9a-f]{64}", migration.get("successor_lock_sha256", "")
        )
        or not re.fullmatch(
            r"[0-9a-f]{64}", migration.get("legacy_manifest_sha256", "")
        )
        or not re.fullmatch(
            r"[0-9a-f]{64}",
            migration.get("legacy_projection_roster_sha256", ""),
        )
        or (
            migration.get("prepackage_intent_sha256") is not None
            and not re.fullmatch(
                r"[0-9a-f]{64}",
                migration.get("prepackage_intent_sha256", ""),
            )
        )
        or any(
            not isinstance(migration.get(field), int)
            or isinstance(migration.get(field), bool)
            or migration[field] <= 0
            for field in ("legacy_projection_count", "legacy_runtime_count")
        )
        or not isinstance(migration.get("prior_anchor_identity"), list)
        or len(migration["prior_anchor_identity"]) != 2
        or any(
            not isinstance(item, int) or isinstance(item, bool) or item <= 0
            for item in migration["prior_anchor_identity"]
        )
        or not isinstance(migration.get("legacy_lock"), dict)
        or set(migration["legacy_lock"]) != legacy_fields
        or migration["legacy_lock"].get("public_key")
        != _CLAUDE_PROJECTION_LEGACY_PUBLIC
    ):
        raise RuntimeError("legacy Claude projection migration authority is malformed")
    source_root = canonical(migration["legacy_source_root"])
    if os.path.normcase(source_root) != os.path.normcase(
        canonical(receipt.get("source_root"))
    ):
        raise RuntimeError("legacy Claude projection migration source differs")
    if (
        isinstance(receipt.get("lock_identity"), list)
        and receipt["lock_identity"] != migration["prior_anchor_identity"]
    ):
        raise RuntimeError("legacy Claude projection migration anchor differs")
    lock_path = canonical(os.path.join(canonical(claude_home), ".plamen-projection.lock"))
    legacy_lock = migration["legacy_lock"]
    if (
        os.path.normcase(canonical(legacy_lock.get("path")))
        != os.path.normcase(lock_path)
        or legacy_lock.get("links") != 1 or legacy_lock.get("size") != 1
        or legacy_lock.get("sha256")
        != hashlib.sha256(_CLAUDE_PROJECTION_LEGACY_LOCK_RAW).hexdigest()
        or any(
            not isinstance(legacy_lock.get(field), int)
            or isinstance(legacy_lock.get(field), bool)
            or legacy_lock[field] <= 0
            for field in ("device", "inode")
        )
    ):
        raise RuntimeError("legacy Claude projection migration lock differs")
    roster = migration.get("legacy_projection_roster")
    if (
        not isinstance(roster, list)
        or len(roster) != migration["legacy_projection_count"]
        or hashlib.sha256(json.dumps(
            roster, sort_keys=True, separators=(",", ":"),
        ).encode("utf-8")).hexdigest()
        != migration["legacy_projection_roster_sha256"]
    ):
        raise RuntimeError("legacy Claude projection migration roster differs")
    claude_root = canonical(claude_home)
    seen_destinations = set()
    for row in roster:
        if (
            not isinstance(row, dict)
            or set(row) != {
                "destination", "relative_path", "install_mode", "descriptor",
            }
            or row.get("install_mode") not in {"link", "copied", "copied_dir"}
            or not isinstance(row.get("relative_path"), str)
        ):
            raise RuntimeError("legacy Claude projection migration roster is malformed")
        relative = PurePosixPath(row["relative_path"])
        if relative.is_absolute() or ".." in relative.parts or not relative.parts:
            raise RuntimeError("legacy Claude projection migration roster path differs")
        destination = canonical(row["destination"])
        expected_destination = canonical(
            os.path.join(claude_root, *relative.parts)
        )
        key = os.path.normcase(destination)
        descriptor = row.get("descriptor")
        if (
            key in seen_destinations
            or key != os.path.normcase(expected_destination)
            or not isinstance(descriptor, dict)
        ):
            raise RuntimeError("legacy Claude projection migration destination differs")
        seen_destinations.add(key)
        mode = row["install_mode"]
        if mode == "link":
            expected_target = canonical(os.path.join(source_root, *relative.parts))
            if (
                set(descriptor) != {"kind", "target"}
                or descriptor.get("kind") not in {"symlink", "junction"}
                or os.path.normcase(canonical(descriptor.get("target")))
                != os.path.normcase(expected_target)
            ):
                raise RuntimeError("legacy Claude projection migration link differs")
        elif mode == "copied":
            if (
                set(descriptor) != {"kind", "size", "sha256"}
                or descriptor.get("kind") != "file"
                or not isinstance(descriptor.get("size"), int)
                or isinstance(descriptor.get("size"), bool)
                or descriptor["size"] < 0
                or not re.fullmatch(
                    r"[0-9a-f]{64}", descriptor.get("sha256", "")
                )
            ):
                raise RuntimeError("legacy Claude projection migration copy differs")
        elif (
            set(descriptor) != {"kind", "sha256"}
            or descriptor.get("kind") != "directory"
            or not re.fullmatch(r"[0-9a-f]{64}", descriptor.get("sha256", ""))
        ):
            raise RuntimeError("legacy Claude projection migration directory differs")
    return migration


def _validate_committed_install_rows(
    receipt, *, installed, codex_home,
    expected_count=_CODEX_INSTALL_SOURCE_COUNT,
    allow_preterminal_authority=False,
    allow_replaced_terminal_authority=False,
):
    """Validate the complete committed package before replaceable bootstrap."""
    row_fields = {
        "source_path", "install_kind", "destination_root", "destination_path",
        "destination_key", "size", "sha256", "destination", "stage",
    }
    journal_fields = {"index", "destination", "sha256"}
    rows = receipt["rows"]
    journal = receipt["journal"]
    terminal = receipt.get("terminal_verification")
    terminal_fields = set(terminal or ())
    if (
        terminal_fields not in _CODEX_INSTALL_TERMINAL_FIELD_SHAPES
        or type(terminal.get("verified_count")) is not int
        or terminal.get("verified_count") != expected_count
        or not isinstance(terminal.get("completed_ns"), int)
        or isinstance(terminal.get("completed_ns"), bool)
        or terminal["completed_ns"] <= 0
        or not re.fullmatch(
            r"[0-9a-f]{64}", terminal.get("verified_manifest_sha256", "")
        )
        or (
            "projection_public_key" in terminal_fields
            and not re.fullmatch(r"[0-9a-f]{64}", terminal["projection_public_key"])
        )
        or (
            "projection_lock_public_key" in terminal_fields
            and not re.fullmatch(
                r"[0-9a-f]{64}", terminal["projection_lock_public_key"]
            )
        )
        or (
            "projection_lock_authority_sha256" in terminal_fields
            and not re.fullmatch(
                r"[0-9a-f]{64}",
                terminal["projection_lock_authority_sha256"],
            )
        )
    ):
        raise RuntimeError("Plamen terminal install verification is malformed")
    if "legacy_projection_migration" in terminal_fields:
        _validate_committed_legacy_projection_migration(
            receipt,
            claude_home=str(Path(codex_home).absolute().parent / ".claude"),
        )
    manifests = {"plamen": [], "codex": []}
    keys = set()
    for index, row in enumerate(rows):
        observed_fields = set(row) if isinstance(row, dict) else set()
        authority_present = "terminal_authority" in observed_fields
        if (
            not isinstance(row, dict)
            or observed_fields - {"terminal_authority"} != row_fields
            or (not authority_present and not allow_preterminal_authority)
        ):
            raise RuntimeError("Plamen committed install row is malformed")
        root_name = row.get("destination_root")
        if root_name not in manifests:
            raise RuntimeError("Plamen committed destination root is malformed")
        relative = row.get("destination_path")
        source_path = row.get("source_path")
        size = row.get("size")
        digest = row.get("sha256")
        if (
            not isinstance(relative, str) or not relative
            or not isinstance(source_path, str) or not source_path
            or not isinstance(size, int) or isinstance(size, bool) or size < 0
            or not isinstance(digest, str) or not re.fullmatch(r"[0-9a-f]{64}", digest)
        ):
            raise RuntimeError("Plamen committed install row fields are malformed")
        base = installed if root_name == "plamen" else codex_home
        expected = base.joinpath(*relative.split("/"))
        destination = Path(row.get("destination", ""))
        if str(destination) != str(expected):
            raise RuntimeError("Plamen committed destination path is foreign")
        key = f"{root_name}/{relative}".casefold()
        if row.get("destination_key") != key or key in keys:
            raise RuntimeError("Plamen committed destination identity is malformed")
        keys.add(key)
        descriptor = _codex_install_committed_descriptor(
            base, tuple(relative.split("/")),
        )
        if (
            descriptor.get("kind") != "file"
            or descriptor.get("links") != 1
            or descriptor.get("size") != size
            or descriptor.get("sha256") != digest
        ):
            raise RuntimeError("Plamen committed installed bytes differ from receipt")
        if (
            authority_present
            and not allow_replaced_terminal_authority
            and descriptor != row["terminal_authority"]
        ):
            raise RuntimeError("Plamen committed installed authority differs from receipt")
        manifest = f"{source_path}|{size}|{digest}\n".encode("utf-8")
        manifests[root_name].append((source_path, manifest))
        entry = journal[index]
        entry_fields = set(entry) if isinstance(entry, dict) else set()
        journal_authority_present = "terminal_authority" in entry_fields
        if (
            not isinstance(entry, dict)
            or entry_fields - {"terminal_authority"} != journal_fields
            or (not journal_authority_present and not allow_preterminal_authority)
            or entry.get("index") != index
            or entry.get("destination") != str(destination)
            or entry.get("sha256") != digest
        ):
            raise RuntimeError("Plamen committed journal differs from installed rows")
        if (
            journal_authority_present
            and not allow_replaced_terminal_authority
            and entry["terminal_authority"] != descriptor
        ):
            raise RuntimeError("Plamen committed journal authority differs")
    def _manifest_sha(named_rows):
        return hashlib.sha256(b"".join(raw for _name, raw in sorted(named_rows))).hexdigest()
    runtime_sha = _manifest_sha(manifests["plamen"])
    adapter_sha = _manifest_sha(manifests["codex"])
    combined_sha = _manifest_sha(manifests["plamen"] + manifests["codex"])
    if (
        receipt.get("runtime_manifest_sha256") != runtime_sha
        or receipt.get("adapter_manifest_sha256") != adapter_sha
        or receipt.get("source_manifest_sha256") != combined_sha
        or terminal.get("verified_manifest_sha256") != combined_sha
    ):
        raise RuntimeError("Plamen committed manifest differs from installed rows")


def _terminal_pending_suffix_authority(
    *, prefix, folder_components, transaction_id, writer_generation, outcome,
):
    """Return the exact dispatcher events permitted after TERMINAL_PREFIX."""
    if (
        not isinstance(prefix, dict)
        or not isinstance(prefix.get("event_count"), int)
        or isinstance(prefix.get("event_count"), bool)
        or prefix["event_count"] < 0
        or not isinstance(folder_components, tuple)
        or not folder_components
    ):
        raise RuntimeError("terminal suffix prefix authority is malformed")
    rows = []

    def append(operation, components):
        rows.append({
            "ordinal": prefix["event_count"] + len(rows),
            "transaction_id": transaction_id,
            "writer_generation": writer_generation,
            "operation": operation, "root": "codex",
            "components": list(components), "state": "COMPLETED",
        })

    def publish_components(components, operation="EXCLUSIVE_BYTES"):
        main_ordinal = prefix["event_count"] + len(rows)
        append(operation, components)
        name = components[-1]
        append(
            "TEMP_BYTES",
            components[:-1] + (
                name + f".{transaction_id}.{main_ordinal:08d}.tmp",
            ),
        )

    def publish(name):
        publish_components(folder_components + (name,))

    publish("sentinel.json"); publish("manifest.json")
    publish("terminal-last.json"); publish("folder-seal.json")
    for name in (
        "precommit.json", "transaction.json", "smoke.json", "recovery.json",
        "broker.json", "process.json", "environment.json", "sentinel.json",
        "manifest.json", "folder-seal.json",
    ):
        append("MAKE_READONLY", folder_components + (name,))
    append("MAKE_READONLY", folder_components)
    result_name = {
        "COMMITTED": ".plamen-codex-install.json",
        "ROLLED_BACK": "rollback-result.json",
        "RECOVERED": "recovered-receipt.json",
        "EMERGENCY_REPAIR_REQUIRED": "emergency-result.json",
        "TERMINAL_GENERATION_FAILED": "terminal-failure-result.json",
    }.get(outcome)
    if result_name is None:
        raise RuntimeError("terminal suffix outcome is unsupported")
    result_components = (
        (result_name,) if outcome == "COMMITTED"
        else folder_components[:-1] + (result_name,)
    )
    publish_components(result_components, operation="ATOMIC_BYTES")
    append("FINISH_RETAINED", folder_components + ("terminal-last.json",))
    if len(rows) != 22:
        raise RuntimeError("terminal suffix event roster differs")
    return rows


def _terminal_dispatcher_event_authority(events):
    fields = (
        "ordinal", "transaction_id", "writer_generation", "operation",
        "root", "components", "state",
    )
    return [{key: event.get(key) for key in fields} for event in events]


def _terminal_expected_capture_labels(outcome):
    def boundaries(families):
        return tuple(
            f"{family.upper()}_{edge.upper()}_{side}"
            for family in families
            for edge in ("first", "middle", "last")
            for side in ("BEFORE", "AFTER")
        )
    if outcome == "COMMITTED":
        return (
            "PRE_SOURCE_CAPTURE", *boundaries(("capture_revalidation",)),
            "PRE_RECEIPT", "PRE_STAGE", *boundaries(("stage",)),
            "PRE_BACKUP", *boundaries(("backup",)),
            "PRECOMMIT", "PRE_EMERGENCY", "PRE_LIVE",
            *boundaries(("live",)), "POSTTRANSACTION", "PRE_SMOKE",
            "POSTSMOKE", "PRE_SENTINEL_CAPTURE", "PRE_TERMINAL",
        )
    if outcome == "ROLLED_BACK":
        return (
            "PRE_COMPENSATION",
            *boundaries(("compensation_restore", "compensation_delete")),
            "POSTCOMPENSATION", "PRE_SENTINEL_CAPTURE", "PRE_TERMINAL",
        )
    if outcome == "RECOVERED":
        return (
            "PRE_RECOVERY", *boundaries(("recovery_restore", "recovery_delete")),
            "POSTRECOVERY", "PRE_SENTINEL_CAPTURE", "PRE_TERMINAL",
        )
    if outcome in {"EMERGENCY_REPAIR_REQUIRED", "TERMINAL_GENERATION_FAILED"}:
        return ("PRE_EMERGENCY", "PRE_SENTINEL_CAPTURE", "PRE_TERMINAL")
    raise RuntimeError("install terminal outcome capture roster is unsupported")


def _terminal_capture_label_roster_is_valid(outcome, labels):
    labels = tuple(labels)
    if outcome in {"COMMITTED", "EMERGENCY_REPAIR_REQUIRED", "TERMINAL_GENERATION_FAILED"}:
        return labels == _terminal_expected_capture_labels(outcome)
    if outcome not in {"ROLLED_BACK", "RECOVERED"}:
        return False
    prefix = "COMPENSATION" if outcome == "ROLLED_BACK" else "RECOVERY"
    families = (
        ("COMPENSATION_RESTORE", "COMPENSATION_DELETE")
        if outcome == "ROLLED_BACK" else
        ("RECOVERY_RESTORE", "RECOVERY_DELETE")
    )
    if (
        len(labels) != 10
        or labels[0] != "PRE_" + prefix
        or labels[-3:] != (
            "POST" + prefix, "PRE_SENTINEL_CAPTURE", "PRE_TERMINAL",
        )
    ):
        return False
    middle = labels[1:7]
    for offset, edge in enumerate(("FIRST", "MIDDLE", "LAST")):
        before, after = middle[offset * 2:offset * 2 + 2]
        if not any(
            before == f"{family}_{edge}_BEFORE"
            and after == f"{family}_{edge}_AFTER"
            for family in families
        ):
            return False
    return True


def _validate_terminal_fold_authority(
    sentinel, *, capture_labels, folder_components,
    transaction_id, writer_generation, outcome,
):
    prefix = sentinel.get("terminal_prefix")
    suffix = sentinel.get("pending_suffix")
    capture_fields = {
        "label", "a_count", "a_sha256", "b_count", "b_sha256",
        "c_count", "c_sha256", "event_count", "event_sha256", "unknown_count",
    }
    if (
        not isinstance(prefix, dict) or set(prefix) != capture_fields
        or prefix.get("label") != "TERMINAL_PREFIX"
        or prefix.get("unknown_count") != 0
        or suffix != _terminal_pending_suffix_authority(
            prefix=prefix, folder_components=folder_components,
            transaction_id=transaction_id,
            writer_generation=writer_generation,
            outcome=outcome,
        )
        or sentinel.get("terminal_fold_sha256") != hashlib.sha256(
            _borrowed_reader_canonical_bytes([prefix, suffix])
        ).hexdigest()
        or [row.get("label") for row in sentinel.get("captures", ())]
        != list(capture_labels) + ["TERMINAL_PREFIX"]
    ):
        raise RuntimeError("Plamen sealed terminal fold authority differs")
    for partition in ("a", "b", "c"):
        rows = sentinel[partition]["rows"]
        if (
            prefix.get(partition + "_count") != len(rows)
            or prefix.get(partition + "_sha256") != hashlib.sha256(
                _borrowed_reader_canonical_bytes(rows)
            ).hexdigest()
        ):
            raise RuntimeError("Plamen sealed terminal partition fold differs")


def _terminal_evidence_committed_read(root, components, *, directory):
    """Use only dependency-closed readers during pre-bootstrap admission."""
    if "_codex_install_committed_read" in globals():
        return _codex_install_committed_read(
            root, components, directory=directory,
        )
    return _codex_install_committed_descriptor(
        root, components, return_raw=True, directory=directory,
    )


def _terminal_evidence_contract_hook(failpoint, seam):
    hook = globals().get("_codex_install_contract_hook")
    if hook is not None:
        hook(failpoint, seam)
    elif failpoint is not None:
        raise RuntimeError("terminal evidence pre-bootstrap failpoint is unavailable")


def _validate_codex_install_terminal_evidence(
    receipt, receipt_raw, *, codex_home, expected_outcome=None,
    expected_transaction_id=None, expected_writer_generation=None,
    expected_keeper_disposition=None, failpoint=None, dispatcher=None,
    source_rows=None, transaction_components=None, require_fresh=False,
):
    """Validate one pointer-selected terminal generation for its exact outcome."""
    if not isinstance(receipt, dict) or not isinstance(receipt_raw, bytes):
        raise RuntimeError("Plamen terminal result authority is malformed")
    if _strict_json_bytes(receipt_raw) != receipt:
        raise RuntimeError("Plamen terminal result bytes differ")
    outcome_by_schema = {
        _CODEX_INSTALL_SCHEMA: (
            "COMMITTED", "terminal-evidence", "RELEASE_UNUSED",
            _terminal_expected_capture_labels("COMMITTED"),
        ),
        "plamen.codex_install.rollback_result.v1": (
            "ROLLED_BACK", "terminal-evidence-compensated", "ROLLBACK_COMPLETED",
            None,
        ),
        "plamen.codex_install.recovery_result.v1": (
            "RECOVERED", "terminal-evidence-recovered", "RECOVERY_COMPLETED",
            None,
        ),
        "plamen.codex_install.emergency_result.v1": (
            "EMERGENCY_REPAIR_REQUIRED", "terminal-evidence-emergency",
            "EMERGENCY_KEEPER_BOUND",
            _terminal_expected_capture_labels("EMERGENCY_REPAIR_REQUIRED"),
        ),
        "plamen.codex_install.terminal_failure_result.v1": (
            "TERMINAL_GENERATION_FAILED", "terminal-evidence-failed",
            "EMERGENCY_KEEPER_BOUND",
            _terminal_expected_capture_labels("TERMINAL_GENERATION_FAILED"),
        ),
    }
    mapping = outcome_by_schema.get(receipt.get("schema"))
    if mapping is None:
        raise RuntimeError("Plamen terminal result schema is unsupported")
    outcome, folder_leaf, keeper_disposition, capture_labels = mapping
    if receipt.get("state") != outcome:
        raise RuntimeError("Plamen terminal result state differs")
    if expected_outcome is not None and expected_outcome != outcome:
        raise RuntimeError("Plamen terminal expected outcome differs")
    if (
        expected_keeper_disposition is not None
        and expected_keeper_disposition != keeper_disposition
    ):
        raise RuntimeError("Plamen terminal expected keeper disposition differs")
    pointer = receipt.get("terminal_evidence")
    fields = {
        "schema", "writer_generation", "folder", "folder_authority",
        "payload_count", "file_count", "manifest_sha256",
        "folder_seal_sha256", "reserved_terminal_authority",
    }
    transaction_id = receipt.get("transaction_id")
    if (
        not re.fullmatch(r"[0-9a-f]{32}", transaction_id or "")
        or (expected_transaction_id is not None
            and transaction_id != expected_transaction_id)
    ):
        raise RuntimeError("Plamen terminal transaction authority differs")
    folder_components = (
        ".plamen-install-transactions", transaction_id, folder_leaf,
    )
    if (
        not isinstance(pointer, dict) or set(pointer) != fields
        or pointer.get("schema") != "plamen.install.terminal.pointer.v1"
        or not isinstance(pointer.get("writer_generation"), str)
        or (expected_writer_generation is not None
            and pointer.get("writer_generation") != expected_writer_generation)
        or pointer.get("payload_count") != 8 or pointer.get("file_count") != 11
        or not re.fullmatch(r"[0-9a-f]{64}", pointer.get("manifest_sha256", ""))
        or not re.fullmatch(r"[0-9a-f]{64}", pointer.get("folder_seal_sha256", ""))
        or not isinstance(pointer.get("folder_authority"), dict)
        or not pointer.get("folder_authority")
        or not isinstance(pointer.get("reserved_terminal_authority"), dict)
        or not pointer.get("reserved_terminal_authority")
    ):
        raise RuntimeError("Plamen terminal evidence pointer is malformed")
    expected_names = (
        "precommit.json", "transaction.json", "smoke.json", "recovery.json",
        "broker.json", "process.json", "environment.json", "sentinel.json",
        "manifest.json", "folder-seal.json", "terminal-last.json",
    )
    folder, observed_names = _terminal_evidence_committed_read(
        codex_home, folder_components, directory=True,
    )
    if (
        tuple(sorted(observed_names)) != tuple(sorted(expected_names))
        or folder != pointer["folder_authority"]
        or pointer.get("folder") != os.path.join(str(codex_home), *folder_components)
    ):
        raise RuntimeError("Plamen terminal evidence folder authority differs")
    descriptors = {}; values = {}; raws = {}
    for name in expected_names:
        payload_hook = name[:-5].replace("-", "_") if name.endswith(".json") else name
        if name in expected_names[:8]:
            _terminal_evidence_contract_hook(failpoint, f"before_payload_{payload_hook}_join")
        _terminal_evidence_contract_hook(failpoint, "before_stream_attribute_join")
        descriptor, raw = _terminal_evidence_committed_read(
            codex_home, folder_components + (name,), directory=False,
        )
        if (
            not descriptor.get("attributes", 0) & 0x1
            or [row["name"] for row in descriptor.get("streams", [])]
            not in (["::$DATA"], [])
        ):
            raise RuntimeError("Plamen terminal evidence file authority differs")
        descriptors[name] = descriptor; raws[name] = raw
        values[name] = _strict_json_bytes(raw)
        _terminal_evidence_contract_hook(failpoint, "after_stream_attribute_join")
        if name in expected_names[:8]:
            _terminal_evidence_contract_hook(failpoint, f"after_payload_{payload_hook}_join")
    manifest = values["manifest.json"]
    folder_seal = values["folder-seal.json"]
    terminal = descriptors["terminal-last.json"]
    payload_names = expected_names[:8]
    payload_fields = {
        "precommit.json": {"schema", "transaction_id", "writer_generation", "source_count", "source_manifest_sha256", "inverse_sha256", "prior_receipt_authority"},
        "transaction.json": {"schema", "transaction_id", "state", "row_count", "rows_fold_sha256", "journal_fold_sha256"},
        "smoke.json": {"schema", "provider_invocations", "result_count", "results"},
        "recovery.json": {"schema", "outcome", "keeper_state", "recovery_command"},
        "broker.json": {"schema", "event_count", "event_fold_sha256"},
        "process.json": {"schema", "installer_pid", "keeper_pid", "smoke_pids", "provider_processes"},
        "environment.json": {"schema", "sanitized_environment_sha256", "interpreter_sha256", "script_sha256"},
        "sentinel.json": {
            "schema", "a", "b", "c", "unknown_count", "captures",
            "universe_sha256", "terminal_prefix", "pending_suffix",
            "terminal_fold_sha256",
        },
    }
    for name in payload_names:
        value = values[name]
        if (
            not isinstance(value, dict) or set(value) != payload_fields[name]
            or value.get("schema") != "plamen.install.terminal." + name[:-5].replace("-", "_") + ".v1"
        ):
            raise RuntimeError("Plamen terminal payload schema is malformed")
    _terminal_evidence_contract_hook(failpoint, "before_manifest_validate")
    if (
        values["precommit.json"].get("transaction_id") != transaction_id
        or values["precommit.json"].get("writer_generation") != pointer["writer_generation"]
        or values["transaction.json"].get("transaction_id") != transaction_id
        or values["transaction.json"].get("state") != outcome
        or values["smoke.json"].get("provider_invocations") != 0
        or values["smoke.json"].get("result_count") != len(values["smoke.json"].get("results", ()))
        or values["process.json"].get("provider_processes") != 0
    ):
        raise RuntimeError("Plamen terminal payload authority differs")
    prior_receipt = values["precommit.json"].get("prior_receipt_authority")
    if prior_receipt is not None and (
        not isinstance(prior_receipt, dict)
        or set(prior_receipt) != {
            "transaction_id", "size", "sha256", "terminal_authority",
        }
        or not re.fullmatch(r"[0-9a-f]{32}", prior_receipt.get("transaction_id", ""))
        or not isinstance(prior_receipt.get("size"), int)
        or isinstance(prior_receipt.get("size"), bool)
        or prior_receipt.get("size") <= 0
        or not re.fullmatch(r"[0-9a-f]{64}", prior_receipt.get("sha256", ""))
        or not isinstance(prior_receipt.get("terminal_authority"), dict)
        or not prior_receipt["terminal_authority"]
    ):
        raise RuntimeError("Plamen prior committed receipt authority differs")
    for partition in ("a", "b", "c"):
        value = values["sentinel.json"].get(partition)
        if (
            not isinstance(value, dict)
            or set(value) != {"count", "rows", "plamen_write_allowed"}
            or not isinstance(value.get("rows"), list)
            or value.get("count") != len(value["rows"])
            or value.get("plamen_write_allowed") is (partition != "a")
        ):
            raise RuntimeError("Plamen terminal sentinel partition is malformed")
    a_rows = values["sentinel.json"]["a"]["rows"]
    b_rows = values["sentinel.json"]["b"]["rows"]
    c_rows = values["sentinel.json"]["c"]["rows"]
    captures = values["sentinel.json"].get("captures")
    observed_capture_labels = (
        [row.get("label") for row in captures[:-1]]
        if isinstance(captures, list) and captures else []
    )
    if capture_labels is None:
        capture_labels = tuple(observed_capture_labels)
    if (
        values["sentinel.json"].get("unknown_count") != 0
        or len(a_rows) != len(set(a_rows)) or len(b_rows) != len(set(b_rows))
        or len(c_rows) != len(set(c_rows))
        or set(a_rows) & set(b_rows) or set(a_rows) & set(c_rows) or set(b_rows) & set(c_rows)
        or values["sentinel.json"].get("universe_sha256") != hashlib.sha256(
            _borrowed_reader_canonical_bytes([a_rows, b_rows, c_rows])
        ).hexdigest()
        or not isinstance(captures, list)
        or not _terminal_capture_label_roster_is_valid(
            outcome, observed_capture_labels,
        )
        or [row.get("label") for row in captures]
        != observed_capture_labels + ["TERMINAL_PREFIX"]
    ):
        raise RuntimeError("Plamen terminal sentinel universe differs")
    _validate_terminal_fold_authority(
        values["sentinel.json"], capture_labels=capture_labels,
        folder_components=folder_components, transaction_id=transaction_id,
        writer_generation=pointer["writer_generation"], outcome=outcome,
    )
    capture_fields = {
        "label", "a_count", "a_sha256", "b_count",
        "b_sha256", "c_count", "c_sha256", "event_count",
        "event_sha256", "unknown_count",
    }
    for capture in captures:
        if (
            not isinstance(capture, dict) or set(capture) != capture_fields
            or capture.get("unknown_count") != 0
            or not re.fullmatch(
                r"[0-9a-f]{64}", capture.get("event_sha256", "")
            )
            or any(
                not isinstance(capture.get(prefix + "_count"), int)
                or isinstance(capture.get(prefix + "_count"), bool)
                or capture.get(prefix + "_count") < 0
                or not re.fullmatch(
                    r"[0-9a-f]{64}", capture.get(prefix + "_sha256", "")
                )
                for prefix in ("a", "b", "c")
            )
        ):
            raise RuntimeError("Plamen terminal sentinel capture differs")
    required_c_fields = {
        "schema", "rule_id", "typed_root", "initial_address", "state",
        "root_identity", "parent_identity", "selector",
        "maximum_depth", "maximum_count", "maximum_bytes", "owner_class",
        "process_class", "installer_pid", "installer_started_100ns",
        "transaction_id", "created_ns", "generation", "rule_sha256",
        "lifetime", "allowed_external_operations", "transition_limit",
        "empty_before", "empty_after", "rejection_policy", "children",
        "observed_operation", "observed_transition_count",
    }
    for raw_c in c_rows:
        value = _strict_json_bytes((raw_c + "\n").encode("utf-8"))
        if (
            set(value) != required_c_fields
            or value.get("transaction_id") != transaction_id
            or value.get("selector", {}).get("kind") != "EXACT_CHILD"
            or value.get("maximum_depth") != 1
            or not isinstance(value.get("children"), list)
            or value.get("rejection_policy") != "DENY_UNKNOWN_OR_OUTSIDE_LIFETIME"
        ):
            raise RuntimeError("Plamen terminal C policy is malformed")
    if (
        captures[-1]["a_count"] != len(a_rows)
        or captures[-1]["b_count"] != len(b_rows)
        or captures[-1]["c_count"] != len(c_rows)
        or captures[-1]["a_sha256"] != hashlib.sha256(
            _borrowed_reader_canonical_bytes(a_rows)
        ).hexdigest()
        or captures[-1]["b_sha256"] != hashlib.sha256(
            _borrowed_reader_canonical_bytes(b_rows)
        ).hexdigest()
        or captures[-1]["c_sha256"] != hashlib.sha256(
            _borrowed_reader_canonical_bytes(c_rows)
        ).hexdigest()
    ):
        raise RuntimeError("Plamen terminal sentinel final capture differs")
    if (
        not isinstance(manifest, dict)
        or set(manifest) != {"schema", "transaction_id", "payload_count", "payloads"}
        or manifest.get("schema") != "plamen.install.terminal.manifest.v1"
        or manifest.get("transaction_id") != transaction_id
        or manifest.get("payload_count") != 8
        or not isinstance(manifest.get("payloads"), list)
        or len(manifest["payloads"]) != 8
    ):
        raise RuntimeError("Plamen terminal manifest is malformed")
    for ordinal, (name, row) in enumerate(zip(payload_names, manifest["payloads"])):
        if (
            not isinstance(row, dict)
            or set(row) != {"ordinal", "name", "size", "sha256", "terminal_authority"}
            or row.get("ordinal") != ordinal or row.get("name") != name
            or row.get("size") != len(raws[name])
            or row.get("sha256") != hashlib.sha256(raws[name]).hexdigest()
            or row.get("terminal_authority") != descriptors[name]
        ):
            raise RuntimeError("Plamen terminal manifest payload authority differs")
    _terminal_evidence_contract_hook(failpoint, "after_manifest_validate")
    _terminal_evidence_contract_hook(failpoint, "before_folder_seal_validate")
    if (
        not isinstance(folder_seal, dict)
        or set(folder_seal) != {
            "schema", "transaction_id", "file_count", "filenames",
            "folder_authority", "manifest_sha256",
            "reserved_terminal_authority", "extras",
        }
        or folder_seal.get("schema") != "plamen.install.terminal.folder_seal.v1"
        or folder_seal.get("transaction_id") != transaction_id
        or folder_seal.get("file_count") != 11
        or folder_seal.get("filenames") != list(expected_names)
        or folder_seal.get("manifest_sha256") != hashlib.sha256(raws["manifest.json"]).hexdigest()
        or folder_seal.get("reserved_terminal_authority") != pointer["reserved_terminal_authority"]
        or folder_seal.get("extras") != 0
    ):
        raise RuntimeError("Plamen terminal folder seal is malformed")
    _terminal_evidence_contract_hook(failpoint, "after_folder_seal_validate")
    prior_folder = folder_seal.get("folder_authority")
    reserved = pointer["reserved_terminal_authority"]
    stable = ("kind", "device", "inode", "links", "reparse_tag", "name")
    if (
        not isinstance(prior_folder, dict) or not prior_folder
        or any(prior_folder.get(key) != folder.get(key) for key in stable)
        or int(prior_folder.get("attributes", -1)) | 0x1 != folder.get("attributes")
        or not isinstance(reserved, dict)
        or reserved.get("kind") != "file" or reserved.get("size") != 0
        or reserved.get("sha256") != hashlib.sha256(b"").hexdigest()
        or any(reserved.get(key) != terminal.get(key) for key in stable)
    ):
        raise RuntimeError("Plamen terminal retained authority join differs")
    _terminal_evidence_contract_hook(failpoint, "before_terminal_last_validation")
    expected_terminal = _borrowed_reader_canonical_bytes({
        "schema": "plamen.install.terminal.last.v1", "outcome": outcome,
        "transaction_id": transaction_id,
        "writer_generation": pointer["writer_generation"],
        "receipt_sha256": hashlib.sha256(receipt_raw).hexdigest(),
        "manifest_sha256": pointer["manifest_sha256"],
        "folder_seal_sha256": pointer["folder_seal_sha256"],
        "postclose_required": True, "keeper_disposition": keeper_disposition,
        "terminal_fold_sha256": values["sentinel.json"]["terminal_fold_sha256"],
        "actual_suffix": values["sentinel.json"]["pending_suffix"],
    })
    if (
        hashlib.sha256(raws["manifest.json"]).hexdigest() != pointer["manifest_sha256"]
        or hashlib.sha256(raws["folder-seal.json"]).hexdigest() != pointer["folder_seal_sha256"]
        or terminal.get("sha256") != hashlib.sha256(expected_terminal).hexdigest()
    ):
        raise RuntimeError("Plamen terminal disk evidence differs")
    _terminal_evidence_contract_hook(failpoint, "after_terminal_last_validation")
    if require_fresh and (
        dispatcher is None or not isinstance(source_rows, list)
        or tuple(transaction_components or ()) != folder_components[:2]
    ):
        raise RuntimeError("Plamen terminal fresh universe authority is missing")
    if dispatcher is not None:
        final_capture = _capture_codex_install_sentinel(
            dispatcher=dispatcher, source_rows=source_rows,
            transaction_components=tuple(transaction_components), label="TERMINAL",
        )
        prefix = values["sentinel.json"]["terminal_prefix"]
        actual_suffix = _terminal_dispatcher_event_authority(
            dispatcher.events[prefix["event_count"]:]
        )
        if (
            final_capture.get("unknown_count") != 0
            or final_capture.get("b_sha256") != prefix.get("b_sha256")
            or final_capture.get("c_sha256") != prefix.get("c_sha256")
            or actual_suffix != values["sentinel.json"]["pending_suffix"]
            or values["terminal-last.json"].get("actual_suffix") != actual_suffix
        ):
            raise RuntimeError("Plamen terminal fresh universe differs from sealed fold")
        return final_capture
    # Consumers that need predecessor lineage must use this already joined
    # in-memory payload.  Reopening precommit.json after validating the sealed
    # manifest/folder/terminal-last tuple would create a validation-to-use seam.
    return values["precommit.json"]


def _open_install_admission_anchor(codex_home, *, writer, create=False):
    """Open the stable reader/writer anchor and retain a conflicting lease."""
    anchor = Path(codex_home) / _CODEX_INSTALL_ANCHOR
    if os.name == "nt":
        import ctypes
        from ctypes import wintypes

        kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
        kernel32.CreateFileW.restype = wintypes.HANDLE
        kernel32.GetFinalPathNameByHandleW.restype = wintypes.DWORD
        access = 0x80000000 | (0x40000000 if writer or create else 0)
        share = 0 if writer else 0x00000001
        handle = kernel32.CreateFileW(
            wintypes.LPCWSTR(str(anchor)),
            wintypes.DWORD(access),
            wintypes.DWORD(share),
            None,
            wintypes.DWORD(4 if create else 3),
            wintypes.DWORD(0x00000080 | 0x00200000 | 0x02000000),
            None,
        )
        if handle == wintypes.HANDLE(-1).value:
            code = ctypes.get_last_error()
            raise RuntimeError(f"Plamen installation is in maintenance (lock error {code})")
        handle = int(handle)
        identity = _borrowed_reader_handle_identity(handle)
        needed = kernel32.GetFinalPathNameByHandleW(handle, None, 0, 0)
        buffer = ctypes.create_unicode_buffer(needed + 1)
        observed = kernel32.GetFinalPathNameByHandleW(
            handle, buffer, len(buffer), 0,
        )
        final_name = buffer.value.rstrip("\\/").rsplit("\\", 1)[-1]
        if (
            not observed or final_name != _CODEX_INSTALL_ANCHOR
            or identity["reparse_tag"] != 0
            or identity["attributes"] & 0x400
            or identity["attributes"] & 0x10
            or identity["links"] != 1
        ):
            kernel32.CloseHandle(handle)
            raise RuntimeError(
                "Plamen install admission anchor is not an ordinary single-link file"
            )
        if create and identity["size"] == 0:
            seed = b"plamen-install-admission-v1\n"
            written = wintypes.DWORD()
            buffer = ctypes.create_string_buffer(seed)
            if (
                not kernel32.WriteFile(
                    handle, buffer, len(seed), ctypes.byref(written), None,
                )
                or written.value != len(seed)
                or not kernel32.FlushFileBuffers(handle)
            ):
                code = ctypes.get_last_error()
                kernel32.CloseHandle(handle)
                raise OSError(code, "write retained install anchor")
            identity = _borrowed_reader_handle_identity(handle)
        anchor_raw = _borrowed_reader_handle_bytes(handle, maximum=4096)
        if anchor_raw not in {
            b"plamen-install-admission-v1\n",
            b"plamen-install-admission-v1\r\n",
        }:
            kernel32.CloseHandle(handle)
            raise RuntimeError("Plamen install admission anchor bytes differ")

        def _close():
            kernel32.CloseHandle(handle)

        return anchor, handle, _close
    if create:
        anchor.parent.mkdir(parents=True, exist_ok=True)
        try:
            fd = os.open(str(anchor), os.O_CREAT | os.O_EXCL | os.O_WRONLY, 0o600)
        except FileExistsError:
            pass
        else:
            os.write(fd, b"plamen-install-admission-v1\n")
            os.fsync(fd)
            os.close(fd)
    st = os.lstat(anchor)
    if not os.path.isfile(anchor) or os.path.islink(anchor) or st.st_nlink != 1:
        raise RuntimeError("Plamen install admission anchor is not an ordinary single-link file")
    import fcntl

    descriptor = os.open(str(anchor), os.O_RDWR if writer else os.O_RDONLY)
    try:
        fcntl.flock(
            descriptor,
            (fcntl.LOCK_EX if writer else fcntl.LOCK_SH) | fcntl.LOCK_NB,
        )
    except Exception:
        os.close(descriptor)
        raise RuntimeError("Plamen installation is in maintenance")
    return anchor, descriptor, lambda: os.close(descriptor)


def _borrowed_reader_duplicate_for_child(handle):
    if os.name != "nt":
        duplicate = os.dup(handle)
        os.set_inheritable(duplicate, True)
        return duplicate
    import ctypes
    from ctypes import wintypes

    kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
    kernel32.GetCurrentProcess.restype = wintypes.HANDLE
    kernel32.DuplicateHandle.argtypes = [
        wintypes.HANDLE, wintypes.HANDLE, wintypes.HANDLE,
        ctypes.POINTER(wintypes.HANDLE), wintypes.DWORD, wintypes.BOOL,
        wintypes.DWORD,
    ]
    kernel32.DuplicateHandle.restype = wintypes.BOOL
    process = kernel32.GetCurrentProcess()
    duplicate = wintypes.HANDLE()
    desired_read = 0x80000000 | 0x00000080
    if not kernel32.DuplicateHandle(
        process, int(handle), process, ctypes.byref(duplicate), desired_read, True, 0
    ):
        raise RuntimeError("borrowed reader handle duplication failed")
    return int(duplicate.value)


def _duplicate_install_writer_for_child(handle):
    """Duplicate the exact writer file object without reducing its lease rights."""
    if os.name != "nt":
        duplicate = os.dup(handle)
        os.set_inheritable(duplicate, True)
        return duplicate
    import ctypes
    from ctypes import wintypes

    kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
    kernel32.GetCurrentProcess.restype = wintypes.HANDLE
    kernel32.DuplicateHandle.argtypes = [
        wintypes.HANDLE, wintypes.HANDLE, wintypes.HANDLE,
        ctypes.POINTER(wintypes.HANDLE), wintypes.DWORD, wintypes.BOOL,
        wintypes.DWORD,
    ]
    kernel32.DuplicateHandle.restype = wintypes.BOOL
    process = kernel32.GetCurrentProcess()
    duplicate = wintypes.HANDLE()
    if not kernel32.DuplicateHandle(
        process, int(handle), process, ctypes.byref(duplicate), 0, True, 0x2
    ):
        raise RuntimeError("install writer handle duplication failed")
    return int(duplicate.value)


def _borrowed_reader_close_native(handle):
    if os.name == "nt":
        import ctypes
        from ctypes import wintypes
        kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
        kernel32.CloseHandle.argtypes = [wintypes.HANDLE]
        kernel32.CloseHandle.restype = wintypes.BOOL
        if not kernel32.CloseHandle(int(handle)):
            raise OSError(ctypes.get_last_error(), "CloseHandle borrowed reader")
    else:
        os.close(handle)


def _codex_keeper_message(
    authkey, *, transaction_id, active_descriptor_sha256,
    keeper_binding_sha256, writer_generation, request_nonce,
    sequence, phase, state, body=None,
):
    if (
        not isinstance(authkey, bytes) or len(authkey) != 32
        or not re.fullmatch(r"[0-9a-f]{32}", transaction_id or "")
        or not re.fullmatch(r"[0-9a-f]{64}", active_descriptor_sha256 or "")
        or not re.fullmatch(r"[0-9a-f]{64}", keeper_binding_sha256 or "")
        or not isinstance(writer_generation, str) or not writer_generation
        or not re.fullmatch(r"[0-9a-f]{64}", request_nonce or "")
        or not isinstance(sequence, int) or isinstance(sequence, bool) or sequence < 0
        or not isinstance(phase, str) or not phase
        or not isinstance(state, str) or not state
        or (body is not None and not isinstance(body, dict))
    ):
        raise RuntimeError("Codex keeper message authority is malformed")
    unsigned = {
        "schema": _CODEX_KEEPER_MESSAGE_V1_SCHEMA,
        "transaction_id": transaction_id,
        "active_descriptor_sha256": active_descriptor_sha256,
        "keeper_binding_sha256": keeper_binding_sha256,
        "writer_generation": writer_generation,
        "request_nonce": request_nonce,
        "sequence": sequence,
        "phase": phase,
        "state": state,
        "body": body or {},
    }
    value = dict(unsigned)
    value["mac"] = hmac.new(
        authkey, _borrowed_reader_canonical_bytes(unsigned), hashlib.sha256,
    ).hexdigest()
    return value


def _validate_codex_keeper_message(
    value, authkey, *, transaction_id, active_descriptor_sha256,
    keeper_binding_sha256, writer_generation, request_nonce,
    expected_sequence=None, allowed_states=None,
):
    fields = {
        "schema", "transaction_id", "active_descriptor_sha256",
        "keeper_binding_sha256", "writer_generation", "request_nonce",
        "sequence", "phase", "state", "body", "mac",
    }
    if not isinstance(value, dict) or set(value) != fields:
        raise RuntimeError("Codex keeper message schema differs")
    unsigned = {key: value[key] for key in fields - {"mac"}}
    expected_mac = hmac.new(
        authkey, _borrowed_reader_canonical_bytes(unsigned), hashlib.sha256,
    ).hexdigest()
    if (
        value.get("schema") != _CODEX_KEEPER_MESSAGE_V1_SCHEMA
        or value.get("transaction_id") != transaction_id
        or value.get("active_descriptor_sha256") != active_descriptor_sha256
        or value.get("keeper_binding_sha256") != keeper_binding_sha256
        or value.get("writer_generation") != writer_generation
        or value.get("request_nonce") != request_nonce
        or not isinstance(value.get("sequence"), int)
        or isinstance(value.get("sequence"), bool)
        or value["sequence"] < 0
        or (expected_sequence is not None and value["sequence"] != expected_sequence)
        or not isinstance(value.get("phase"), str) or not value["phase"]
        or not isinstance(value.get("state"), str) or not value["state"]
        or not isinstance(value.get("body"), dict)
        or not re.fullmatch(r"[0-9a-f]{64}", value.get("mac", ""))
        or not hmac.compare_digest(value["mac"], expected_mac)
        or (allowed_states is not None and value["state"] not in allowed_states)
    ):
        raise RuntimeError("Codex keeper message authority differs")
    return value


class _CodexKeeperProgressSender:
    def __init__(self, connection, authkey, context):
        self.connection = connection
        self.authkey = authkey
        self.context = dict(context)
        self.phase = "STARTED"
        self.sequence = 0
        self.lock = threading.Lock()
        self.stop_event = threading.Event()
        self.failed = False
        self.thread = None

    def _send(self, state, body=None):
        with self.lock:
            if self.failed:
                return False
            value = _codex_keeper_message(
                self.authkey, sequence=self.sequence, phase=self.phase,
                state=state, body=body, **self.context,
            )
            try:
                self.connection.send(value)
            except (BrokenPipeError, EOFError, OSError):
                self.failed = True
                return False
            self.sequence += 1
            return True

    def start(self):
        self._send("RECOVERY_STARTED")
        def heartbeat():
            while not self.stop_event.wait(_CODEX_KEEPER_PROGRESS_SECONDS):
                self._send("RECOVERY_PROGRESS", {"heartbeat": True})
        self.thread = threading.Thread(target=heartbeat, daemon=True)
        self.thread.start()

    def update(self, phase, body=None):
        if not isinstance(phase, str) or not phase:
            raise RuntimeError("Codex keeper progress phase is malformed")
        self.phase = phase
        self._send("RECOVERY_PROGRESS", body)

    def finish(self, state, body=None):
        self.stop_event.set()
        if self.thread is not None:
            self.thread.join(timeout=5.0)
        self.phase = "DONE"
        self._send(state, body)


_CODEX_KEEPER_ACTIVE_V2_FIELDS = frozenset({
    "schema", "state", "transaction_id", "writer_generation",
    "anchor_identity", "codex_root", "codex_root_identity",
    "plamen_root", "plamen_root_identity", "source_root",
    "source_root_identity", "source_manifest_sha256",
    "runtime_manifest_sha256", "adapter_manifest_sha256", "inverse_sha256",
    "emergency_sha256", "pipe", "pipe_instance_nonce", "authkey",
    "parent_pid", "parent_started_100ns", "principal", "interpreter",
    "interpreter_sha256", "script", "script_sha256", "recovery_argv",
    "recovery_argv_sha256",
})
_CODEX_KEEPER_BINDING_V1_FIELDS = frozenset({
    "schema", "transaction_id", "active_descriptor_sha256",
    "writer_generation", "anchor_identity", "pipe", "pipe_instance_nonce",
    "keeper_pid", "keeper_started_100ns", "keeper_parent_pid",
    "keeper_parent_started_100ns", "principal", "interpreter",
    "interpreter_sha256", "script", "script_sha256",
})


def _validate_codex_keeper_active_v2(value, raw, *, expected=None):
    if (
        not isinstance(value, dict) or set(value) != _CODEX_KEEPER_ACTIVE_V2_FIELDS
        or not isinstance(raw, bytes) or _strict_json_bytes(raw) != value
        or value.get("schema") != _CODEX_KEEPER_ACTIVE_V2_SCHEMA
        or value.get("state") != "KEEPER_ACTIVE"
        or not re.fullmatch(r"[0-9a-f]{32}", value.get("transaction_id", ""))
        or not isinstance(value.get("writer_generation"), str)
        or not value["writer_generation"]
        or not isinstance(value.get("anchor_identity"), dict)
        or any(not isinstance(value.get(name), str) or not value[name]
               for name in ("codex_root", "plamen_root", "source_root"))
        or any(not isinstance(value.get(name), dict) or not value[name]
               for name in ("codex_root_identity", "plamen_root_identity", "source_root_identity"))
        or any(not re.fullmatch(r"[0-9a-f]{64}", value.get(name, ""))
               for name in (
                   "source_manifest_sha256", "runtime_manifest_sha256",
                   "adapter_manifest_sha256", "inverse_sha256", "emergency_sha256",
                   "pipe_instance_nonce", "interpreter_sha256", "script_sha256",
                   "recovery_argv_sha256",
               ))
        or not isinstance(value.get("pipe"), str)
        or not value["pipe"].startswith(r"\\.\pipe\plamen-install-" + value["transaction_id"] + "-")
        or not re.fullmatch(r"[0-9a-f]{64}", value.get("authkey", ""))
        or not isinstance(value.get("parent_pid"), int)
        or isinstance(value.get("parent_pid"), bool) or value["parent_pid"] <= 0
        or not isinstance(value.get("parent_started_100ns"), int)
        or isinstance(value.get("parent_started_100ns"), bool)
        or value["parent_started_100ns"] <= 0
        or not isinstance(value.get("principal"), str)
        or not isinstance(value.get("interpreter"), str) or not value["interpreter"]
        or not isinstance(value.get("script"), str) or not value["script"]
        or not isinstance(value.get("recovery_argv"), list)
        or value.get("recovery_argv_sha256") != hashlib.sha256(
            _borrowed_reader_canonical_bytes(value.get("recovery_argv"))
        ).hexdigest()
    ):
        raise RuntimeError("Codex install active keeper descriptor is malformed")
    if expected is not None and (
        not isinstance(expected, dict)
        or any(value.get(key) != item for key, item in expected.items())
    ):
        raise RuntimeError("Codex install active keeper descriptor authority differs")
    return hashlib.sha256(raw).hexdigest()


def _codex_install_keeper_binding(
    descriptor, *, descriptor_sha256, process_pid, process_started_100ns,
    parent_pid, parent_started_100ns, anchor_identity,
):
    return {
        "schema": _CODEX_KEEPER_BINDING_V1_SCHEMA,
        "transaction_id": descriptor["transaction_id"],
        "active_descriptor_sha256": descriptor_sha256,
        "writer_generation": descriptor["writer_generation"],
        "anchor_identity": anchor_identity,
        "pipe": descriptor["pipe"],
        "pipe_instance_nonce": descriptor["pipe_instance_nonce"],
        "keeper_pid": process_pid,
        "keeper_started_100ns": process_started_100ns,
        "keeper_parent_pid": parent_pid,
        "keeper_parent_started_100ns": parent_started_100ns,
        "principal": descriptor["principal"],
        "interpreter": descriptor["interpreter"],
        "interpreter_sha256": descriptor["interpreter_sha256"],
        "script": descriptor["script"],
        "script_sha256": descriptor["script_sha256"],
    }


def _validate_codex_keeper_binding(value, raw, *, descriptor, expected=None):
    descriptor_raw = _borrowed_reader_canonical_bytes(descriptor)
    if (
        not isinstance(value, dict) or set(value) != _CODEX_KEEPER_BINDING_V1_FIELDS
        or not isinstance(raw, bytes) or _strict_json_bytes(raw) != value
        or value.get("schema") != _CODEX_KEEPER_BINDING_V1_SCHEMA
        or value.get("transaction_id") != descriptor.get("transaction_id")
        or value.get("active_descriptor_sha256")
        != hashlib.sha256(descriptor_raw).hexdigest()
        or value.get("writer_generation") != descriptor.get("writer_generation")
        or value.get("anchor_identity") != descriptor.get("anchor_identity")
        or value.get("pipe") != descriptor.get("pipe")
        or value.get("pipe_instance_nonce") != descriptor.get("pipe_instance_nonce")
        or not isinstance(value.get("keeper_pid"), int)
        or isinstance(value.get("keeper_pid"), bool) or value["keeper_pid"] <= 0
        or not isinstance(value.get("keeper_started_100ns"), int)
        or isinstance(value.get("keeper_started_100ns"), bool)
        or value["keeper_started_100ns"] <= 0
        or not isinstance(value.get("keeper_parent_pid"), int)
        or isinstance(value.get("keeper_parent_pid"), bool)
        or value["keeper_parent_pid"] <= 0
        or not isinstance(value.get("keeper_parent_started_100ns"), int)
        or isinstance(value.get("keeper_parent_started_100ns"), bool)
        or value["keeper_parent_started_100ns"] <= 0
        or any(value.get(name) != descriptor.get(name) for name in (
            "principal", "interpreter", "interpreter_sha256", "script", "script_sha256",
        ))
    ):
        raise RuntimeError("Codex install keeper binding authority differs")
    if expected is not None and (
        not isinstance(expected, dict)
        or any(value.get(key) != item for key, item in expected.items())
    ):
        raise RuntimeError("Codex install keeper binding process authority differs")
    return hashlib.sha256(raw).hexdigest()


def _start_codex_install_keeper(
    *, transaction_id, writer_handle, writer_generation, codex_home,
    plamen_root, source_root, descriptor_sha256, pipe, authkey,
    pipe_instance_nonce, binding_publisher,
):
    """Start the minimal out-of-process holder before COMMITTED publication."""
    if os.name != "nt":
        raise RuntimeError("Codex install keeper requires Windows handle transfer")
    inherited = _duplicate_install_writer_for_child(writer_handle)
    if (
        not isinstance(pipe, str)
        or not pipe.startswith(r"\\.\pipe\plamen-install-" + transaction_id + "-")
        or not isinstance(authkey, bytes)
        or len(authkey) != 32
        or not re.fullmatch(r"[0-9a-f]{64}", pipe_instance_nonce or "")
        or not callable(binding_publisher)
    ):
        raise RuntimeError("Codex install keeper channel authority is malformed")
    environment = {
        "COMSPEC": os.environ.get("COMSPEC", r"C:\Windows\System32\cmd.exe"),
        "HOME": str(Path(codex_home).parent),
        "USERPROFILE": str(Path(codex_home).parent),
        "PATH": os.path.dirname(sys.executable) + os.pathsep + os.environ.get("SYSTEMROOT", r"C:\Windows") + r"\System32",
        "PYTHONHASHSEED": "0", "PYTHONNOUSERSITE": "1",
        "PYTHONDONTWRITEBYTECODE": "1", "PYTHONPATH": "",
        "SYSTEMROOT": os.environ.get("SYSTEMROOT", r"C:\Windows"),
        "WINDIR": os.environ.get("WINDIR", r"C:\Windows"),
        "TEMP": str(Path(codex_home) / ".plamen-install-transactions" / transaction_id),
        "TMP": str(Path(codex_home) / ".plamen-install-transactions" / transaction_id),
    }
    startupinfo = subprocess.STARTUPINFO()
    startupinfo.lpAttributeList = {"handle_list": [inherited]}
    argv = [
        sys.executable, "-B", os.path.abspath(__file__),
        "--codex-install-keeper", transaction_id, str(inherited), pipe,
        authkey.hex(), writer_generation, str(codex_home),
        str(plamen_root), str(source_root),
        descriptor_sha256,
    ]
    process = None
    try:
        process = subprocess.Popen(
            argv, cwd=str(source_root), env=environment,
            stdin=subprocess.DEVNULL, stdout=subprocess.PIPE,
            stderr=subprocess.PIPE, text=True, close_fds=True,
            startupinfo=startupinfo,
        )
    finally:
        _borrowed_reader_close_native(inherited)
    # Windows pipe reads have no native timeout.  Read the one-line readiness
    # token on a daemon thread so a broken child cannot freeze every future
    # install while the parent retains the transaction writer.
    import queue as _queue
    import threading as _threading
    ready_queue = _queue.Queue(maxsize=1)
    def read_ready_line():
        try:
            ready_queue.put((process.stdout.readline().strip(), None))
        except BaseException as exc:
            ready_queue.put(("", exc))
    _threading.Thread(target=read_ready_line, daemon=True).start()
    try:
        ready, ready_error = ready_queue.get(timeout=60.0)
    except _queue.Empty:
        process.kill(); process.wait(timeout=30)
        raise RuntimeError("Codex install keeper readiness timed out")
    if ready_error is not None:
        process.kill(); process.wait(timeout=30)
        raise RuntimeError(
            "Codex install keeper readiness read failed: "
            f"{type(ready_error).__name__}:{ready_error}"
        )
    try:
        ready_identity = json.loads(ready)
    except (TypeError, ValueError):
        ready_identity = None
    if (
        not isinstance(ready_identity, dict)
        or set(ready_identity) != {
            "state", "pid", "started_100ns", "parent_pid",
            "parent_started_100ns",
        }
        or ready_identity.get("state") != "KEEPER_READY_V2"
        or any(
            not isinstance(ready_identity.get(name), int)
            or isinstance(ready_identity.get(name), bool)
            or ready_identity[name] <= 0
            for name in (
                "pid", "started_100ns", "parent_pid",
                "parent_started_100ns",
            )
        )
    ):
        stderr = process.stderr.read(4096)
        process.kill(); process.wait(timeout=30)
        raise RuntimeError("Codex install keeper did not acknowledge: " + stderr)
    redirector_started = _borrowed_reader_process_started_100ns(
        getattr(process, "_handle", None)
    )
    keeper_pid = ready_identity["pid"]
    keeper_started = ready_identity["started_100ns"]
    keeper_parent_pid = ready_identity["parent_pid"]
    keeper_parent_started = ready_identity["parent_started_100ns"]
    if (
        _borrowed_reader_parent_started_100ns(keeper_pid) != keeper_started
        or (
            keeper_pid == process.pid
            and (
                keeper_parent_pid != os.getpid()
                or keeper_parent_started
                != _borrowed_reader_process_started_100ns()
            )
        )
        or (
            keeper_pid != process.pid
            and (
                keeper_parent_pid != process.pid
                or keeper_parent_started != redirector_started
            )
        )
    ):
        process.kill(); process.wait(timeout=30)
        raise RuntimeError("Codex install keeper process identity differs")
    descriptor_authority, descriptor_raw = _codex_install_committed_read(
        Path(codex_home),
        (".plamen-install-transactions", transaction_id, "keeper-descriptor.json"),
        directory=False,
    )
    descriptor = _strict_json_bytes(descriptor_raw)
    _validate_codex_keeper_active_v2(descriptor, descriptor_raw)
    binding = _codex_install_keeper_binding(
        descriptor, descriptor_sha256=descriptor_sha256,
        process_pid=keeper_pid, process_started_100ns=keeper_started,
        parent_pid=keeper_parent_pid,
        parent_started_100ns=keeper_parent_started,
        anchor_identity=_borrowed_reader_handle_identity(writer_handle),
    )
    if (
        descriptor_authority.get("sha256") != descriptor_sha256
        or hashlib.sha256(descriptor_raw).hexdigest() != descriptor_sha256
        or descriptor.get("schema") != _CODEX_KEEPER_ACTIVE_V2_SCHEMA
        or descriptor.get("pipe_instance_nonce") != pipe_instance_nonce
    ):
        process.kill(); process.wait(timeout=30)
        raise RuntimeError("Codex install active keeper descriptor differs")
    binding_raw = _borrowed_reader_canonical_bytes(binding)
    _validate_codex_keeper_binding(binding, binding_raw, descriptor=descriptor)
    if binding_publisher(binding_raw) != binding_raw:
        process.kill(); process.wait(timeout=30)
        raise RuntimeError("Codex install keeper binding publisher differs")
    binding_sha256 = hashlib.sha256(binding_raw).hexdigest()
    from multiprocessing.connection import Client
    connection = Client(pipe, family="AF_PIPE", authkey=authkey)
    connection.send({
        "command": "BIND_V2", "transaction_id": transaction_id,
        "descriptor_sha256": descriptor_sha256,
        "binding_sha256": binding_sha256,
        "pipe_instance_nonce": pipe_instance_nonce,
    })
    if not connection.poll(30.0):
        connection.close()
        process.kill(); process.wait(timeout=30)
        raise RuntimeError("Codex install keeper binding acknowledgment timed out")
    try:
        binding_ack = connection.recv()
    except EOFError as exc:
        stderr = process.stderr.read(4096)
        connection.close()
        process.wait(timeout=30)
        raise RuntimeError(
            "Codex install keeper rejected binding: " + stderr
        ) from exc
    if binding_ack != {
        "state": "BOUND_V2", "transaction_id": transaction_id,
        "descriptor_sha256": descriptor_sha256,
        "binding_sha256": binding_sha256,
    }:
        raise RuntimeError("Codex install keeper binding acknowledgment differs")
    return {
        "process": process, "connection": connection, "pipe": pipe,
        "authkey": authkey.hex(), "transaction_id": transaction_id,
        "writer_generation": writer_generation, "activated": False,
        "descriptor_sha256": descriptor_sha256,
        "binding_sha256": binding_sha256,
        "pipe_instance_nonce": pipe_instance_nonce,
    }


def _release_codex_install_keeper(keeper):
    if keeper is None or keeper.get("activated"):
        return
    connection = keeper["connection"]
    connection.send({"command": "RELEASE_UNUSED", "transaction_id": keeper["transaction_id"]})
    if not connection.poll(30.0):
        raise RuntimeError("Codex install keeper release acknowledgment timed out")
    if connection.recv() != {"state": "RELEASED", "transaction_id": keeper["transaction_id"]}:
        raise RuntimeError("Codex install keeper release acknowledgment differs")
    connection.close()
    keeper["process"].wait(timeout=30)
    if keeper["process"].returncode != 0:
        raise RuntimeError("Codex install keeper release failed")


def _activate_codex_install_keeper(keeper, *, reason):
    if keeper is None or keeper.get("activated"):
        raise RuntimeError("Codex install keeper activation authority differs")
    keeper["connection"].send({
        "command": "ACTIVATE", "transaction_id": keeper["transaction_id"],
        "reason": str(reason)[:1000],
    })
    expected = {"state": "LOCK_HELD_MANUAL_RECOVERY_REQUIRED",
                "transaction_id": keeper["transaction_id"]}
    if not keeper["connection"].poll(30.0):
        raise RuntimeError("Codex install keeper activation acknowledgment timed out")
    if keeper["connection"].recv() != expected:
        raise RuntimeError("Codex install keeper activation acknowledgment differs")
    keeper["connection"].close(); keeper["activated"] = True


def _codex_install_keeper_descriptor(
    *, transaction_id, writer_generation, writer_handle, codex_home,
    plamen_root, source_root, receipt, emergency_raw, pipe, authkey,
):
    def root_identity(path):
        path = Path(path).absolute()
        authority, _names = _codex_install_committed_read(
            path.parent, (path.name,), directory=True,
        )
        return authority
    pipe_instance_nonce = secrets.token_hex(32)
    descriptor = {
        "schema": _CODEX_KEEPER_ACTIVE_V2_SCHEMA,
        "state": "KEEPER_ACTIVE",
        "transaction_id": transaction_id,
        "writer_generation": writer_generation,
        "anchor_identity": _borrowed_reader_handle_identity(writer_handle),
        "codex_root": str(codex_home),
        "codex_root_identity": root_identity(codex_home),
        "plamen_root": str(plamen_root),
        "plamen_root_identity": root_identity(plamen_root),
        "source_root": str(source_root),
        "source_root_identity": root_identity(source_root),
        "source_manifest_sha256": receipt["source_manifest_sha256"],
        "runtime_manifest_sha256": receipt["runtime_manifest_sha256"],
        "adapter_manifest_sha256": receipt["adapter_manifest_sha256"],
        "inverse_sha256": receipt["inverse_sha256"],
        "emergency_sha256": hashlib.sha256(emergency_raw).hexdigest(),
        "pipe": pipe,
        "pipe_instance_nonce": pipe_instance_nonce,
        "authkey": authkey.hex(),
        "parent_pid": os.getpid(),
        "parent_started_100ns": _borrowed_reader_process_started_100ns(),
        "principal": os.environ.get("USERNAME") or os.environ.get("USER") or "",
        "interpreter": os.path.abspath(sys.executable),
        "interpreter_sha256": _codex_install_committed_read(
            Path(sys.executable).parent, (Path(sys.executable).name,), directory=False,
            allow_stable_foreign_links=True,
        )[0]["sha256"],
        "script": os.path.abspath(__file__),
        "script_sha256": _codex_install_committed_read(
            Path(__file__).parent, (Path(__file__).name,), directory=False,
        )[0]["sha256"],
        "recovery_argv": [
            os.path.abspath(sys.executable), "-B", os.path.abspath(__file__),
            "--recover-codex-install", transaction_id,
        ],
    }
    descriptor["recovery_argv_sha256"] = hashlib.sha256(
        _borrowed_reader_canonical_bytes(descriptor["recovery_argv"])
    ).hexdigest()
    return descriptor


def _run_codex_install_keeper(argv):
    if len(argv) != 10 or argv[0] != "--codex-install-keeper":
        raise RuntimeError("Codex install keeper argv is malformed")
    (_flag, transaction_id, handle_raw, pipe, auth_hex, writer_generation,
     codex_raw, plamen_raw, source_raw, descriptor_sha256) = argv
    if not re.fullmatch(r"[0-9a-f]{32}", transaction_id):
        raise RuntimeError("Codex install keeper transaction is malformed")
    handle = int(handle_raw)
    if handle <= 0 or not re.fullmatch(r"[0-9a-f]{64}", descriptor_sha256):
        raise RuntimeError("Codex install keeper authority is malformed")
    _descriptor_authority, descriptor_raw = _codex_install_committed_read(
        Path(codex_raw),
        (".plamen-install-transactions", transaction_id, "keeper-descriptor.json"),
        directory=False,
    )
    descriptor = _strict_json_bytes(descriptor_raw)
    _validate_codex_keeper_active_v2(descriptor, descriptor_raw)
    active_interpreter = os.path.abspath(sys.executable)
    active_interpreter_authority, _active_interpreter_raw = (
        _codex_install_committed_read(
            Path(active_interpreter).parent,
            (Path(active_interpreter).name,),
            directory=False,
            allow_stable_foreign_links=True,
        )
    )
    if (
        hashlib.sha256(descriptor_raw).hexdigest() != descriptor_sha256
        or descriptor.get("schema") != _CODEX_KEEPER_ACTIVE_V2_SCHEMA
        or descriptor.get("state") != "KEEPER_ACTIVE"
        or descriptor.get("transaction_id") != transaction_id
        or descriptor.get("writer_generation") != writer_generation
        or descriptor.get("codex_root") != str(Path(codex_raw).absolute())
        or descriptor.get("plamen_root") != str(Path(plamen_raw).absolute())
        or descriptor.get("source_root") != str(Path(source_raw).absolute())
        or descriptor.get("pipe") != pipe
        or descriptor.get("authkey") != auth_hex
        or descriptor.get("interpreter") != active_interpreter
        or descriptor.get("interpreter_sha256")
        != active_interpreter_authority.get("sha256")
        or not re.fullmatch(r"[0-9a-f]{64}", descriptor.get("pipe_instance_nonce", ""))
        or descriptor.get("anchor_identity") != _borrowed_reader_handle_identity(handle)
    ):
        raise RuntimeError("Codex install keeper descriptor differs from inherited authority")
    from multiprocessing.connection import Listener
    listener = Listener(pipe, family="AF_PIPE", authkey=bytes.fromhex(auth_hex))
    sys.stdout.write(json.dumps({
        "state": "KEEPER_READY_V2",
        "pid": os.getpid(),
        "started_100ns": _borrowed_reader_process_started_100ns(),
        "parent_pid": os.getppid(),
        "parent_started_100ns": _borrowed_reader_parent_started_100ns(
            os.getppid()
        ),
    }, sort_keys=True, separators=(",", ":")) + "\n")
    sys.stdout.flush()
    connection = None
    try:
        connection = listener.accept()
        bound = connection.recv()
        if (
            not isinstance(bound, dict)
            or set(bound) != {
                "command", "transaction_id", "descriptor_sha256",
                "binding_sha256", "pipe_instance_nonce",
            }
            or bound.get("command") != "BIND_V2"
            or bound.get("transaction_id") != transaction_id
            or bound.get("descriptor_sha256") != descriptor_sha256
            or bound.get("pipe_instance_nonce") != descriptor["pipe_instance_nonce"]
            or not re.fullmatch(r"[0-9a-f]{64}", bound.get("binding_sha256", ""))
        ):
            raise RuntimeError("Codex install keeper bind differs")
        binding_authority, binding_raw = _codex_install_committed_read(
            Path(codex_raw),
            (".plamen-install-transactions", transaction_id, "keeper-binding.json"),
            directory=False,
        )
        binding = _strict_json_bytes(binding_raw)
        _validate_codex_keeper_binding(binding, binding_raw, descriptor=descriptor)
        binding_fields = {
            "schema", "transaction_id", "active_descriptor_sha256",
            "writer_generation", "anchor_identity", "pipe",
            "pipe_instance_nonce", "keeper_pid", "keeper_started_100ns",
            "keeper_parent_pid", "keeper_parent_started_100ns", "principal",
            "interpreter", "interpreter_sha256", "script", "script_sha256",
        }
        parent_pid = os.getppid()
        if (
            set(binding) != binding_fields
            or binding.get("schema") != _CODEX_KEEPER_BINDING_V1_SCHEMA
            or binding.get("transaction_id") != transaction_id
            or binding.get("active_descriptor_sha256") != descriptor_sha256
            or binding.get("writer_generation") != writer_generation
            or binding.get("anchor_identity") != _borrowed_reader_handle_identity(handle)
            or binding.get("pipe") != pipe
            or binding.get("pipe_instance_nonce") != descriptor["pipe_instance_nonce"]
            or binding.get("keeper_pid") != os.getpid()
            or binding.get("keeper_started_100ns")
            != _borrowed_reader_process_started_100ns()
            or binding.get("keeper_parent_pid") != parent_pid
            or binding.get("keeper_parent_started_100ns")
            != _borrowed_reader_parent_started_100ns(parent_pid)
            or binding.get("principal") != descriptor["principal"]
            or binding.get("interpreter") != descriptor["interpreter"]
            or binding.get("interpreter_sha256") != descriptor["interpreter_sha256"]
            or binding.get("script") != descriptor["script"]
            or binding.get("script_sha256") != descriptor["script_sha256"]
            or binding_authority.get("sha256") != bound["binding_sha256"]
            or hashlib.sha256(binding_raw).hexdigest() != bound["binding_sha256"]
        ):
            raise RuntimeError("Codex install keeper binding authority differs")
        connection.send({
            "state": "BOUND_V2", "transaction_id": transaction_id,
            "descriptor_sha256": descriptor_sha256,
            "binding_sha256": bound["binding_sha256"],
        })
        parent_channel_eof = False
        try:
            command = connection.recv()
        except EOFError:
            parent_channel_eof = True
            command = {"command": "ACTIVATE", "transaction_id": transaction_id,
                       "reason": "PARENT_CHANNEL_EOF"}
        if command.get("transaction_id") != transaction_id:
            raise RuntimeError("Codex install keeper command transaction differs")
        if command.get("command") == "RELEASE_UNUSED":
            connection.send({"state": "RELEASED", "transaction_id": transaction_id})
            _borrowed_reader_close_native(handle); handle = None
            return 0
        if command.get("command") != "ACTIVATE":
            raise RuntimeError("Codex install keeper command is unsupported")
        if not parent_channel_eof:
            connection.send({"state": "LOCK_HELD_MANUAL_RECOVERY_REQUIRED",
                             "transaction_id": transaction_id})
        connection.close(); connection = None
        recovery = listener.accept()
        request = recovery.recv()
        if request != {"command": "RECOVER", "transaction_id": transaction_id,
                       "descriptor_sha256": descriptor_sha256}:
            raise RuntimeError("Codex install keeper recovery request differs")
        try:
            result = _recover_codex_package_transaction(
                transaction_id, codex_home=codex_raw,
                _borrowed_writer=(handle, writer_generation, lambda: None),
            )
        except BaseException as exc:
            recovery.send({
                "state": "RECOVERY_FAILED", "transaction_id": transaction_id,
                "error": f"{type(exc).__name__}:{str(exc)[:2000]}",
            })
            recovery.close()
            return 1
        recovery.send({"state": "RECOVERED", "transaction_id": transaction_id,
                       "result": result})
        recovery.close()
        _borrowed_reader_close_native(handle); handle = None
        return 0
    finally:
        if connection is not None: connection.close()
        listener.close()
        if handle is not None: _borrowed_reader_close_native(handle)


def _assert_borrowed_install_writer_authority(
    writer_handle, codex_home, receipt,
):
    """Prove that one supplied anchor handle retains the exclusive writer."""
    codex_home = Path(codex_home).absolute()
    handle_authority = _borrowed_reader_handle_identity(writer_handle)
    if (
        not isinstance(receipt, dict)
        or receipt.get("lock_identity") != [
            handle_authority.get("volume"), handle_authority.get("file_id"),
        ]
        or handle_authority.get("reparse_tag") != 0
        or handle_authority.get("links") != 1
    ):
        raise RuntimeError("borrowed smoke writer anchor authority differs")
    anchor = codex_home / _CODEX_INSTALL_ANCHOR
    if os.name == "nt":
        import ctypes
        from ctypes import wintypes

        class _IoStatusBlock(ctypes.Structure):
            _fields_ = [
                ("status", ctypes.c_void_p),
                ("information", ctypes.c_size_t),
            ]

        ntdll = ctypes.WinDLL("ntdll", use_last_error=True)
        query = ntdll.NtQueryInformationFile
        query.argtypes = [
            wintypes.HANDLE, ctypes.POINTER(_IoStatusBlock), ctypes.c_void_p,
            wintypes.ULONG, wintypes.ULONG,
        ]
        query.restype = wintypes.LONG
        io_status = _IoStatusBlock()
        access = wintypes.DWORD()
        status = query(
            wintypes.HANDLE(int(writer_handle)), ctypes.byref(io_status),
            ctypes.byref(access), ctypes.sizeof(access),
            8,  # FileAccessInformation
        )
        granted_access = access.value
        # GENERIC_WRITE is mapped by CreateFile to these file-specific rights.
        required_write = 0x00000002 | 0x00000004 | 0x00000010 | 0x00000100
        if status < 0 or granted_access & required_write != required_write:
            raise RuntimeError("borrowed smoke handle is not the install writer")

        kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
        kernel32.CreateFileW.restype = wintypes.HANDLE
        # Windows share rights are independent and checked bidirectionally.
        # Request each access category separately while our probes themselves
        # share all categories.  Any nonzero share bit on the retained handle
        # lets the corresponding probe open; a true share-zero writer makes all
        # three fail specifically with ERROR_SHARING_VIOLATION.
        for desired_access in (
            0x80000000,  # GENERIC_READ / FILE_SHARE_READ
            0x40000000,  # GENERIC_WRITE / FILE_SHARE_WRITE
            0x00010000,  # DELETE / FILE_SHARE_DELETE
        ):
            probe = kernel32.CreateFileW(
                wintypes.LPCWSTR(str(anchor)), wintypes.DWORD(desired_access),
                wintypes.DWORD(0x00000001 | 0x00000002 | 0x00000004),
                None, wintypes.DWORD(3),
                wintypes.DWORD(0x00000080 | 0x00200000 | 0x02000000), None,
            )
            if probe != wintypes.HANDLE(-1).value:
                kernel32.CloseHandle(probe)
                raise RuntimeError("borrowed smoke writer lease is not exclusive")
            if ctypes.get_last_error() != 32:  # ERROR_SHARING_VIOLATION
                raise RuntimeError("borrowed smoke writer lease cannot be proven")
    else:
        import errno
        import fcntl

        flags = fcntl.fcntl(writer_handle, fcntl.F_GETFL)
        if flags & os.O_ACCMODE != os.O_RDWR:
            raise RuntimeError("borrowed smoke handle is not the install writer")
        path_stat = os.lstat(anchor)
        handle_stat = os.fstat(writer_handle)
        if (
            path_stat.st_dev != handle_stat.st_dev
            or path_stat.st_ino != handle_stat.st_ino
            or path_stat.st_nlink != 1
        ):
            raise RuntimeError("borrowed smoke writer anchor authority differs")
        probe = os.open(str(anchor), os.O_RDONLY)
        try:
            try:
                fcntl.flock(probe, fcntl.LOCK_SH | fcntl.LOCK_NB)
            except OSError as exc:
                if exc.errno not in {errno.EACCES, errno.EAGAIN}:
                    raise RuntimeError(
                        "borrowed smoke writer lease cannot be proven"
                    ) from exc
            else:
                fcntl.flock(probe, fcntl.LOCK_UN)
                raise RuntimeError("borrowed smoke writer lease is not exclusive")
        finally:
            os.close(probe)
    return handle_authority


def _run_borrowed_install_child(
    *, dispatcher, argv, command_kind, cwd, environment, timeout=180,
):
    """Run one exact read-only installed child beneath the retained writer."""
    if (
        not isinstance(dispatcher, _CodexInstallMutationDispatcher)
        or dispatcher.closed
        or dispatcher._installer_pid != os.getpid()
        or dispatcher._installer_started_100ns
        != _borrowed_reader_process_started_100ns()
        or not isinstance(argv, (list, tuple))
        or len(argv) < 3
    ):
        raise RuntimeError("borrowed reader issue authority is malformed")
    transaction_id = dispatcher.transaction_id
    writer_generation = dispatcher.writer_generation
    writer_handle = dispatcher.writer_handle
    codex_home = dispatcher.codex_home
    plamen_home = dispatcher.plamen_root
    if writer_generation != "public:" + transaction_id:
        raise RuntimeError("borrowed smoke writer generation is not transaction-bound")
    interpreter = Path(argv[0]).absolute()
    script = Path(argv[2]).absolute()
    if argv[1] != "-B" or command_kind not in {
        "FRONT_VERSION", "FRONT_HELP", "FRONT_DOCTOR", "FRONT_DETECT", "DRIVER_VERSION",
        "DRIVER_HELP", "DRIVER_DETECT", "CONFIG_CREATE", "CONFIG_RESUME",
        "CONFIG_OVERWRITE_REFUSAL", "SC_WIZARD_DRY_START",
        "SC_WIZARD_DRY_RESUME", "L1_WIZARD_DRY_START",
        "L1_WIZARD_DRY_RESUME",
    }:
        raise RuntimeError("borrowed reader command authority is unsupported")
    codex_home = Path(codex_home).absolute()
    plamen_home = Path(plamen_home).absolute()
    receipt_path = codex_home / _CODEX_INSTALL_RECEIPT
    _receipt_descriptor, receipt_raw = _codex_install_committed_read(
        codex_home, (_CODEX_INSTALL_RECEIPT,), directory=False,
    )
    receipt = _strict_json_bytes(receipt_raw)
    if (
        receipt.get("state") != "COMMITTED"
        or receipt.get("transaction_id") != transaction_id
        or receipt.get("terminal_evidence") is not None
    ):
        raise RuntimeError("borrowed child requires exact committed transaction")
    _assert_borrowed_install_writer_authority(
        writer_handle, codex_home, receipt,
    )
    capability_read, capability_write = os.pipe()
    ack_read, ack_write = os.pipe()
    child_anchor = _borrowed_reader_duplicate_for_child(writer_handle)
    child_handles = []
    process = None
    nonce = uuid.uuid4().hex
    try:
        import msvcrt
        capability_native = msvcrt.get_osfhandle(capability_read) if os.name == "nt" else capability_read
        ack_native = msvcrt.get_osfhandle(ack_write) if os.name == "nt" else ack_write
        child_handles = [int(child_anchor), int(capability_native), int(ack_native)]
        for value in (capability_read, ack_write):
            os.set_inheritable(value, True)
        child_environment = {str(key): str(value) for key, value in environment.items()}
        child_environment.update({
            _PLAMEN_BORROWED_READER_ENV[0]: str(child_anchor),
            _PLAMEN_BORROWED_READER_ENV[1]: str(capability_native),
            _PLAMEN_BORROWED_READER_ENV[2]: str(ack_native),
        })
        startupinfo = None
        popen_kwargs = {}
        if os.name == "nt":
            startupinfo = subprocess.STARTUPINFO()
            startupinfo.lpAttributeList = {"handle_list": child_handles}
            popen_kwargs["startupinfo"] = startupinfo
        process = subprocess.Popen(
            [str(item) for item in argv], cwd=os.path.abspath(str(cwd)),
            env=child_environment, stdin=subprocess.DEVNULL,
            stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=False,
            close_fds=True, **popen_kwargs,
        )
        os.close(capability_read); capability_read = None
        os.close(ack_write); ack_write = None
        redirector_started = _borrowed_reader_process_started_100ns(
            getattr(process, "_handle", None)
        )
        import queue as _queue
        import threading as _threading
        ready_queue = _queue.Queue(maxsize=1)
        def read_child_ready():
            try:
                ready_queue.put((process.stdout.readline(), None))
            except BaseException as exc:
                ready_queue.put((b"", exc))
        _threading.Thread(target=read_child_ready, daemon=True).start()
        try:
            child_ready_raw, child_ready_error = ready_queue.get(timeout=30.0)
        except _queue.Empty:
            raise RuntimeError("borrowed reader child readiness timed out")
        if child_ready_error is not None:
            raise RuntimeError(
                "borrowed reader child readiness failed: "
                f"{type(child_ready_error).__name__}:{child_ready_error}"
            )
        child_ready = _strict_json_bytes(child_ready_raw)
        if (
            not isinstance(child_ready, dict)
            or set(child_ready) != {
                "schema", "pid", "started_100ns", "parent_pid",
                "parent_started_100ns",
            }
            or child_ready.get("schema")
            != "plamen.borrowed_install_reader.ready.v1"
        ):
            raise RuntimeError("borrowed reader child readiness differs")
        child_pid = child_ready.get("pid")
        child_started = child_ready.get("started_100ns")
        child_parent_pid = child_ready.get("parent_pid")
        child_parent_started = child_ready.get("parent_started_100ns")
        if (
            any(
                not isinstance(value, int) or isinstance(value, bool)
                or value <= 0
                for value in (
                    child_pid, child_started, child_parent_pid,
                    child_parent_started,
                )
            )
            or _borrowed_reader_parent_started_100ns(child_pid)
            != child_started
            or (
                child_pid == process.pid
                and (
                    child_parent_pid != os.getpid()
                    or child_parent_started
                    != _borrowed_reader_process_started_100ns()
                )
            )
            or (
                child_pid != process.pid
                and (
                    child_parent_pid != process.pid
                    or child_parent_started != redirector_started
                )
            )
        ):
            raise RuntimeError("borrowed reader child process identity differs")
        issued = time.time_ns()
        def native_identity(path):
            descriptor, _raw = _codex_install_committed_read(
                path.parent, (path.name,), directory=False,
                allow_stable_foreign_links=path == interpreter,
            )
            value = dict(descriptor)
            value["path"] = str(path)
            return value
        interpreter_authority = native_identity(interpreter)
        script_authority = native_identity(script)
        def capability_identity(value):
            return {
                "path": value["path"], "size": value["size"],
                "sha256": value["sha256"],
            }
        cwd_path = Path(cwd).absolute()
        cwd_authority, _cwd_names = _codex_install_committed_read(
            cwd_path.parent, (cwd_path.name,), directory=True,
        )
        environment_rows = [
            [str(key), str(value)] for key, value in sorted(environment.items())
        ]
        normalized_argv = [str(interpreter), "-B", str(script), *[str(item) for item in argv[3:]]]
        unsigned = {
            "schema": _PLAMEN_BORROWED_READER_SCHEMA, "nonce": nonce,
            "issued_ns": issued, "expires_ns": issued + int(timeout * 1_000_000_000),
            "parent_pid": child_parent_pid,
            "parent_started_100ns": child_parent_started,
            "child_pid": child_pid, "child_started_100ns": child_started,
            "writer_generation": writer_generation, "transaction_id": transaction_id,
            "anchor_identity": _borrowed_reader_handle_identity(writer_handle),
            "receipt": {"path": str(receipt_path), "state": receipt["state"],
                        "transaction_id": receipt["transaction_id"], "size": len(receipt_raw),
                        "sha256": hashlib.sha256(receipt_raw).hexdigest()},
            "codex_home": str(codex_home), "plamen_home": str(plamen_home),
            "installed_generation": transaction_id,
            "source_manifest_sha256": receipt["source_manifest_sha256"],
            "combined_manifest_sha256": receipt["source_manifest_sha256"],
            "interpreter": capability_identity(interpreter_authority),
            "script": capability_identity(script_authority),
            "argv": normalized_argv,
            "argv_sha256": hashlib.sha256(_borrowed_reader_canonical_bytes(normalized_argv)).hexdigest(),
            "cwd": os.path.abspath(str(cwd)), "cwd_authority": cwd_authority,
            "environment": environment_rows,
            "environment_sha256": _borrowed_reader_environment_sha256(environment),
            "command_kind": command_kind, "mode": "READ_ONLY_ADMISSION",
            "expected": {"allowed_rc": [0], "stdout": "CAPTURE", "stderr": "CAPTURE"},
            "inherited_handles": {
                "anchor": child_anchor, "capability": int(capability_native),
                "ack": int(ack_native),
            },
            "one_use": True, "nested_child_authority": False,
        }
        capability = dict(unsigned)
        capability["signature"] = hashlib.sha256(_borrowed_reader_canonical_bytes(unsigned)).hexdigest()
        if set(capability) != _PLAMEN_BORROWED_READER_FIELDS:
            raise RuntimeError("borrowed reader issuer field set differs")
        raw = _borrowed_reader_canonical_bytes(capability)
        offset = 0
        while offset < len(raw):
            count = os.write(capability_write, raw[offset:])
            if count <= 0:
                raise RuntimeError("borrowed capability write failed")
            offset += count
        os.close(capability_write); capability_write = None
        stdout, stderr = process.communicate(timeout=timeout)
        acknowledgment_raw = os.read(ack_read, 65536)
        if process.returncode not in unsigned["expected"]["allowed_rc"]:
            raise RuntimeError(
                "borrowed installed child failed: "
                + repr({
                    "returncode": process.returncode,
                    "stdout_sha256": hashlib.sha256(stdout).hexdigest(),
                    "stderr_sha256": hashlib.sha256(stderr).hexdigest(),
                    "stdout": stdout[-1000:], "stderr": stderr[-4000:],
                    "acknowledgment_size": len(acknowledgment_raw),
                    "acknowledgment_sha256": hashlib.sha256(
                        acknowledgment_raw
                    ).hexdigest(),
                })
            )
        acknowledgment = _strict_json_bytes(acknowledgment_raw)
        if acknowledgment != {
            "schema": "plamen.borrowed_install_reader.ack.v1", "nonce": nonce,
            "pid": child_pid, "started_100ns": child_started,
            "anchor_identity": unsigned["anchor_identity"], "state": "CONSUMED",
        }:
            raise RuntimeError("borrowed reader acknowledgment differs")
        return {
            "argv": normalized_argv, "argv_sha256": unsigned["argv_sha256"],
            "command_kind": command_kind, "nonce": nonce, "pid": child_pid,
            "started_100ns": child_started, "returncode": process.returncode,
            "stdout": stdout, "stderr": stderr, "acknowledged": True,
            "anchor_identity": unsigned["anchor_identity"],
            "parent_pid": unsigned["parent_pid"],
            "parent_started_100ns": unsigned["parent_started_100ns"],
            "process_creation_identity": {
                "pid": child_pid, "started_100ns": child_started,
                "parent_pid": unsigned["parent_pid"],
                "parent_started_100ns": unsigned["parent_started_100ns"],
            },
            "environment": environment_rows,
            "environment_sha256": unsigned["environment_sha256"],
            "executable_authority": interpreter_authority,
            "interpreter_authority": interpreter_authority,
            "script_authority": script_authority,
            "cwd_authority": unsigned["cwd_authority"],
            "provider_invocations": 0, "network_invocations": 0,
            "audit_worker_invocations": 0,
        }
    except BaseException:
        if process is not None and process.poll() is None:
            process.kill()
            process.wait(timeout=30)
        raise
    finally:
        for descriptor in (
            capability_read, capability_write, ack_read, ack_write,
        ):
            if descriptor is not None:
                try: os.close(descriptor)
                except OSError: pass
        try: _borrowed_reader_close_native(child_anchor)
        except OSError: pass


def _codex_install_child_environment(codex_home):
    home = str(Path(codex_home).parent)
    system_root = os.environ.get("SYSTEMROOT", r"C:\Windows")
    return {
        "COMSPEC": os.environ.get("COMSPEC", system_root + r"\System32\cmd.exe"),
        "HOME": home, "USERPROFILE": home,
        "PATH": os.path.dirname(sys.executable) + os.pathsep + system_root + r"\System32",
        "PYTHONHASHSEED": "0", "PYTHONNOUSERSITE": "1",
        "PYTHONDONTWRITEBYTECODE": "1", "PYTHONPATH": "",
        "SYSTEMROOT": system_root, "WINDIR": system_root,
        "TEMP": str(Path(codex_home) / ".plamen-install-transactions"),
        "TMP": str(Path(codex_home) / ".plamen-install-transactions"),
        "PLAMEN_PROVIDER_INVOCATIONS": "0",
        "PLAMEN_NETWORK_DISABLED": "1",
        "PLAMEN_AUDIT_WORKERS_DISABLED": "1",
    }


def _run_codex_install_integrated_smoke(
    *, dispatcher, transaction_id, writer_handle, writer_generation,
    codex_home, plamen_root, transaction_components, failpoint=None,
):
    """Execute every private no-provider product route beneath one writer."""
    script = Path(plamen_root) / "plamen.py"
    driver = Path(plamen_root) / "scripts" / "plamen_driver.py"
    environment = _codex_install_child_environment(codex_home)
    smoke_components = transaction_components + ("smoke",)
    dispatcher.mkdir(dispatcher.address("codex", smoke_components))
    evidence_components = smoke_components + ("evidence",)
    dispatcher.mkdir(dispatcher.address("codex", evidence_components))
    route_occurrences = {}
    projects = {}
    for pipeline in ("sc", "l1"):
        components = smoke_components + (pipeline + "-project",)
        dispatcher.mkdir(dispatcher.address("codex", components))
        dispatcher.mkdir(
            dispatcher.address("codex", components + (".scratchpad",))
        )
        projects[pipeline] = (
            Path(codex_home).joinpath(*components), components,
        )

    def run(kind, arguments, *, cwd, target_script=None):
        route = kind.lower().replace("driver_", "direct_")
        _codex_install_contract_hook(failpoint, "before_smoke_" + route)
        target_script = target_script or script
        result = _run_borrowed_install_child(
            dispatcher=dispatcher,
            argv=[sys.executable, "-B", str(target_script), *map(str, arguments)],
            command_kind=kind,
            cwd=cwd,
            environment=environment,
            timeout=240,
        )
        occurrence = route_occurrences.get(kind, 0)
        route_occurrences[kind] = occurrence + 1
        stem = f"{kind.lower()}-{occurrence:03d}"
        raw_evidence = {}
        for stream_name in ("stdout", "stderr"):
            components = evidence_components + (stem + "." + stream_name + ".bin",)
            address = dispatcher.address("codex", components)
            dispatcher.exclusive_bytes(address, result[stream_name])
            raw_evidence[stream_name] = {
                "path": str(Path(codex_home).joinpath(*components)),
                "authority": dispatcher.make_readonly(address),
            }
        if kind.startswith(("FRONT_", "DRIVER_")):
            payload = {
                "schema": "plamen.installed_route.result.v1",
                "command_kind": kind,
                "stdout_sha256": hashlib.sha256(result["stdout"]).hexdigest(),
                "stderr_sha256": hashlib.sha256(result["stderr"]).hexdigest(),
                "provider_invocations": 0,
            }
        else:
            try:
                payload = _strict_json_bytes(result["stdout"])
            except BaseException as exc:
                raise RuntimeError("integrated install smoke output is noncanonical") from exc
        if payload.get("provider_invocations") != 0:
            raise RuntimeError("integrated install smoke crossed provider boundary")
        sealed = {
            "command_kind": kind,
            "route_kind": route,
            "transaction_stage": "COMMITTED_PRE_TERMINAL",
            "argv": result["argv"],
            "argv_sha256": result["argv_sha256"],
            "pid": result["pid"],
            "parent_pid": result["parent_pid"],
            "started_100ns": result["started_100ns"],
            "process_creation_identity": result["process_creation_identity"],
            "environment": result["environment"],
            "environment_sha256": result["environment_sha256"],
            "executable_authority": result["executable_authority"],
            "interpreter_authority": result["interpreter_authority"],
            "script_authority": result["script_authority"],
            "cwd_authority": result["cwd_authority"],
            "returncode": result["returncode"],
            "stdout_size": len(result["stdout"]),
            "stdout_sha256": hashlib.sha256(result["stdout"]).hexdigest(),
            "stdout": result["stdout"].decode("utf-8", "strict"),
            "stderr_size": len(result["stderr"]),
            "stderr_sha256": hashlib.sha256(result["stderr"]).hexdigest(),
            "stderr": result["stderr"].decode("utf-8", "strict"),
            "stdout_path": raw_evidence["stdout"]["path"],
            "stdout_authority": raw_evidence["stdout"]["authority"],
            "stderr_path": raw_evidence["stderr"]["path"],
            "stderr_authority": raw_evidence["stderr"]["authority"],
            "parsed_result": payload,
            "provider_invocations": result["provider_invocations"],
            "network_invocations": result["network_invocations"],
            "audit_worker_invocations": result["audit_worker_invocations"],
        }
        _codex_install_contract_hook(failpoint, "after_smoke_" + route)
        return sealed

    results = []
    sc_project = projects["sc"][0]
    results.extend((
        run("FRONT_VERSION", ["--version"], cwd=sc_project),
        run("FRONT_HELP", ["--help"], cwd=sc_project),
        run("FRONT_DOCTOR", ["doctor"], cwd=sc_project),
        run("FRONT_DETECT", ["--detect-language", sc_project], cwd=sc_project),
        run("DRIVER_VERSION", ["--version"], cwd=sc_project, target_script=driver),
        run("DRIVER_HELP", ["--help"], cwd=sc_project, target_script=driver),
        run("DRIVER_DETECT", ["--detect-language", sc_project], cwd=sc_project, target_script=driver),
    ))
    for pipeline in ("sc", "l1"):
        project, project_components = projects[pipeline]
        config = project / ".scratchpad" / "config.json"
        config_components = project_components + (".scratchpad", "config.json")
        config_address = dispatcher.address("codex", config_components)
        config_event = dispatcher._authorize(
            "EXTERNAL_SMOKE", config_address, expected_old=None,
            expected_new={"kind": "file", "links": 1, "reparse_tag": 0},
        )
        try:
            results.append(run(
                "CONFIG_CREATE",
                ["config", "--create", project, pipeline, "light", "evm" if pipeline == "sc" else "go", "codex"],
                cwd=project,
            ))
            dispatcher._complete(config_event, config_address)
        except BaseException:
            if config_event["state"] == "AUTHORIZED":
                config_event["state"] = "FAILED"
                dispatcher._release_event(config_event)
            raise
        before = dispatcher._current(dispatcher.address("codex", config_components))
        if before is None:
            raise RuntimeError("integrated install config creation did not publish")
        if pipeline == "sc":
            results.append(run(
                "CONFIG_RESUME", ["config", "--resume", config], cwd=project,
            ))
            results.append(run(
                "CONFIG_OVERWRITE_REFUSAL",
                ["config", "--overwrite-refusal", project, pipeline, "light", "evm", "codex"],
                cwd=project,
            ))
            if dispatcher._current(dispatcher.address("codex", config_components)) != before:
                raise RuntimeError("integrated overwrite refusal changed config authority")
            results.append(run(
                "SC_WIZARD_DRY_START",
                ["wizard", "--dry-run", "--codex", config], cwd=project,
            ))
            results.append(run(
                "SC_WIZARD_DRY_RESUME",
                ["wizard", "--dry-run", "--codex", "--resume", config], cwd=project,
            ))
        else:
            results.append(run(
                "L1_WIZARD_DRY_START",
                ["l1", "wizard", "--dry-run", "--codex", config], cwd=project,
            ))
            results.append(run(
                "L1_WIZARD_DRY_RESUME",
                ["l1", "wizard", "--dry-run", "--codex", "--resume", config], cwd=project,
            ))
    expected = {
        "FRONT_VERSION", "FRONT_HELP", "FRONT_DOCTOR", "FRONT_DETECT",
        "DRIVER_VERSION", "DRIVER_HELP", "DRIVER_DETECT",
        "CONFIG_CREATE", "CONFIG_RESUME", "CONFIG_OVERWRITE_REFUSAL",
        "SC_WIZARD_DRY_START", "SC_WIZARD_DRY_RESUME",
        "L1_WIZARD_DRY_START", "L1_WIZARD_DRY_RESUME",
    }
    if {row["command_kind"] for row in results} != expected or len(results) != 15:
        raise RuntimeError("integrated install smoke kind roster differs")
    return results


def _installed_runtime_root():
    """Return identity-bound installed authority, never a lexical decision."""
    module_address = Path(__file__)
    # Windows launchers expand USERPROFILE; POSIX launchers and installers use
    # HOME. Requiring the Windows-only variable on Linux/macOS silently
    # bypassed installed-runtime admission and made Doctor fall back to
    # ambient backend discovery.
    home_variable = "USERPROFILE" if sys.platform == "win32" else "HOME"
    user_root = os.environ.get(home_variable)
    if not isinstance(user_root, str) or not user_root:
        return None
    installed_address = Path(user_root) / ".plamen"
    try:
        module_authority, module_raw = _codex_install_committed_descriptor(
            module_address.parent, (module_address.name,), return_raw=True,
        )
        installed_authority, installed_raw = _codex_install_committed_descriptor(
            installed_address, (module_address.name,), return_raw=True,
        )
    except (FileNotFoundError, OSError):
        return None
    identity_fields = (
        "device", "inode", "attributes", "reparse_tag", "links", "size",
        "sha256", "streams", "name",
    )
    if (
        module_raw != installed_raw
        or module_authority.get("links") != 1
        or installed_authority.get("links") != 1
        or module_authority.get("reparse_tag") != 0
        or installed_authority.get("reparse_tag") != 0
        or module_authority.get("attributes", 0) & 0x400
        or installed_authority.get("attributes", 0) & 0x400
        or any(module_authority.get(key) != installed_authority.get(key)
               for key in identity_fields)
    ):
        return None
    return {
        "address": installed_address,
        "module_authority": module_authority,
        "installed_authority": installed_authority,
    }


def _admit_installed_runtime_before_bootstrap(
    _issue_capability=_issue_codex_install_admission_capability,
):
    """Acquire the installed runtime reader before bootstrap/local imports."""
    global _CODEX_INSTALL_READER, _CODEX_INSTALL_READER_COMMAND_KIND
    global _CODEX_INSTALL_ADMISSION
    installed_authority = _installed_runtime_root()
    if installed_authority is None:
        return
    installed = installed_authority["address"]
    args = [item.lower() for item in sys.argv[1:]]
    if args and args[0] in {"--codex-install-keeper", "--recover-codex-install"}:
        return
    if args and args[0] == "install" and "--codex" in args:
        return
    discovery = bool(args) and args[0] in {
        "help", "--help", "-h", "version", "--version"
    }
    home_variable = "USERPROFILE" if sys.platform == "win32" else "HOME"
    user_root = os.environ.get(home_variable)
    if not isinstance(user_root, str) or not user_root:
        raise RuntimeError("installed admission user root is unavailable")
    codex_home = Path(user_root) / ".codex"
    receipt_path = codex_home / _CODEX_INSTALL_RECEIPT
    anchor_path = codex_home / _CODEX_INSTALL_ANCHOR
    if discovery:
        try:
            _codex_install_committed_descriptor(
                codex_home, (_CODEX_INSTALL_ANCHOR,),
            )
            anchor_present = True
        except (FileNotFoundError, OSError):
            anchor_present = False
        try:
            _codex_install_committed_descriptor(
                codex_home, (_CODEX_INSTALL_RECEIPT,),
            )
            receipt_present = True
        except (FileNotFoundError, OSError):
            receipt_present = False
        if not anchor_present and not receipt_present:
            return
    try:
        borrowed = _consume_borrowed_install_reader(
            installed=installed,
            codex_home=codex_home,
            command_kinds={
                "FRONT_VERSION": lambda argv: [item.lower() for item in argv] in (["version"], ["--version"]),
                "FRONT_HELP": lambda argv: [item.lower() for item in argv] in (["help"], ["--help"], ["-h"]),
                "FRONT_DOCTOR": lambda argv: [item.lower() for item in argv] == ["doctor"],
                "FRONT_DETECT": lambda argv: len(argv) == 2 and argv[0].lower() == "--detect-language",
                "CONFIG_CREATE": lambda argv: len(argv) == 7 and argv[:2] == ["config", "--create"],
                "CONFIG_RESUME": lambda argv: len(argv) == 3 and argv[:2] == ["config", "--resume"],
                "CONFIG_OVERWRITE_REFUSAL": lambda argv: len(argv) == 7 and argv[:2] == ["config", "--overwrite-refusal"],
                "SC_WIZARD_DRY_START": lambda argv: argv[:3] == ["wizard", "--dry-run", "--codex"] and len(argv) in {3, 4},
                "SC_WIZARD_DRY_RESUME": lambda argv: len(argv) == 5 and argv[:4] == ["wizard", "--dry-run", "--codex", "--resume"],
                "L1_WIZARD_DRY_START": lambda argv: argv[:4] == ["l1", "wizard", "--dry-run", "--codex"] and len(argv) in {4, 5},
                "L1_WIZARD_DRY_RESUME": lambda argv: len(argv) == 6 and argv[:5] == ["l1", "wizard", "--dry-run", "--codex", "--resume"],
            },
            strict_json=_strict_json_bytes,
        )
        if borrowed is None:
            anchor, handle, close = _open_install_admission_anchor(
                codex_home, writer=False, create=False
            )
            _receipt_descriptor, receipt_before = _codex_install_committed_descriptor(
                codex_home, (_CODEX_INSTALL_RECEIPT,), return_raw=True,
            )
        else:
            handle, close, receipt_before, _capability = borrowed
            _CODEX_INSTALL_READER_COMMAND_KIND = _capability["command_kind"]
            anchor = anchor_path
        receipt = _strict_json_bytes(receipt_before)
        if set(receipt) != _CODEX_COMMITTED_RECEIPT_FIELDS or receipt.get("schema") != _CODEX_INSTALL_SCHEMA:
            raise RuntimeError("Plamen install receipt authority is incomplete")
        if receipt.get("state") != _CODEX_INSTALL_TERMINAL_STATE:
            raise RuntimeError(
                "Plamen installation is in maintenance: "
                f"{receipt.get('transaction_id', 'unknown')} "
                f"{receipt.get('state', 'UNKNOWN')}"
            )
        if (
            type(receipt.get("source_count")) is not int
            or receipt.get("source_count") != _CODEX_INSTALL_SOURCE_COUNT
            or type(receipt.get("runtime_count")) is not int
            or receipt.get("runtime_count") != _CODEX_INSTALL_RUNTIME_COUNT
            or type(receipt.get("adapter_count")) is not int
            or receipt.get("adapter_count") != _CODEX_INSTALL_ADAPTER_COUNT
            or len(receipt.get("rows", ())) != _CODEX_INSTALL_SOURCE_COUNT
            or len(receipt.get("journal", ())) != _CODEX_INSTALL_SOURCE_COUNT
        ):
            raise RuntimeError("Plamen committed install receipt has the wrong denominator")
        if not re.fullmatch(r"[0-9a-f]{32}", receipt.get("transaction_id", "")):
            raise RuntimeError("Plamen committed transaction identity is malformed")
        if not re.fullmatch(r"[0-9a-f]{64}", receipt.get("source_manifest_sha256", "")):
            raise RuntimeError("Plamen committed source manifest identity is malformed")
        destination_keys = [row.get("destination_key") for row in receipt["rows"] if isinstance(row, dict)]
        if (
            len(destination_keys) != _CODEX_INSTALL_SOURCE_COUNT
            or len({str(key).casefold() for key in destination_keys})
            != _CODEX_INSTALL_SOURCE_COUNT
        ):
            raise RuntimeError("Plamen committed destination roster is malformed")
        _receipt_after_descriptor, receipt_after = _codex_install_committed_descriptor(
            codex_home, (_CODEX_INSTALL_RECEIPT,), return_raw=True,
        )
        if receipt_after != receipt_before:
            raise RuntimeError("Plamen install receipt changed during admission")
        native_lock = _borrowed_reader_handle_identity(handle)
        lock_identity = [int(native_lock["volume"]), int(native_lock["file_id"])]
        if receipt.get("lock_identity") != lock_identity:
            raise RuntimeError("Plamen install lock identity differs from committed receipt")
        plamen_script_rows = [
            row for row in receipt.get("rows", ())
            if isinstance(row, dict)
            and row.get("destination_root") == "plamen"
            and row.get("destination_path") == "plamen.py"
        ]
        if (
            len(plamen_script_rows) != 1
            or plamen_script_rows[0].get("terminal_authority")
            != installed_authority["module_authority"]
        ):
            raise RuntimeError("Plamen installed module authority differs from receipt")
        owner = receipt.get("owner")
        if (
            not isinstance(owner, dict)
            or set(owner) != {"pid", "executable", "executable_sha256", "principal", "started_ns"}
            or not isinstance(owner.get("pid"), int) or isinstance(owner.get("pid"), bool)
            or owner.get("pid") <= 0
            or not isinstance(owner.get("started_ns"), int)
            or owner.get("started_ns") <= 0
            or not re.fullmatch(r"[0-9a-f]{64}", owner.get("executable_sha256", ""))
        ):
            raise RuntimeError("Plamen committed installer authority is malformed")
        _validate_committed_install_rows(
            receipt, installed=installed, codex_home=codex_home
        )
        if borrowed is None:
            _validate_codex_install_terminal_evidence(
                receipt, receipt_before, codex_home=codex_home,
            )
    except Exception as exc:
        try:
            close()
        except Exception:
            pass
        message = str(exc).splitlines()[0][:300]
        sys.stderr.write(
            f"Plamen maintenance admission denied: {message}. "
            "Recover with `plamen install --codex --recover <transaction-id>`.\n"
        )
        raise SystemExit(75)
    reader = (handle, close, receipt_before)
    _CODEX_INSTALL_ADMISSION = _issue_capability(
        reader=reader,
        command_kind=_CODEX_INSTALL_READER_COMMAND_KIND,
        installed_root=installed,
        codex_home=codex_home,
    )
    _CODEX_INSTALL_READER = reader
    atexit.register(close)


_admit_installed_runtime_before_bootstrap()
del _issue_codex_install_admission_capability


def _public_help_text(version: str) -> str:
    """One public help contract for both source and installed entry points."""
    return f"""plamen {version}
Usage:
  plamen                              Interactive wizard (terminal required)
  plamen plan MODE PATH [OPTIONS]     Validate and explain a run; zero provider calls
  plamen light|core|thorough PATH [OPTIONS]
  plamen l1 light|core|thorough PATH [OPTIONS]
  plamen resume [PATH/.scratchpad/config.json]
  plamen compare REPORT [--docs GROUND_TRUTH]
  plamen install                      Install/repair Claude integration
  plamen install --codex              Install/repair the Codex package
  plamen install --codex --check      Validate the local source package; no writes
  plamen setup                        Interactive toolchain setup (terminal required)
  plamen doctor                       Verify installation; zero provider calls

Audit options:
  --docs PATH_OR_URL   --scope PATH   --notes TEXT   --network NAME
  --proven-only        --tier T0|T1|T2|T3            --modules a,b,c
  --codex | --claude   --allow-model-fallback        --yes
  --claude-exec-mode headless       --claude-headless

Plan options:
  --l1                 --json         --explain-routes

Accessibility:
  NO_COLOR=1 disables ANSI color. PLAMEN_PLAIN_OUTPUT=1 disables rich output.
  PLAMEN_PLAIN_WIZARD=1 uses numbered, line-oriented prompts for screen readers.

Starting or resuming an audit launches external workers and may consume quota.
Model fallback is disabled unless --allow-model-fallback is explicitly supplied."""


def _early_cli_discovery():
    args = [item.lower() for item in sys.argv[1:]]
    if not args:
        return
    if args[0] in {"version", "--version"}:
        _version_descriptor, version_raw = _codex_install_committed_descriptor(
            Path(__file__).parent, ("VERSION",), return_raw=True,
        )
        version = version_raw.decode("utf-8").strip()
        print(f"plamen {version}")
        raise SystemExit(0)
    # Help is a discovery route at every command depth.  Resolve it before
    # bootstrap and before main() can enter any mutating workflow; otherwise
    # `plamen install --help` is indistinguishable from `plamen install` and
    # can refresh links/configuration merely while a user asks for usage.
    if args[0] in {"help", "--help", "-h"} or any(
        item in {"--help", "-h"} for item in args[1:]
    ):
        _version_descriptor, version_raw = _codex_install_committed_descriptor(
            Path(__file__).parent, ("VERSION",), return_raw=True,
        )
        version = version_raw.decode("utf-8").strip()
        print(_public_help_text(version))
        raise SystemExit(0)


_early_cli_discovery()

