# Windows: enable VT100 + force UTF-8 stdout before anything loads.
# Guard against pytest/captured/non-buffer streams: rewrapping a capture object's
# buffer detaches it and crashes pytest's teardown ("I/O operation on closed
# file"). Only rewrap a real, buffer-backed, not-already-UTF-8 stream, never under
# pytest. This keeps the terminal UI correct while letting plamen.py be imported
# in tests cleanly.
if sys.platform == "win32" and "pytest" not in sys.modules:
    os.system("")
    for _name in ("stdout", "stderr"):
        _s = getattr(sys, _name, None)
        if (
            _s is not None
            and hasattr(_s, "reconfigure")
            and (getattr(_s, "encoding", "") or "").lower().replace("-", "") != "utf8"
        ):
            try:
                # Reconfigure the existing wrapper in place. Replacing it with
                # TextIOWrapper(buffer) transfers/duplicates ownership badly:
                # when bootstrap exits, it can close the inherited stdout pipe
                # underneath the managed child process.
                _s.reconfigure(encoding="utf-8", errors="replace")
            except Exception:
                pass

# ── Bootstrap: auto-install core deps on first run ──────────
_RUNTIME_PYTHON = (3, 12)
_RUNTIME_STAMP_SCHEMA = "plamen.python_runtime.v1"
_PYTHON_DEPENDENCY_STAMP_SCHEMA = "plamen.python_dependency_runtime.v1"
_PYTHON_DEPENDENCY_BOOTSTRAP_ATTESTATION_TTL_NS = 120 * 1_000_000_000
_PYTHON_DEPENDENCY_BOOTSTRAP_MATERIALIZATION = object()
_PYTHON_DEPENDENCY_BOOTSTRAP_ATTESTATION = None


def _managed_runtime_root():
    return Path(os.path.expanduser("~/.local/share/plamen/runtime/py312"))


def _managed_runtime_python():
    root = _managed_runtime_root()
    return root / ("Scripts/python.exe" if os.name == "nt" else "bin/python")


def _runtime_lock_path():
    return Path(__file__).resolve().parent / "requirements-runtime-core.lock"


def _file_sha256(path):
    digest = hashlib.sha256()
    with open(path, "rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def _atomic_write_bytes(path, raw):
    destination = Path(path)
    destination.parent.mkdir(parents=True, exist_ok=True)
    temporary = destination.with_name(
        f".{destination.name}.{os.getpid()}.{secrets.token_hex(6)}.tmp"
    )
    try:
        with open(temporary, "xb") as handle:
            handle.write(raw)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temporary, destination)
    finally:
        try:
            temporary.unlink()
        except FileNotFoundError:
            pass


def _atomic_write_text(path, value, encoding="utf-8"):
    _atomic_write_bytes(path, value.encode(encoding))


def _atomic_write_json(path, value):
    _atomic_write_text(path, json.dumps(value, indent=2) + "\n")


def _runtime_stamp_path():
    return _managed_runtime_root() / ".plamen-runtime.json"


def _python_dependency_stamp_path():
    # Keep the cache beside, never inside, the censused runtime.  Atomic stamp
    # publication changes its parent-directory mtime; placing it under py312
    # would invalidate the root-directory row that the stamp just recorded.
    return _managed_runtime_root().parent / ".plamen-python-dependency-py312.json"


def _retire_legacy_python_dependency_stamp():
    """Remove only the exact obsolete in-census cache before a locked repair."""
    path = _managed_runtime_root() / ".plamen-dependency-runtime.json"
    try:
        info = os.lstat(path)
    except FileNotFoundError:
        return True
    except OSError:
        return False
    if (
        not stat.S_ISREG(info.st_mode)
        or stat.S_ISLNK(info.st_mode)
        or _python_dependency_census_reparse(info)
        or info.st_nlink != 1
    ):
        return False
    try:
        path.unlink()
    except OSError:
        return False
    return not path.exists()


def _runtime_stamp_valid(lock_digest):
    python = _managed_runtime_python()
    stamp_path = _runtime_stamp_path()
    if not python.is_file() or not stamp_path.is_file():
        return False
    try:
        stamp = json.loads(stamp_path.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return False
    return stamp == {
        "lock_sha256": lock_digest,
        "python_abi": "cp312",
        "schema": _RUNTIME_STAMP_SCHEMA,
    }


def _write_runtime_stamp(lock_digest):
    stamp_path = _runtime_stamp_path()
    stamp_path.parent.mkdir(parents=True, exist_ok=True)
    raw = (json.dumps({
        "lock_sha256": lock_digest,
        "python_abi": "cp312",
        "schema": _RUNTIME_STAMP_SCHEMA,
    }, sort_keys=True, separators=(",", ":")) + "\n").encode("utf-8")
    temporary = stamp_path.with_name(
        f".{stamp_path.name}.{os.getpid()}.{secrets.token_hex(6)}.tmp"
    )
    try:
        with open(temporary, "xb") as handle:
            handle.write(raw)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temporary, stamp_path)
    finally:
        try:
            temporary.unlink()
        except FileNotFoundError:
            pass


def _python_lock_authority_sha256(root):
    """Digest only the exact lock consumed by the full-runtime pip command.

    The toolchain runtime closure intentionally contains executable source,
    prompts, generated policy consumers, and other governed assets.  Those
    bytes must refresh the committed package, but they are not Python package
    authority and must not cause a multi-gigabyte pip reinstall.
    """
    lock = Path(root).absolute() / "requirements-runtime-full.lock"
    if not lock.is_file() or lock.is_symlink():
        raise RuntimeError("reviewed full Python runtime lock is unavailable")
    return _file_sha256(lock)


def _python_dependency_authority(source_root=None):
    """Bind the pip lock to the exact managed interpreter that consumes it."""
    python = _managed_runtime_python()
    resolved = python.resolve(strict=True)
    if not resolved.is_file() or resolved.is_symlink():
        raise RuntimeError("managed Python interpreter authority is unavailable")
    payload = {
        "implementation": sys.implementation.name,
        "interpreter_sha256": _file_sha256(resolved),
        "lock_sha256": _python_lock_authority_sha256(
            source_root or Path(__file__).absolute().parent
        ),
        "machine": platform.machine().lower(),
        "python_version": list(sys.version_info[:3]),
        "schema": "plamen.python_dependency_authority.v1",
        "sys_platform": sys.platform,
    }
    return hashlib.sha256(
        json.dumps(payload, sort_keys=True, separators=(",", ":")).encode("utf-8")
    ).hexdigest()


_PYTHON_DEPENDENCY_CENSUS_SCHEMA = "plamen.python_dependency_census.v1"
_PYTHON_DEPENDENCY_CENSUS_EXCLUDED_DIRS = frozenset()
_PYTHON_DEPENDENCY_TRUST_BOUNDARY = "USER_WRITABLE_DRIFT_DETECTION_ONLY"


def _python_dependency_census_roots(runtime_root=None, site_roots=None):
    root = Path(runtime_root or _managed_runtime_root()).absolute()
    if site_roots is None:
        import sysconfig
        site_roots = [
            value
            for key, value in sysconfig.get_paths().items()
            if key in {"purelib", "platlib"} and value
        ]
    # WindowsPath equality is case-insensitive.  Never put the candidates in a
    # Path set before checking their exact spellings: doing so can silently
    # discard one member of a case-sensitive directory before the census sees
    # it.  Exact duplicates (purelib == platlib) are harmless; alias spellings
    # are not.
    exact_roots = {}
    root_aliases = {}
    for item in site_roots:
        candidate = Path(item).absolute()
        exact = os.fspath(candidate)
        alias = _python_dependency_census_alias(exact)
        prior = root_aliases.get(alias)
        if prior is not None and prior != exact:
            raise RuntimeError("Python site-package roots contain a spelling alias")
        root_aliases[alias] = exact
        exact_roots.setdefault(exact, candidate)
    roots = tuple(exact_roots[key] for key in sorted(exact_roots))
    if not roots:
        raise RuntimeError("managed Python site-package roots are unavailable")
    try:
        for item in roots:
            relative = item.relative_to(root)
            if os.fspath(root.joinpath(*relative.parts)) != os.fspath(item):
                raise RuntimeError(
                    "Python site-package root uses an aliased root spelling"
                )
    except ValueError as exc:
        raise RuntimeError("Python site-package root escapes managed runtime") from exc
    return root, roots


def _python_dependency_census_reparse(info):
    return bool(
        getattr(info, "st_file_attributes", 0)
        & getattr(stat, "FILE_ATTRIBUTE_REPARSE_POINT", 0x400)
    )


def _python_dependency_census_alias(value):
    """Return the conservative filesystem spelling key without losing bytes."""
    import unicodedata

    normalized = unicodedata.normalize("NFC", value)
    return normalized.casefold() if os.name == "nt" else normalized


def _python_dependency_census_paths(runtime_root, site_roots):
    """Enumerate and validate the deterministic ordinary-file roster."""
    selected = [runtime_root / "pyvenv.cfg"]
    directories = [runtime_root]
    for site_root in site_roots:
        current = runtime_root
        for component in site_root.relative_to(runtime_root).parts:
            current = current / component
            try:
                ancestor_info = os.lstat(current)
            except OSError as exc:
                raise RuntimeError(
                    "Python dependency directory ancestor is unavailable"
                ) from exc
            if (
                not stat.S_ISDIR(ancestor_info.st_mode)
                or stat.S_ISLNK(ancestor_info.st_mode)
                or _python_dependency_census_reparse(ancestor_info)
            ):
                raise RuntimeError(
                    "Python dependency directory ancestor is linked or special"
                )
            directories.append(current)
        try:
            root_info = os.lstat(site_root)
        except OSError as exc:
            raise RuntimeError("managed Python site-package root is unavailable") from exc
        if (
            not stat.S_ISDIR(root_info.st_mode)
            or stat.S_ISLNK(root_info.st_mode)
            or _python_dependency_census_reparse(root_info)
        ):
            raise RuntimeError("managed Python site-package root is not a physical directory")
        for directory, dirnames, filenames in os.walk(site_root, followlinks=False):
            directory_path = Path(directory)
            directories.append(directory_path)
            kept = []
            for name in sorted(dirnames):
                child = directory_path / name
                try:
                    info = os.lstat(child)
                except OSError as exc:
                    raise RuntimeError("Python dependency directory changed during census") from exc
                if (
                    not stat.S_ISDIR(info.st_mode)
                    or stat.S_ISLNK(info.st_mode)
                    or _python_dependency_census_reparse(info)
                ):
                    raise RuntimeError("Python dependency directory is linked or special")
                if name not in _PYTHON_DEPENDENCY_CENSUS_EXCLUDED_DIRS:
                    kept.append(name)
                    directories.append(child)
            dirnames[:] = kept
            selected.extend(directory_path / name for name in sorted(filenames))
    aliases = {}
    exact_paths = set()
    result = []
    for path in sorted(selected, key=lambda item: item.as_posix()):
        try:
            relative = path.relative_to(runtime_root).as_posix()
        except ValueError as exc:
            raise RuntimeError("Python dependency census path escapes runtime") from exc
        parts = PurePosixPath(relative).parts
        if (
            not parts
            or PurePosixPath(relative).is_absolute()
            or any(part in {"", ".", ".."} for part in parts)
            or "\\" in relative
        ):
            raise RuntimeError("Python dependency census path is unsafe")
        alias = _python_dependency_census_alias(relative)
        prior = aliases.get(alias)
        if prior is not None and prior != relative:
            raise RuntimeError("Python dependency census contains a path alias")
        aliases[alias] = relative
        if relative in exact_paths:
            continue
        exact_paths.add(relative)
        result.append((path, relative))
    directory_rows = []
    directory_aliases = {}
    exact_directories = set()
    directory_physical = set()
    for path in sorted(directories, key=lambda item: item.as_posix()):
        relative = (
            "." if os.fspath(path) == os.fspath(runtime_root)
            else path.relative_to(runtime_root).as_posix()
        )
        alias = _python_dependency_census_alias(relative)
        prior = directory_aliases.get(alias)
        if prior is not None and prior != relative:
            raise RuntimeError("Python dependency census contains a directory path alias")
        directory_aliases[alias] = relative
        if relative in exact_directories:
            continue
        exact_directories.add(relative)
        try:
            info = os.lstat(path)
        except OSError as exc:
            raise RuntimeError("Python dependency directory ancestor is unavailable") from exc
        if (
            not stat.S_ISDIR(info.st_mode)
            or stat.S_ISLNK(info.st_mode)
            or _python_dependency_census_reparse(info)
        ):
            raise RuntimeError("Python dependency directory ancestor is linked or special")
        identity = (info.st_dev, info.st_ino)
        if identity in directory_physical:
            raise RuntimeError("Python dependency census contains a directory alias")
        directory_physical.add(identity)
        directory_rows.append({
            "device": info.st_dev,
            "inode": info.st_ino,
            "mtime_ns": info.st_mtime_ns,
            "path": relative,
            "type": "directory",
        })
    return result, directory_rows


def _python_dependency_census_member(item):
    """Hash one roster member through a stable physical descriptor."""
    path, relative = item
    try:
        before = os.lstat(path)
    except OSError as exc:
        raise RuntimeError("Python dependency census member is unavailable") from exc
    if (
        not stat.S_ISREG(before.st_mode)
        or stat.S_ISLNK(before.st_mode)
        or _python_dependency_census_reparse(before)
        or before.st_nlink != 1
    ):
        raise RuntimeError("Python dependency census member is linked or special")
    flags = os.O_RDONLY | getattr(os, "O_BINARY", 0) | getattr(os, "O_NOFOLLOW", 0)
    descriptor = None
    digest = hashlib.sha256()
    try:
        descriptor = os.open(path, flags)
        opened = os.fstat(descriptor)
        identity = (opened.st_dev, opened.st_ino)
        if (
            identity != (before.st_dev, before.st_ino)
            or not stat.S_ISREG(opened.st_mode)
            or opened.st_nlink != 1
            or _python_dependency_census_reparse(opened)
        ):
            raise RuntimeError("Python dependency census member identity is unsafe")
        while True:
            block = os.read(descriptor, 1024 * 1024)
            if not block:
                break
            digest.update(block)
        after_open = os.fstat(descriptor)
    finally:
        if descriptor is not None:
            os.close(descriptor)
    try:
        after_path = os.lstat(path)
    except OSError as exc:
        raise RuntimeError("Python dependency census member disappeared") from exc
    stable_fields = ("st_dev", "st_ino", "st_nlink", "st_size", "st_mtime_ns")
    if (
        not stat.S_ISREG(after_path.st_mode)
        or stat.S_ISLNK(after_path.st_mode)
        or _python_dependency_census_reparse(after_path)
        or any(
            getattr(before, field) != getattr(after_open, field)
            or getattr(after_open, field) != getattr(after_path, field)
            for field in stable_fields
        )
    ):
        raise RuntimeError(
            "Python dependency census member changed while hashing: " + relative
        )
    return identity, {
        "path": relative,
        "sha256": digest.hexdigest(),
        "size": opened.st_size,
        "type": "file",
    }


def _python_dependency_census_members(runtime_root, site_roots):
    """Hash the exact roster concurrently, retaining deterministic row order."""
    from concurrent.futures import ThreadPoolExecutor

    roster, directory_rows = _python_dependency_census_paths(runtime_root, site_roots)
    workers = max(1, min(8, os.cpu_count() or 1))
    with ThreadPoolExecutor(max_workers=workers) as executor:
        captured = list(executor.map(_python_dependency_census_member, roster))
    identities = [identity for identity, _row in captured]
    if len(identities) != len(set(identities)):
        raise RuntimeError("Python dependency census contains a physical alias")
    rows = [row for _identity, row in captured]
    replay, replay_directories = _python_dependency_census_paths(runtime_root, site_roots)
    if (
        [(relative) for _path, relative in replay] != [row["path"] for row in rows]
        or replay_directories != directory_rows
    ):
        raise RuntimeError("Python dependency census roster changed during replay")
    return rows, directory_rows


def _python_dependency_census_bounded_diff(expected, actual, limit=8):
    """Describe the first deterministic manifest differences without file data."""
    differences = []

    def safe_path(value):
        rendered = json.dumps(value, ensure_ascii=True)
        return rendered if len(rendered) <= 180 else rendered[:177] + "..."

    def compare(kind, expected_rows, actual_rows):
        expected_by_path = {row["path"]: row for row in expected_rows}
        actual_by_path = {row["path"]: row for row in actual_rows}
        for path in sorted(set(expected_by_path) | set(actual_by_path)):
            if len(differences) >= limit:
                return
            before = expected_by_path.get(path)
            after = actual_by_path.get(path)
            if before is None:
                differences.append(f"extra {kind} {safe_path(path)}")
            elif after is None:
                differences.append(f"missing {kind} {safe_path(path)}")
            elif before != after:
                fields = sorted(
                    key for key in set(before) | set(after)
                    if before.get(key) != after.get(key)
                )
                differences.append(
                    f"changed {kind} {safe_path(path)} fields={','.join(fields)}"
                )

    if expected.get("schema") != actual.get("schema"):
        differences.append("changed census schema")
    compare("directory", expected.get("directories", ()), actual.get("directories", ()))
    compare("file", expected.get("rows", ()), actual.get("rows", ()))
    if not differences:
        return "manifest summaries differ without a row difference"
    return "; ".join(differences[:limit])


def _python_dependency_runtime_census(
    runtime_root=None, site_roots=None, *, include_manifest=False,
):
    root, sites = _python_dependency_census_roots(runtime_root, site_roots)
    root_info = os.lstat(root)
    if (
        not stat.S_ISDIR(root_info.st_mode)
        or stat.S_ISLNK(root_info.st_mode)
        or _python_dependency_census_reparse(root_info)
    ):
        raise RuntimeError("managed Python runtime root is linked or special")
    rows, directories = _python_dependency_census_members(root, sites)
    replay_rows, replay_directories = _python_dependency_census_members(root, sites)
    if rows != replay_rows or directories != replay_directories:
        expected = {
            "directories": directories,
            "rows": rows,
            "schema": _PYTHON_DEPENDENCY_CENSUS_SCHEMA,
        }
        actual = {
            "directories": replay_directories,
            "rows": replay_rows,
            "schema": _PYTHON_DEPENDENCY_CENSUS_SCHEMA,
        }
        raise RuntimeError(
            "Python dependency census changed during byte replay: "
            + _python_dependency_census_bounded_diff(expected, actual)
        )
    manifest = {
        "directories": directories,
        "rows": rows,
        "schema": _PYTHON_DEPENDENCY_CENSUS_SCHEMA,
    }
    canonical = json.dumps(manifest, sort_keys=True, separators=(",", ":")).encode("utf-8")
    summary = {
        "census_sha256": hashlib.sha256(canonical).hexdigest(),
        "directory_count": len(directories),
        "file_count": len(rows),
        "total_bytes": sum(row["size"] for row in rows),
    }
    return (summary, manifest) if include_manifest else summary


def _python_dependency_stamp_observation():
    """Read the cache stamp through one stable ordinary-file identity."""
    path = _python_dependency_stamp_path().absolute()
    try:
        before = os.lstat(path)
    except OSError as exc:
        raise RuntimeError("Python dependency stamp is unavailable") from exc
    if (
        not stat.S_ISREG(before.st_mode)
        or stat.S_ISLNK(before.st_mode)
        or _python_dependency_census_reparse(before)
        or before.st_nlink != 1
    ):
        raise RuntimeError("Python dependency stamp is linked or special")
    descriptor = None
    raw = bytearray()
    try:
        flags = os.O_RDONLY | getattr(os, "O_BINARY", 0) | getattr(os, "O_NOFOLLOW", 0)
        descriptor = os.open(path, flags)
        opened = os.fstat(descriptor)
        if (
            (opened.st_dev, opened.st_ino) != (before.st_dev, before.st_ino)
            or not stat.S_ISREG(opened.st_mode)
            or opened.st_nlink != 1
            or _python_dependency_census_reparse(opened)
        ):
            raise RuntimeError("Python dependency stamp identity is unsafe")
        while True:
            block = os.read(descriptor, 1024 * 1024)
            if not block:
                break
            raw.extend(block)
        after_open = os.fstat(descriptor)
    finally:
        if descriptor is not None:
            os.close(descriptor)
    try:
        after_path = os.lstat(path)
    except OSError as exc:
        raise RuntimeError("Python dependency stamp disappeared") from exc
    fields = ("st_dev", "st_ino", "st_mode", "st_nlink", "st_size", "st_mtime_ns")
    if any(
        getattr(before, field) != getattr(after_open, field)
        or getattr(after_open, field) != getattr(after_path, field)
        for field in fields
    ):
        raise RuntimeError("Python dependency stamp changed while reading")
    identity = tuple(getattr(after_open, field) for field in fields)
    return {
        "identity": identity,
        "path": os.fspath(path),
        "raw": bytes(raw),
        "raw_sha256": hashlib.sha256(raw).hexdigest(),
    }


def _publish_python_dependency_bootstrap_attestation(
    *, source_root, authority_digest, stamp_observation, census_summary,
):
    """Publish one non-serializable, process-local VALID-bootstrap replay."""
    global _PYTHON_DEPENDENCY_BOOTSTRAP_ATTESTATION
    _PYTHON_DEPENDENCY_BOOTSTRAP_ATTESTATION = {
        "authority_sha256": authority_digest,
        "census_summary": dict(census_summary),
        "interpreter_path": os.fspath(_managed_runtime_python().resolve(strict=True)),
        "materialization_marker": _PYTHON_DEPENDENCY_BOOTSTRAP_MATERIALIZATION,
        "pid": os.getpid(),
        "runtime_root": os.fspath(_managed_runtime_root().absolute()),
        "source_root": os.fspath(Path(source_root).absolute()),
        "stamp_identity": stamp_observation["identity"],
        "stamp_path": stamp_observation["path"],
        "stamp_raw_sha256": stamp_observation["raw_sha256"],
        "validated_at_ns": time.monotonic_ns(),
    }


def _consume_python_dependency_bootstrap_attestation(
    *, source_root, authority_digest, force_refresh=False,
):
    """Consume a matching bootstrap replay once, otherwise fail closed."""
    global _PYTHON_DEPENDENCY_BOOTSTRAP_ATTESTATION
    attestation = _PYTHON_DEPENDENCY_BOOTSTRAP_ATTESTATION
    _PYTHON_DEPENDENCY_BOOTSTRAP_ATTESTATION = None
    if force_refresh or not isinstance(attestation, dict):
        return None
    try:
        now = time.monotonic_ns()
        expected = {
            "authority_sha256": authority_digest,
            "interpreter_path": os.fspath(_managed_runtime_python().resolve(strict=True)),
            "materialization_marker": _PYTHON_DEPENDENCY_BOOTSTRAP_MATERIALIZATION,
            "pid": os.getpid(),
            "runtime_root": os.fspath(_managed_runtime_root().absolute()),
            "source_root": os.fspath(Path(source_root).absolute()),
        }
        if any(attestation.get(key) != value for key, value in expected.items()):
            return None
        validated_at = attestation.get("validated_at_ns")
        if (
            type(validated_at) is not int
            or now < validated_at
            or now - validated_at > _PYTHON_DEPENDENCY_BOOTSTRAP_ATTESTATION_TTL_NS
        ):
            return None
        current = _python_dependency_stamp_observation()
        if (
            current["path"] != attestation.get("stamp_path")
            or current["identity"] != attestation.get("stamp_identity")
            or current["raw_sha256"] != attestation.get("stamp_raw_sha256")
        ):
            return None
        summary = attestation.get("census_summary")
        if (
            not isinstance(summary, dict)
            or set(summary) != {
                "census_sha256", "directory_count", "file_count", "total_bytes",
            }
            or not re.fullmatch(r"[0-9a-f]{64}", summary.get("census_sha256", ""))
            or any(
                type(summary.get(key)) is not int or summary[key] < 0
                for key in ("directory_count", "file_count", "total_bytes")
            )
        ):
            return None
        return dict(summary)
    except (OSError, RuntimeError, ValueError, TypeError):
        return None


def _python_dependency_stamp_status(
    authority_digest, *, expected_manifest=None, diagnostics=None,
    validated_observation=None,
):
    """Replay a user-writable drift cache; this is not a malware trust root."""
    path = _python_dependency_stamp_path()
    if not path.exists():
        return "ABSENT"
    try:
        info = os.lstat(path)
    except OSError:
        return "INVALID"
    if (
        not stat.S_ISREG(info.st_mode)
        or stat.S_ISLNK(info.st_mode)
        or _python_dependency_census_reparse(info)
        or info.st_nlink != 1
    ):
        return "INVALID"
    try:
        observation = _python_dependency_stamp_observation()
        raw = observation["raw"]
        value = json.loads(raw.decode("utf-8"))
        census_result = _python_dependency_runtime_census(
            include_manifest=expected_manifest is not None
        )
        if expected_manifest is None:
            census = census_result
            actual_manifest = None
        else:
            census, actual_manifest = census_result
    except (OSError, RuntimeError, UnicodeError, ValueError):
        return "INVALID"
    expected = {
        "authority_sha256": authority_digest,
        **census,
        "schema": _PYTHON_DEPENDENCY_STAMP_SCHEMA,
        "trust_boundary": _PYTHON_DEPENDENCY_TRUST_BOUNDARY,
    }
    expected_raw = (
        json.dumps(expected, sort_keys=True, separators=(",", ":")) + "\n"
    ).encode("utf-8")
    valid = value == expected and raw == expected_raw
    if (
        not valid
        and expected_manifest is not None
        and isinstance(diagnostics, list)
    ):
        diagnostics.append(
            _python_dependency_census_bounded_diff(
                expected_manifest, actual_manifest
            )
        )
    if valid and isinstance(validated_observation, list):
        validated_observation.append({
            **observation,
            "census_summary": dict(census),
        })
    return "VALID" if valid else "INVALID"


def _write_python_dependency_stamp(authority_digest, *, retain_manifest=False):
    if not re.fullmatch(r"[0-9a-f]{64}", authority_digest or ""):
        raise RuntimeError("Python dependency authority digest is malformed")
    census_result = _python_dependency_runtime_census(
        include_manifest=retain_manifest
    )
    if retain_manifest:
        census, manifest = census_result
    else:
        census = census_result
        manifest = None
    _atomic_write_bytes(
        _python_dependency_stamp_path(),
        (json.dumps({
            "authority_sha256": authority_digest,
            **census,
            "schema": _PYTHON_DEPENDENCY_STAMP_SCHEMA,
            "trust_boundary": _PYTHON_DEPENDENCY_TRUST_BOUNDARY,
        }, sort_keys=True, separators=(",", ":")) + "\n").encode("utf-8"),
    )
    return manifest


def _invalidate_python_dependency_stamp():
    path = _python_dependency_stamp_path()
    try:
        path.unlink()
    except FileNotFoundError:
        return True
    except OSError:
        return False
    return not path.exists()


def _python_dependency_refresh_required(
    *,
    force_refresh,
    core_ok,
    deep_ok,
    protobuf_current,
    runtime_healthy,
    stamp_status,
):
    """Pure fail-closed decision for the expensive full-lock reinstall."""
    if force_refresh or not all((core_ok, deep_ok, protobuf_current, runtime_healthy)):
        return True
    return stamp_status != "VALID"


def _pip_install_args():
    """Return pip's base argv for the active Plamen-owned runtime only."""
    managed = _managed_runtime_python().resolve()
    active = Path(sys.executable).resolve()
    if active != managed:
        raise RuntimeError(
            "Python package mutation refused outside the Plamen-owned runtime"
        )
    return [str(managed), "-B", "-m", "pip", "install"]


def _early_admitted_install_authority():
    """Replay the exact opaque admission and its retained/named authorities."""
    reader, command_kind, installed_root, codex_home = (
        _replay_codex_install_admission_capability(_CODEX_INSTALL_ADMISSION)
    )
    if (
        reader is not _CODEX_INSTALL_READER
        or command_kind != _CODEX_INSTALL_READER_COMMAND_KIND
        or not isinstance(reader, tuple)
        or len(reader) != 3
    ):
        raise RuntimeError("installed admission telemetry differs")
    handle, close, receipt_raw = reader
    if (
        type(handle) is not int
        or handle <= 0
        or not callable(close)
        or not isinstance(receipt_raw, bytes)
    ):
        raise RuntimeError("installed admission reader is malformed")
    current_installed = _installed_runtime_root()
    if (
        current_installed is None
        or current_installed["address"].absolute() != installed_root
        or Path(__file__).absolute().parent != installed_root
    ):
        raise RuntimeError("installed admission module authority differs")
    _receipt_descriptor, current_raw = _codex_install_committed_descriptor(
        codex_home, (_CODEX_INSTALL_RECEIPT,), return_raw=True,
    )
    if current_raw != receipt_raw:
        raise RuntimeError("installed admission receipt changed")
    receipt = _strict_json_bytes(receipt_raw)
    identity = _borrowed_reader_handle_identity(handle)
    if receipt.get("lock_identity") != [
        int(identity["volume"]), int(identity["file_id"]),
    ]:
        raise RuntimeError("installed admission anchor authority differs")
    return reader, command_kind, installed_root, codex_home, receipt


def _has_admitted_install_command(*command_kinds):
    """Return whether the current process owns one exact admitted command."""
    try:
        _reader, command_kind, _installed, _codex, _receipt = (
            _early_admitted_install_authority()
        )
    except (OSError, RuntimeError, TypeError, ValueError):
        return False
    return command_kind in command_kinds


def _early_internal_launcher_receipt():
    """Return the already-admitted receipt without depending on late globals.

    ``mcp-selection``, ``mcp-launch``, and ``backend-launch`` enter bootstrap
    before the ordinary installed-receipt helpers and ``PLAMEN_HOME`` are
    defined.  The pre-bootstrap admission immediately above this section has
    already validated the complete committed package while retaining the
    exact admission-anchor handle.  Rebind that retained capability here; a
    source invocation or a caller-fabricated placeholder must not turn an
    internal launcher command into an admitted installed command.
    """
    _reader, _command_kind, installed_root, _codex_home, receipt = (
        _early_admitted_install_authority()
    )
    if (
        not isinstance(receipt, dict)
        or set(receipt) != _CODEX_COMMITTED_RECEIPT_FIELDS
        or receipt.get("schema") != _CODEX_INSTALL_SCHEMA
        or receipt.get("state") != _CODEX_INSTALL_TERMINAL_STATE
        or not isinstance(receipt.get("plamen_root"), str)
        or Path(receipt["plamen_root"]).absolute() != installed_root
        or not isinstance(receipt.get("lock_identity"), list)
        or len(receipt["lock_identity"]) != 2
        or any(type(value) is not int or value < 0 for value in receipt["lock_identity"])
    ):
        raise RuntimeError("installed MCP launcher receipt is malformed")
    return receipt


def _bootstrap():
    """Converge on the hash-locked Plamen runtime, then re-exec inside it."""
    # The keeper is a capability-constrained child of an already-admitted
    # installer.  It must never mutate or bootstrap dependencies while holding
    # the transaction writer.  Its inherited handle, exact interpreter digest,
    # script digest, descriptor, and authenticated pipe are validated by the
    # keeper entry point before it can bind.
    if len(sys.argv) >= 2 and sys.argv[1] in {
        "--codex-install-keeper", "--codex-install-census-child",
    }:
        return True
    if len(sys.argv) >= 2 and sys.argv[1] in {
        "mcp-selection", "mcp-launch", "backend-launch",
    }:
        # The generation verifier is installed code.  Admit the complete
        # committed package and reviewed managed interpreter before that module
        # can be imported; never bootstrap or mutate dependencies on this path.
        try:
            lock = _runtime_lock_path()
            committed = _early_internal_launcher_receipt()
            installed_root = Path(__file__).absolute().parent
            if (
                Path(committed["plamen_root"]).absolute() != installed_root
                or Path(sys.executable).resolve(strict=True)
                != _managed_runtime_python().resolve(strict=True)
                or not lock.is_file()
                or not _runtime_stamp_valid(_file_sha256(lock))
            ):
                raise RuntimeError("installed MCP launcher authority differs")
        except (OSError, RuntimeError, ValueError, TypeError) as exc:
            sys.stderr.write("Error: MCP launcher admission denied: " + str(exc) + "\n")
            return False
        return True
    projection_assertion = "--codex-install-assert-claude-projection-current"
    if len(sys.argv) >= 2 and sys.argv[1] == projection_assertion:
        if sys.argv[1:] != [projection_assertion]:
            sys.stderr.write(
                "Error: Claude projection assertion argv differs.\n"
            )
            return False
        try:
            lock = _runtime_lock_path()
            active = Path(sys.executable).resolve(strict=True)
            managed = _managed_runtime_python().resolve(strict=True)
            if (
                sys.implementation.name != "cpython"
                or sys.version_info[:2] != _RUNTIME_PYTHON
                or active != managed
                or not lock.is_file()
                or not _runtime_stamp_valid(_file_sha256(lock))
            ):
                sys.stderr.write(
                    "Error: Claude projection assertion requires the existing "
                    "reviewed Plamen runtime.\n"
                )
                return False
        except OSError:
            sys.stderr.write(
                "Error: Claude projection assertion runtime is unavailable.\n"
            )
            return False
        return True
    # Test imports are read-only and must never create a user-level runtime.
    if "pytest" in sys.modules:
        try:
            import rich, InquirerPy  # noqa: F401
            return True
        except ImportError:
            return False
    if sys.implementation.name != "cpython" or sys.version_info[:2] != _RUNTIME_PYTHON:
        sys.stderr.write(
            "Error: Plamen requires CPython 3.12 to reproduce its reviewed "
            "binary-wheel lock. Install Python 3.12 and retry.\n"
        )
        return False
    lock = _runtime_lock_path()
    if not lock.is_file():
        sys.stderr.write(f"Error: reviewed runtime lock is missing: {lock}\n")
        return False
    lock_digest = _file_sha256(lock)
    managed_python = _managed_runtime_python()
    # On POSIX, a venv's bin/python is normally a symlink to the base
    # interpreter.  Comparing resolved executables therefore cannot tell an
    # ambient interpreter from the managed venv: both resolve to the same
    # inode.  sys.prefix is the venv identity and remains the managed root
    # after the re-exec below.
    active_runtime_root = Path(sys.prefix).absolute()
    installer_command = len(sys.argv) >= 2 and sys.argv[1] in {"install", "setup"}
    if installer_command:
        # Install/setup must not create generated bytecode in either the mutable
        # source or the exact package tree being censused.
        sys.dont_write_bytecode = True
    read_only_package_check = (
        len(sys.argv) >= 4
        and sys.argv[1] == "install"
        and "--codex" in sys.argv[2:]
        and "--check" in sys.argv[2:]
    )
    if read_only_package_check and not _runtime_stamp_valid(lock_digest):
        sys.stderr.write(
            "Error: read-only package check requires an existing verified "
            "Plamen runtime; run `plamen install` first. No files were changed.\n"
        )
        return False
    try:
        if not managed_python.is_file():
            import venv
            print("  Creating isolated Plamen Python runtime...")
            venv.EnvBuilder(
                with_pip=True, clear=False, symlinks=(os.name != "nt")
            ).create(_managed_runtime_root())
        if not _runtime_stamp_valid(lock_digest):
            print("  Installing hash-verified Plamen dependencies (first run/update)...")
            install = subprocess.run([
                str(managed_python), "-B", "-m", "pip", "install",
                "--disable-pip-version-check", "--require-hashes",
                "--only-binary=:all:", "-r", str(lock),
            ])
            if install.returncode != 0:
                return False
            verify = (
                subprocess.CompletedProcess([], 0)
                if installer_command else subprocess.run([
                    str(managed_python), "-I", "-B", "-c",
                    "import InquirerPy, jsonschema, mcp, pydantic, rich; "
                    "from google import protobuf",
                ])
            )
            check = (
                subprocess.CompletedProcess([], 0)
                if installer_command else subprocess.run(
                    [str(managed_python), "-B", "-m", "pip", "check"]
                )
            )
            if verify.returncode != 0 or check.returncode != 0:
                return False
            _write_runtime_stamp(lock_digest)
        if active_runtime_root != _managed_runtime_root().absolute():
            argv = [
                str(managed_python), "-B", str(Path(__file__).resolve()),
                *sys.argv[1:],
            ]
            if os.name == "nt":
                # Windows has no native exec(2). Wait for the managed process so
                # its failure cannot be reported as a successful parent exit.
                raise SystemExit(subprocess.call(argv))
            os.execv(str(managed_python), argv)
        if installer_command:
            source_root = Path(__file__).absolute().parent
            full_lock = source_root / "requirements-runtime-full.lock"
            if not full_lock.is_file() or full_lock.is_symlink():
                raise RuntimeError("reviewed full Python runtime lock is unavailable")
            authority = _python_dependency_authority(source_root)
            validated_observation = []
            census_started = time.monotonic()
            print("  Scanning exact managed Python dependency runtime...")
            status = _python_dependency_stamp_status(
                authority, validated_observation=validated_observation,
            )
            if status != "VALID":
                print("  Repairing exact hash-locked Python dependency runtime...")
                if not _retire_legacy_python_dependency_stamp():
                    raise RuntimeError(
                        "legacy in-runtime dependency stamp could not be retired safely"
                    )
                install = subprocess.run([
                    str(managed_python.resolve(strict=True)), "-B", "-m", "pip", "install",
                    "--disable-pip-version-check", "--require-hashes",
                    "--only-binary=:all:", "-r", str(full_lock),
                ])
                if install.returncode != 0:
                    return False
                authority = _python_dependency_authority(source_root)
                candidate = _write_python_dependency_stamp(
                    authority, retain_manifest=True
                )
                diagnostics = []
                if _python_dependency_stamp_status(
                    authority,
                    expected_manifest=candidate,
                    diagnostics=diagnostics,
                ) != "VALID":
                    raise RuntimeError(
                        "candidate Python dependency census did not replay: "
                        + (diagnostics[0] if diagnostics else "bounded diff unavailable")
                    )
                probe = subprocess.run([
                    str(managed_python.resolve(strict=True)), "-I", "-B", "-c",
                    "import InquirerPy, chromadb, jsonschema, mcp, pydantic, rich, "
                    "sentence_transformers; from google import protobuf",
                ])
                check = subprocess.run([
                    str(managed_python.resolve(strict=True)), "-B", "-m", "pip", "check",
                ])
                if probe.returncode != 0 or check.returncode != 0:
                    _invalidate_python_dependency_stamp()
                    return False
                candidate = _write_python_dependency_stamp(
                    authority, retain_manifest=True
                )
                diagnostics = []
                if _python_dependency_stamp_status(
                    authority,
                    expected_manifest=candidate,
                    diagnostics=diagnostics,
                ) != "VALID":
                    raise RuntimeError(
                        "final Python dependency census did not replay: "
                        + (diagnostics[0] if diagnostics else "bounded diff unavailable")
                    )
            else:
                observation = validated_observation[0]
                summary = observation["census_summary"]
                print(
                    "  Verified managed Python runtime: "
                    f"{summary['file_count']:,} files, "
                    f"{summary['total_bytes']:,} bytes in "
                    f"{time.monotonic() - census_started:.1f}s."
                )
                print(
                    "  Reusing this verified census once during install setup; "
                    "no second full scan will run."
                )
                probe = subprocess.run([
                    str(managed_python.resolve(strict=True)), "-I", "-B", "-c",
                    "import InquirerPy, rich",
                ])
                if probe.returncode != 0:
                    return False
                _publish_python_dependency_bootstrap_attestation(
                    source_root=source_root,
                    authority_digest=authority,
                    stamp_observation=observation,
                    census_summary=summary,
                )
        import rich, InquirerPy  # noqa: F401
        return True
    except (OSError, subprocess.SubprocessError) as exc:
        sys.stderr.write(f"Error: could not prepare the reviewed Python runtime: {exc}\n")
        return False

if not _bootstrap():
    print("Error: Could not prepare Plamen's hash-locked Python runtime.")
    sys.exit(1)

