def _drain_stdin():
    """Flush buffered keystrokes so a stray Enter from a prior prompt or
    from scrolling output does not auto-submit the next interactive prompt.
    Fixes the chained-prompt input-bleed where a checkbox returned [] before
    the user could interact."""
    try:
        if sys.platform == "win32":
            import msvcrt
            while msvcrt.kbhit():
                msvcrt.getwch()
        else:
            import termios
            termios.tcflush(sys.stdin.fileno(), termios.TCIFLUSH)
    except Exception:
        pass

# ── Paths ───────────────────────────────────────────────────
# PLAMEN_HOME: where the Plamen repo actually lives (resolves through symlinks)
# CLAUDE_HOME: where Claude Code reads config from (always ~/.claude)
PLAMEN_HOME = os.path.dirname(os.path.abspath(__file__))
CLAUDE_HOME = os.path.expanduser("~/.claude")
_TOOLCHAIN_VERSION_LOCK_SCHEMA = "plamen.toolchain_version_lock.v1"
_TOOLCHAIN_VERSION_LOCK_PATH = os.path.join(
    PLAMEN_HOME,
    "verification_policy",
    "toolchain_version_lock.v1.json",
)
_TOOLCHAIN_GOVERNANCE_PATH = os.path.join(
    PLAMEN_HOME,
    "verification_policy",
    "toolchain_governance.v1.json",
)


def _toolchain_control_module():
    """Import the stdlib-only toolchain authority module from this checkout."""
    scripts_dir = os.path.join(PLAMEN_HOME, "scripts")
    if scripts_dir not in sys.path:
        sys.path.insert(0, scripts_dir)
    import toolchain_control_authority

    return toolchain_control_authority


def _toolchain_runtime_closure_from_root(root):
    """Read the typed closure from an installed generation, not this module."""
    path = os.path.join(
        os.path.normpath(os.fspath(root)),
        "verification_policy", "toolchain_runtime_closure.v1.json",
    )
    with open(path, "rb") as stream:
        value = _strict_json_bytes(stream.read())
    if (
        set(value) != {
            "assets", "derivation", "entrypoints", "files",
            "manifest_control", "schema",
        }
        or value.get("schema") != "plamen.toolchain-runtime-closure.v1"
        or value.get("manifest_control") != {
            "kind": "control",
            "path": "verification_policy/toolchain_runtime_closure.v1.json",
        }
        or not isinstance(value.get("files"), list)
        or not isinstance(value.get("assets"), list)
    ):
        raise RuntimeError("installed runtime closure manifest is malformed")
    files = tuple(value["files"])
    if (
        len(files) != len(set(files))
        or any(
            not isinstance(item, str)
            or PurePosixPath(item).is_absolute()
            or ".." in PurePosixPath(item).parts
            or PurePosixPath(item).as_posix() != item
            for item in files
        )
        or value["manifest_control"]["path"] not in files
    ):
        raise RuntimeError("installed runtime closure file denominator is malformed")
    rows = []
    seen = set()
    for row in value["assets"]:
        if (
            not isinstance(row, dict)
            or set(row) != {"digest_mode", "kind", "path", "sha256"}
            or row.get("digest_mode") not in {"raw-v1", "utf8-lf-v1"}
            or row.get("path") not in files
            or row.get("path") in seen
            or not re.fullmatch(r"[0-9a-f]{64}", row.get("sha256", ""))
            or not isinstance(row.get("kind"), str)
            or not row["kind"]
        ):
            raise RuntimeError("installed runtime closure asset row is malformed")
        seen.add(row["path"])
        rows.append(dict(row))
    if seen != set(files) - {value["manifest_control"]["path"]}:
        raise RuntimeError("installed runtime closure asset denominator differs")
    return files, tuple(rows)


def _toolchain_runtime_required_files(root=None):
    """Return the one shared package/install/runtime file denominator."""
    if root is not None:
        return _toolchain_runtime_closure_from_root(root)[0]
    module = _toolchain_control_module()
    return tuple(module.TOOLCHAIN_RUNTIME_REQUIRED_FILES)


def _toolchain_runtime_asset_rows(root=None):
    """Return digest-bound typed rows from the shared v2 closure manifest."""
    if root is not None:
        return _toolchain_runtime_closure_from_root(root)[1]
    module = _toolchain_control_module()
    return tuple(dict(row) for row in module.TOOLCHAIN_RUNTIME_ASSET_ROWS)


def _toolchain_runtime_required_integrity_issues(root, *, closure_root=None):
    """Return the runtime denominator's absent and digest-mismatched paths."""
    import hashlib

    root = os.path.normpath(os.fspath(root))
    try:
        required = _toolchain_runtime_required_files(closure_root)
    except Exception as exc:
        # The denominator provider is itself required.  A damaged public
        # package must fail doctor/install cleanly instead of crashing before
        # it can explain why the runtime is incomplete.
        return {
            "missing": [
                "scripts/toolchain_control_authority.py "
                f"(denominator unavailable: {type(exc).__name__})"
            ],
            "mismatched": [],
        }
    try:
        expected = {
            row["path"]: (row["digest_mode"], row["sha256"])
            for row in _toolchain_runtime_asset_rows(closure_root)
        }
    except Exception as exc:
        return {
            "missing": [
                "verification_policy/toolchain_runtime_closure.v1.json "
                f"(typed rows unavailable: {type(exc).__name__})"
            ],
            "mismatched": [],
        }
    missing = [
        relative
        for relative in required
        if not os.path.isfile(
            os.path.join(root, *relative.split("/"))
        )
    ]
    # Presence is checked as one complete pass first. When anything is absent,
    # return the exact absence set without spending time hashing unrelated
    # assets; a complete tree then receives the full digest pass below.
    if missing:
        return {"missing": missing, "mismatched": []}
    mismatched = []
    for relative in required:
        path = os.path.join(root, *relative.split("/"))
        expected_row = expected.get(relative)
        if expected_row is None:
            continue
        digest_mode, expected_digest = expected_row
        try:
            with open(path, "rb") as stream:
                raw = stream.read()
            canonical = (
                raw.decode("utf-8")
                .replace("\r\n", "\n")
                .encode("utf-8")
                if digest_mode == "utf8-lf-v1"
                else raw
            )
            observed = hashlib.sha256(canonical).hexdigest()
        except (OSError, UnicodeError):
            missing.append(relative)
            continue
        if observed != expected_digest:
            mismatched.append(relative)
    return {"missing": missing, "mismatched": mismatched}


def _toolchain_runtime_required_missing(root):
    """Compatibility projection of every runtime integrity failure."""
    issues = _toolchain_runtime_required_integrity_issues(root)
    return [*issues["missing"], *issues["mismatched"]]


def _toolchain_runtime_bundle_sha256(root, *, closure_root=None):
    """Digest the exact runtime denominator, including names and bytes."""

    import hashlib

    root = os.path.normpath(os.fspath(root))
    required = _toolchain_runtime_required_files(closure_root)
    issues = _toolchain_runtime_required_integrity_issues(
        root, closure_root=closure_root,
    )
    missing = [*issues["missing"], *issues["mismatched"]]
    if missing:
        raise RuntimeError(
            "runtime bundle is incomplete: " + ", ".join(missing)
        )
    digest = hashlib.sha256()
    for relative in required:
        path = os.path.join(root, *relative.split("/"))
        encoded_name = relative.encode("utf-8")
        digest.update(len(encoded_name).to_bytes(8, "big"))
        digest.update(encoded_name)
        size = os.path.getsize(path)
        digest.update(size.to_bytes(8, "big"))
        with open(path, "rb") as stream:
            while True:
                block = stream.read(1024 * 1024)
                if not block:
                    break
                digest.update(block)
    return digest.hexdigest()


def _load_toolchain_version_lock_legacy(path=None):
    """Load the reviewed setup/runtime identity denominator.

    This is local control data only. It never resolves a registry, installer,
    package manager, or mutable release channel.
    """
    import json

    lock_path = os.path.normpath(path or _TOOLCHAIN_VERSION_LOCK_PATH)
    try:
        with open(lock_path, "r", encoding="utf-8") as source:
            payload = json.load(source)
    except Exception as exc:
        raise RuntimeError(
            f"toolchain version lock is unreadable: {type(exc).__name__}"
        ) from exc
    identities = payload.get("identities") if isinstance(payload, dict) else None
    if (
        payload.get("schema_version") != _TOOLCHAIN_VERSION_LOCK_SCHEMA
        or not isinstance(identities, list)
        or not identities
    ):
        raise RuntimeError("toolchain version lock schema is invalid")
    seen = set()
    for row in identities:
        if not isinstance(row, dict):
            raise RuntimeError("toolchain version lock identity is invalid")
        identity_id = str(row.get("identity_id") or "")
        expected = str(row.get("expected_version") or "")
        identity_kind = str(row.get("identity_kind") or "")
        package_name = str(row.get("package_name") or "")
        install_spec = str(row.get("install_spec") or "")
        probe = row.get("version_probe")
        parser = str(row.get("version_output_parser") or "")
        if (
            not re.fullmatch(r"[a-z0-9][a-z0-9_.-]{0,63}", identity_id)
            or identity_id in seen
            or not re.fullmatch(r"\d+\.\d+\.\d+", expected)
            or identity_kind not in {"command", "python_distribution"}
            or not package_name
            or not install_spec
            or not isinstance(probe, list)
            or not probe
            or not all(isinstance(item, str) and item for item in probe)
            or row.get("acquisition_scope") != "SETUP_ONLY"
            or row.get("deterministic_provider_authority_requires")
            != "MATCH"
        ):
            raise RuntimeError(
                f"toolchain version lock identity is invalid: {identity_id!r}"
            )
        if identity_kind == "python_distribution":
            if (
                parser != "PYTHON_METADATA_EXACT"
                or not str(row.get("python_module") or "")
                or install_spec != f"{package_name}=={expected}"
                or probe
                != ["python-importlib-metadata", package_name]
            ):
                raise RuntimeError(
                    f"toolchain version lock identity is invalid: "
                    f"{identity_id!r}"
                )
            generated = str(row.get("generated_code_version") or "")
            if generated:
                try:
                    generated_tuple = tuple(
                        map(int, generated.split("."))
                    )
                    runtime_tuple = tuple(map(int, expected.split(".")))
                except (TypeError, ValueError):
                    generated_tuple = ()
                    runtime_tuple = ()
                if (
                    len(generated_tuple) != 3
                    or len(runtime_tuple) != 3
                    or generated_tuple[0] != runtime_tuple[0]
                    or generated_tuple > runtime_tuple
                    or (
                        identity_id == "protobuf"
                        and row.get("generated_module_path")
                        != "plamen_l1/scip_pb2.py"
                    )
                ):
                    raise RuntimeError(
                        f"toolchain version lock identity is invalid: "
                        f"{identity_id!r}"
                    )
            if identity_id == "protobuf" and not generated:
                raise RuntimeError(
                    f"toolchain version lock identity is invalid: "
                    f"{identity_id!r}"
                )
        elif (
            parser != "SCIP_GO_EXACT_V1"
            or install_spec != f"{package_name}@v{expected}"
            or probe[0] != identity_id
        ):
            raise RuntimeError(
                f"toolchain version lock identity is invalid: {identity_id!r}"
            )
        if identity_id == "scip-go" and (
            row.get("go_command_path")
            != "github.com/scip-code/scip-go/cmd/scip-go"
            or row.get("go_module_path")
            != "github.com/scip-code/scip-go"
            or package_name != row.get("go_command_path")
        ):
            raise RuntimeError(
                f"toolchain version lock identity is invalid: {identity_id!r}"
            )
        seen.add(identity_id)
    return payload


def _load_toolchain_version_lock(path=None, governance_path=None):
    """Load the single reviewed lock/governance control pair used at runtime."""

    try:
        toolchain_control_authority = _toolchain_control_module()
        controls = toolchain_control_authority.load_toolchain_controls(
            Path(governance_path or _TOOLCHAIN_GOVERNANCE_PATH),
            Path(path or _TOOLCHAIN_VERSION_LOCK_PATH),
        )
    except Exception as exc:
        error_type = getattr(
            locals().get("toolchain_control_authority"),
            "ToolchainControlError",
            (),
        )
        if error_type and isinstance(exc, error_type):
            raise RuntimeError(str(exc)) from exc
        raise RuntimeError(
            f"toolchain controls are unreadable: {type(exc).__name__}"
        ) from exc
    return dict(controls.lock)


def _load_toolchain_governance(path=None, lock_path=None):
    """Load governance from the same closed control authority as the lock."""
    try:
        toolchain_control_authority = _toolchain_control_module()
        controls = toolchain_control_authority.load_toolchain_controls(
            Path(path or _TOOLCHAIN_GOVERNANCE_PATH),
            Path(lock_path or _TOOLCHAIN_VERSION_LOCK_PATH),
        )
    except Exception as exc:
        error_type = getattr(
            locals().get("toolchain_control_authority"),
            "ToolchainControlError",
            (),
        )
        if error_type and isinstance(exc, error_type):
            raise RuntimeError(str(exc)) from exc
        raise RuntimeError(
            f"toolchain controls are unreadable: {type(exc).__name__}"
        ) from exc
    return dict(controls.governance)


def _locked_toolchain_identity(identity_id):
    for row in _load_toolchain_version_lock()["identities"]:
        if row["identity_id"] == identity_id:
            return dict(row)
    raise RuntimeError(
        f"toolchain version lock omits identity: {identity_id}"
    )


def _version_identity_status(expected, observed, identity_id=""):
    """Classify one local version observation without acquiring anything."""
    observed = str(observed or "UNAVAILABLE").strip()
    if not observed or observed.upper() in {
        "UNAVAILABLE",
        "TIMEOUT",
    } or observed.upper().startswith("ERROR:"):
        return "UNAVAILABLE"
    if identity_id == "scip-go":
        lines = [line.strip() for line in observed.splitlines() if line.strip()]
        matched = (
            len(lines) == 1
            and re.fullmatch(
                rf"(?i:(?:scip-go(?:\s+version)?\s+)?v?"
                rf"{re.escape(str(expected))})",
                lines[0],
            )
            is not None
        )
    else:
        matched = observed == str(expected)
    return "MATCH" if matched else "MISMATCH"


def _observed_locked_command_version(row):
    probe = list(row["version_probe"])
    binary_name = probe[0]
    search_paths = _GO_PATHS if binary_name == "scip-go" else []
    path = _find_bin(binary_name)
    if not path and search_paths:
        path = _find_bin(binary_name, search_paths)
    if not path:
        return "UNAVAILABLE"
    try:
        result = subprocess.run(
            [path, *probe[1:]],
            timeout=5,
            capture_output=True,
            text=True,
            encoding="utf-8",
            errors="replace",
        )
    except subprocess.TimeoutExpired:
        return "TIMEOUT"
    except (FileNotFoundError, PermissionError, OSError) as exc:
        return f"ERROR:{exc.__class__.__name__}"
    output = ((result.stdout or "") + (result.stderr or "")).strip()
    if result.returncode != 0 or not output:
        return f"ERROR:rc={result.returncode}"
    return output[:4096]


def _observed_python_distribution_version(distribution):
    try:
        from importlib.metadata import PackageNotFoundError, version

        return version(distribution)
    except PackageNotFoundError:
        return "UNAVAILABLE"
    except Exception as exc:
        return f"ERROR:{type(exc).__name__}"


def _locked_identity_is_current(identity_id, *, search_paths=None):
    """Return true only when the reviewed identity is locally observed exactly."""
    row = _locked_toolchain_identity(identity_id)
    kind = str(row.get("identity_kind") or "")
    if kind == "python_distribution":
        observed = _observed_python_distribution_version(row["package_name"])
    elif kind == "command":
        observed = _observed_locked_command_version(row)
    else:
        return False
    return (
        _version_identity_status(
            row["expected_version"],
            observed,
            identity_id,
        )
        == "MATCH"
    )


def _slither_is_current():
    # Recon executes the installed Python module, not a PATH-resolved Slither
    # console script.  A same-named or stale CLI therefore cannot authorize
    # (or invalidate) the reviewed distribution/module identity.
    return _locked_identity_is_current("slither")


def _scip_go_is_current():
    return bool(
        _find_bin("scip-go", _GO_PATHS)
        and _locked_identity_is_current("scip-go")
    )


def _protobuf_runtime_is_current():
    if not _locked_identity_is_current("protobuf"):
        return False
    row = _locked_toolchain_identity("protobuf")
    generated = os.path.join(PLAMEN_HOME, "plamen_l1", "scip_pb2.py")
    try:
        with open(generated, "r", encoding="utf-8") as source:
            text = source.read(8192)
    except OSError:
        return False
    matches = re.findall(
        r"(?m)^# Protobuf Python Version: "
        r"([0-9]+\.[0-9]+\.[0-9]+)\s*$",
        text,
    )
    if len(matches) != 1 or matches[0] != row.get("generated_code_version"):
        return False
    try:
        generated_version = tuple(map(int, matches[0].split(".")))
        runtime_version = tuple(
            map(int, str(row["expected_version"]).split("."))
        )
    except (TypeError, ValueError):
        return False
    return (
        generated_version[0] == runtime_version[0]
        and generated_version <= runtime_version
    )


def _locked_toolchain_identity_report(
    *,
    command_versions=None,
    distribution_versions=None,
):
    """Return expected-vs-observed rows for doctor without installing tools."""
    command_versions = command_versions if command_versions is not None else {}
    distribution_versions = (
        distribution_versions
        if distribution_versions is not None
        else {}
    )
    supplied_commands = command_versions is not None and bool(
        command_versions
    )
    supplied_distributions = distribution_versions is not None and bool(
        distribution_versions
    )
    governed = {
        row["tool_id"]: row
        for row in _load_toolchain_governance()["tools"]
    }
    rows = []
    for locked in _load_toolchain_version_lock()["identities"]:
        identity_id = locked["identity_id"]
        if locked["identity_kind"] == "command":
            observed = (
                str(command_versions.get(identity_id, "UNAVAILABLE"))
                if supplied_commands
                else _observed_locked_command_version(locked)
            )
        elif locked["identity_kind"] == "python_distribution":
            observed = (
                str(distribution_versions.get(identity_id, "UNAVAILABLE"))
                if supplied_distributions
                else _observed_python_distribution_version(
                    locked["package_name"]
                )
            )
        else:
            raise RuntimeError(
                f"unsupported locked identity kind: {locked['identity_kind']}"
            )
        identity_status = _version_identity_status(
            locked["expected_version"],
            observed,
            identity_id,
        )
        authority = dict(governed[identity_id]["runtime_authority"])
        deterministic_authority = (
            authority.get("deterministic_provider_authority") is True
        )
        rows.append({
            "identity_id": identity_id,
            "expected_version": locked["expected_version"],
            "observed_version": observed,
            "identity_status": identity_status,
            "provider_authority_status": authority["identity_status"],
            "deterministic_provider_authority": deterministic_authority,
            "provider_ready": (
                identity_status == "MATCH" and deterministic_authority
            ),
            "acquisition_scope": locked["acquisition_scope"],
        })
    return rows

# ── Version ─────────────────────────────────────────────────
def _read_version() -> str:
    vfile = os.path.join(PLAMEN_HOME, "VERSION")
    try:
        with open(vfile) as f:
            return f.read().strip()
    except FileNotFoundError:
        return "dev"

VERSION = _read_version()


def _check_claude_md_version():
    """Warn if ~/.claude/CLAUDE.md has a stale Plamen injection (different version)."""
    claude_md = os.path.join(CLAUDE_HOME, "CLAUDE.md")
    if not os.path.isfile(claude_md):
        return  # not installed yet
    try:
        with open(claude_md, "r", encoding="utf-8") as f:
            content = f.read()
    except OSError:
        return
    # Look for version in the injected Plamen section
    marker = "<!-- PLAMEN:START"
    if marker not in content:
        return  # no injection found
    injected = content[content.index(marker):]
    # Extract the first "(vX.Y.Z)" version tag from the injected block. The
    # injected header is version-line-agnostic: the current layout carries the
    # version on line 4 ("...autonomous Web3 security auditing agent (v2.1.0).")
    # rather than on the "Security Auditor" title line, so we scan the whole
    # injected block for a "(vMAJOR.MINOR.PATCH)" tag instead of anchoring to a
    # specific surrounding phrase.
    import re
    m = re.search(r"\(v(\d+\.\d+\.\d+)\)", injected)
    if not m:
        return
    injected_ver = m.group(1)
    if injected_ver != VERSION:
        w = sys.stdout.write
        w(f"\n  {_C_ORANGE}Warning: Version mismatch: repo is v{VERSION} but "
          f"~/.claude/CLAUDE.md has v{injected_ver}{_RST}\n")
        w(f"  {_C_GRAY}  Run 'plamen install' to update. Pipeline may behave "
          f"incorrectly until then.{_RST}\n\n")


