class _PlainPrompt:
    def __init__(self, kind, message, choices=None, default=None, validate=None):
        self.kind = kind
        self.message = message
        self.choices = choices or []
        self.default = default
        self.validate = validate

    @staticmethod
    def _rows(choices):
        rows = []
        for choice in choices:
            if isinstance(choice, dict) and "name" in choice:
                rows.append((str(choice["name"]), choice.get("value", choice["name"])))
            elif isinstance(choice, str):
                rows.append((choice, choice))
        return rows

    def execute(self):
        if self.kind == "select":
            rows = self._rows(self.choices)
            if not rows:
                raise RuntimeError("plain wizard prompt has no choices")
            print(f"\n{self.message}")
            for index, (name, _value) in enumerate(rows, 1):
                marker = " (default)" if _value == self.default else ""
                print(f"  {index}. {name}{marker}")
            while True:
                raw = input("Choice: ").strip()
                if not raw and self.default is not None:
                    return self.default
                if raw.isdigit() and 1 <= int(raw) <= len(rows):
                    return rows[int(raw) - 1][1]
                print(f"Enter a number from 1 to {len(rows)}.")
        if self.kind == "checkbox":
            rows = self._rows(self.choices)
            print(f"\n{self.message}")
            for index, (name, _value) in enumerate(rows, 1):
                print(f"  {index}. {name}")
            while True:
                raw = input("Choices (comma-separated, blank for none): ").strip()
                if not raw:
                    return []
                try:
                    indexes = [int(item.strip()) for item in raw.split(",")]
                except ValueError:
                    indexes = []
                if indexes and all(1 <= item <= len(rows) for item in indexes):
                    return [rows[item - 1][1] for item in dict.fromkeys(indexes)]
                print(f"Enter comma-separated numbers from 1 to {len(rows)}.")
        while True:
            suffix = f" [{self.default}]" if self.default not in {None, ""} else ""
            value = input(f"{self.message}{suffix}: ")
            if not value and self.default is not None:
                value = self.default
            verdict = self.validate(value) if callable(self.validate) else True
            if verdict is True:
                return value
            print(str(verdict))


class _PlainInquirer:
    @staticmethod
    def select(message, choices, default=None, **_kwargs):
        return _PlainPrompt("select", message, choices, default)

    @staticmethod
    def checkbox(message, choices, default=None, **_kwargs):
        return _PlainPrompt("checkbox", message, choices, default)

    @staticmethod
    def filepath(message, default=None, validate=None, **_kwargs):
        return _PlainPrompt("filepath", message, default=default, validate=validate)

    @staticmethod
    def text(message, default=None, validate=None, **_kwargs):
        return _PlainPrompt("text", message, default=default, validate=validate)


