def _ast_grep_cmds():
    """Install ast-grep. Prefer cargo (works on all platforms) with brew
    fallback on macOS for a faster binary install."""
    if sys.platform == "darwin" and _has_brew():
        return ['cargo install ast-grep --version 0.45.2 --locked']
    return ['cargo install ast-grep --version 0.45.2 --locked']


