def _codex_install_trim_crt_heap():
    """Best-effort release of unused blocks owned by this process' UCRT heap."""
    report = {
        "attempted": False,
        "succeeded": False,
        "return_code": None,
        "errno": None,
        "error": None,
    }
    if os.name != "nt":
        return report
    import ctypes

    try:
        # _heapmin is cdecl, so bind it through CDLL rather than WinDLL.  It
        # compacts only the active UCRT heap; never enumerate or compact heaps
        # belonging to other runtimes loaded into this process.
        ucrt = ctypes.CDLL("ucrtbase.dll", use_errno=True)
        heapmin = ucrt._heapmin
        heapmin.argtypes = []
        heapmin.restype = ctypes.c_int
        ctypes.set_errno(0)
        report["attempted"] = True
        report["return_code"] = int(heapmin())
        report["errno"] = int(ctypes.get_errno())
        report["succeeded"] = report["return_code"] == 0
    except (AttributeError, OSError, TypeError, ValueError) as exc:
        # Heap trimming is an optimization boundary, never transaction
        # authority.  Preserve a stable, testable report and fail open.
        report["error"] = type(exc).__name__
    return report


def _codex_install_trim_working_set(*, collect=False, report=False):
    """Release installer-owned transient pages after authority folds are sealed."""
    result = {
        "gc_collected": None,
        "crt_heap": None,
        "working_set_attempted": False,
        "working_set_released": False,
        "working_set_error": None,
    }
    if collect:
        result["gc_collected"] = int(gc.collect())
        # Python/ctypes objects must be unreachable before asking the UCRT to
        # return its unused arenas to Windows.
        result["crt_heap"] = _codex_install_trim_crt_heap()
    if os.name != "nt":
        return result if report else False
    import ctypes
    from ctypes import wintypes

    try:
        kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
        psapi = ctypes.WinDLL("psapi", use_last_error=True)
        kernel32.GetCurrentProcess.restype = wintypes.HANDLE
        psapi.EmptyWorkingSet.argtypes = [wintypes.HANDLE]
        psapi.EmptyWorkingSet.restype = wintypes.BOOL
        result["working_set_attempted"] = True
        result["working_set_released"] = bool(
            psapi.EmptyWorkingSet(kernel32.GetCurrentProcess())
        )
        if not result["working_set_released"]:
            result["working_set_error"] = int(ctypes.get_last_error())
    except (AttributeError, OSError, TypeError, ValueError) as exc:
        # This is an optimization boundary, not transaction authority.  A
        # platform that declines trimming must not turn a valid install into
        # rollback.
        result["working_set_error"] = type(exc).__name__
    return result if report else result["working_set_released"]


def _codex_native_directory_names(handle):
    """Enumerate one retained directory handle without reopening its pathname."""
    api = _codex_native_api(); ctypes = api["ctypes"]
    names = []
    restart = True
