def show_hint_panel():
    """Box-drawn panel showing what users need to prepare."""
    w = sys.stdout.write
    bx = _C_BOX
    W = 52  # inner visible width (matches ─ count)

    def row(parts):
        """parts: list of (visible_text, ansi_color_or_None) tuples."""
        vis = sum(len(t) for t, _ in parts)
        colored = "".join(f"{c}{t}{_RST}" if c else t for t, c in parts)
        w(f"  {bx}│{_RST}{colored}{' ' * max(0, W - vis)}{bx}│{_RST}\n")

    w(f"  {bx}╭{'─' * W}╮{_RST}\n")
    row([("  you'll need to provide", _C_GRAY)])
    row([])  # blank line
    row([("  ", None), ("target", _C_GREEN), ("          ", None),
         ("local project directory", _C_GRAY)])
    row([("  ", None), ("docs", _C_GREEN), ("            ", None),
         ("whitepaper or spec (optional)", _C_GRAY)])
    row([("  ", None), ("scope", _C_GREEN), ("           ", None),
         ("scope.txt or notes (optional)", _C_GRAY)])
    row([("  ", None), ("ground truth", _C_GREEN), ("    ", None),
         ("reference report (compare only)", _C_GRAY)])
    w(f"  {bx}╰{'─' * W}╯{_RST}\n")
    w("\n")
    sys.stdout.flush()


# ── Helpers ──────────────────────────────────────────────────

# Dirs skipped at ANY depth (build artifacts, tooling, never contain source)
_SKIP_ALWAYS = {'node_modules', '.git', 'cache', 'artifacts', '.anchor', '.aptos', '.stellar', '.soroban',
                '.daml', 'typechain', 'typechain-types', 'coverage', '__pycache__', 'vendor'}
# Dirs skipped only at project ROOT level (contain deps/tests/scripts, not source)
_SKIP_ROOT = {'lib', 'target', 'build', 'out', 'test', 'tests', 'mock', 'mocks',
              'script', 'deploy', 'migrations', 'flatten', 'docs', 'doc'}
_SC_EXTS = {'.sol', '.rs', '.move'}
_L1_EXTS = {'.go', '.rs'}
_SRC_EXTS = _SC_EXTS | _L1_EXTS


def _count_source_files(d: str) -> int:
    """Count .sol/.rs/.move files recursively, pruning skip dirs on descent."""
    d = os.path.normpath(d)
    total = 0
    for root, dirs, files in os.walk(d):
        if os.path.normpath(root) == d:
            dirs[:] = [x for x in dirs if x not in _SKIP_ALWAYS and x not in _SKIP_ROOT]
        else:
            dirs[:] = [x for x in dirs if x not in _SKIP_ALWAYS]
        total += sum(1 for f in files if os.path.splitext(f)[1] in _SRC_EXTS)
    return total


def _is_home_or_root(d: str) -> bool:
    """Return True if d is a home directory, user root, or system root."""
    d = os.path.normpath(d)
    home = os.path.normpath(os.path.expanduser("~"))
    if d == home or d == os.path.dirname(home):
        return True
    # Windows roots like C:\ or Unix /
    if len(d) <= 3 or d in ("/", "\\"):
        return True
    return False


def _detect_project_hint(d: str) -> str:
    # Skip recursive scan on home/root dirs — they're too large
    if _is_home_or_root(d):
        return ""
    indicators = {
        "foundry.toml": "Foundry", "hardhat.config.js": "Hardhat",
        "hardhat.config.ts": "Hardhat", "truffle-config.js": "Truffle",
        "Anchor.toml": "Anchor", "Move.toml": "Move", "stellar.toml": "Soroban",
        "go.mod": "Go", "Cargo.toml": "Rust",
    }
    for fname, label in indicators.items():
        if os.path.exists(os.path.join(d, fname)):
            total = _count_source_files(d)
            return f"{label} — {total} source files" if total else label
    # No config file — still check for source files
    total = _count_source_files(d)
    if total:
        return f"{total} source files"
    return ""


# ── Detection Helpers ──────────────────────────────────────

_L1_GO_IMPORTS = [
    "reth-", "libp2p", "cometbft", "cosmos-sdk", "beacon-chain",
    "eth/protocols", "fork_choice", "x/staking", "prysm", "lighthouse",
    "tendermint", "consensus/", "p2p/", "core/vm/",
]
_L1_RUST_CRATES = [
    "reth", "lighthouse", "substrate", "libp2p", "tendermint",
    "revm", "alloy-consensus", "sc-consensus", "sp-consensus",
]


def _count_loc(target: str, extensions: set, skip_patterns: set = None) -> int:
    """Count lines of code for given extensions, skipping test files and vendor dirs."""
    skip = skip_patterns or set()
    total = 0
    for root, dirs, files in os.walk(target):
        rel = os.path.relpath(root, target)
        if os.path.normpath(root) == os.path.normpath(target):
            dirs[:] = [x for x in dirs if x not in _SKIP_ALWAYS and x not in _SKIP_ROOT]
        else:
            dirs[:] = [x for x in dirs if x not in _SKIP_ALWAYS]
        for f in files:
            if os.path.splitext(f)[1] not in extensions:
                continue
            low = f.lower()
            if any(p in low for p in ("_test.", "test_", ".test.", "_mock", "mock_")):
                continue
            if any(p in low for p in skip):
                continue
            try:
                fp = os.path.join(root, f)
                with open(fp, "r", errors="ignore") as fh:
                    total += sum(1 for _ in fh)
            except OSError:
                pass
    return total


def _detect_language(target: str) -> str:
    """Detect project language: evm, solana, soroban, aptos, sui, daml, go, rust."""
    sol_count = _count_loc(target, {".sol"})
    go_count = _count_loc(target, {".go"})
    rs_count = _count_loc(target, {".rs"})
    move_count = _count_loc(target, {".move"})
    daml_count = _count_loc(target, {".daml"})

    # .daml is an unambiguous source suffix (one suffix -> one language). When
    # any .daml source is present and at least co-dominant, the project is DAML.
    if daml_count > 0 and daml_count >= max(sol_count, go_count, rs_count, move_count):
        return "daml"

    if sol_count > 0 and sol_count >= max(go_count, rs_count, move_count):
        return "evm"

    if move_count > 0 and move_count >= max(sol_count, go_count, rs_count):
        move_toml = os.path.join(target, "Move.toml")
        if os.path.isfile(move_toml):
            try:
                with open(move_toml, "r", errors="ignore") as f:
                    content = f.read()
                if "AptosFramework" in content or "aptos" in content.lower():
                    return "aptos"
            except OSError:
                pass
        return "sui"

    if rs_count > 0 and rs_count >= max(sol_count, go_count, move_count):
        cargo_toml = os.path.join(target, "Cargo.toml")
        if os.path.isfile(cargo_toml):
            try:
                with open(cargo_toml, "r", errors="ignore") as f:
                    content = f.read().lower()
                if "soroban" in content or "stellar" in content:
                    return "soroban"
                if "anchor" in content or "solana" in content:
                    return "solana"
                if any(c in content for c in _L1_RUST_CRATES):
                    return "rust"
            except OSError:
                pass
        # Check workspace members for deeper Cargo.toml files
        for sub in os.listdir(target):
            sub_cargo = os.path.join(target, sub, "Cargo.toml")
            if os.path.isfile(sub_cargo):
                try:
                    with open(sub_cargo, "r", errors="ignore") as f:
                        c = f.read().lower()
                    if "soroban" in c or "stellar" in c:
                        return "soroban"
                    if "anchor" in c or "solana" in c:
                        return "solana"
                except OSError:
                    pass
        return "rust"

    if go_count > 0 and go_count >= max(sol_count, rs_count, move_count):
        return "go"

    # Fallback: check config files
    if os.path.isfile(os.path.join(target, "Anchor.toml")):
        return "solana"
    if os.path.isfile(os.path.join(target, "foundry.toml")):
        return "evm"
    if os.path.isfile(os.path.join(target, "go.mod")):
        return "go"
    return "evm"


def _detect_pipeline(language: str) -> str:
    """Map language to pipeline: 'sc' or 'l1'."""
    if language in ("go", "rust"):
        return "l1"
    return "sc"


def _detect_l1_tier(loc: int) -> str:
    if loc < 2000:
        return "t0"
    if loc < 30000:
        return "t1"
    if loc <= 100000:
        return "t2"
    return "t3"


_L1_TIER_LABELS = {
    "t0": ("T0 — Patch", "<=2k LOC diff, PR/commit review"),
    "t1": ("T1 — Subsystem", "5-30k LOC, one module cluster"),
    "t2": ("T2 — Whole-client", "30-100k LOC, full codebase"),
    "t3": ("T3 — Full screen", ">100k LOC, breadth over depth"),
}


_WORKSPACE_CONTAINERS = {
    'crates', 'packages', 'subcrates', 'libs', 'components',
    'cmd', 'pkg', 'internal', 'modules',
}


def _scan_modules(target: str, language: str) -> list:
    """Enumerate project modules with LOC counts. Returns [(name, path, loc)].

    Expands workspace container dirs (crates/, cmd/, pkg/, internal/, etc.)
    into their children so each subcrate/subpackage appears as a selectable module.
    """
    exts = {".go"} if language == "go" else {".rs"}
    skip = _SKIP_ALWAYS | _SKIP_ROOT
    modules = []
    try:
        entries = sorted(os.listdir(target))
    except OSError:
        return []
    for entry in entries:
        full = os.path.join(target, entry)
        if not os.path.isdir(full):
            continue
        if entry in skip or entry.startswith("."):
            continue
        if entry.lower() in _WORKSPACE_CONTAINERS:
            try:
                children = sorted(os.listdir(full))
            except OSError:
                children = []
            for child in children:
                child_full = os.path.join(full, child)
                if not os.path.isdir(child_full):
                    continue
                if child in _SKIP_ALWAYS or child.startswith("."):
                    continue
                loc = _count_loc(child_full, exts)
                if loc > 0:
                    modules.append((f"{entry}/{child}", child_full, loc))
            continue
        loc = _count_loc(full, exts)
        if loc > 0:
            modules.append((entry, full, loc))
    return modules


def _detect_fork(target: str) -> bool:
    """Check for fork indicators: upstream remote or README mentions."""
    try:
        r = subprocess.run(
            ["git", "remote", "-v"], capture_output=True, text=True,
            cwd=target, timeout=5)
        if r.returncode == 0 and "upstream" in r.stdout.lower():
            return True
    except Exception:
        pass
    for readme in ("README.md", "README", "readme.md"):
        rp = os.path.join(target, readme)
        if os.path.isfile(rp):
            try:
                with open(rp, "r", errors="ignore") as f:
                    head = f.read(2000).lower()
                if "fork" in head and ("upstream" in head or "based on" in head):
                    return True
            except OSError:
                pass
    return False


def _l1_stages(mode, bc, vc, est_findings, src_tok, total_lines,
               PROMPT_BASE, SKILL_AVG, ARTIFACT_SMALL, ARTIFACT_LARGE, orch_base):
    """Build L1 pipeline stage list for cost estimation.

    L1 differs from SC: bake phase, no chain analysis, no instantiate,
    graph sweeps + location recovery (thorough), more verify shards,
    larger codebases with module-scoped agents.
    """
    # L1 breadth agents are module-scoped — each sees a smaller source slice
    # but L1 codebases are much larger, so cap the per-agent source fraction
    src_per_agent = min(src_tok, int(src_tok * 0.3))

    # L1 verify shards: 10 high + 6 medium + 4 low (thorough), scaled by findings
    vc_high = min(10, max(2, int(est_findings * 0.3)))
    vc_med = min(6, max(2, int(est_findings * 0.25)))
    vc_low = min(4, max(1, int(est_findings * 0.15)))

    if mode == "light":
        bc_l = min(3, max(2, bc))
        vc_l = min(4, max(2, est_findings // 4))
        return [
            ("Bake",             1, "sonnet", PROMPT_BASE + int(src_tok * 0.2), 6),
            ("Recon",            2, "sonnet", PROMPT_BASE + int(src_tok * 0.4) + ARTIFACT_SMALL, 10),
            ("Breadth",          bc_l, "sonnet", PROMPT_BASE + SKILL_AVG + src_per_agent + ARTIFACT_LARGE, 10),
            ("Inventory",        1, "sonnet", PROMPT_BASE + ARTIFACT_LARGE * 2, 8),
            ("Depth (merged)",   3, "sonnet", PROMPT_BASE + SKILL_AVG * 2 + int(src_tok * 0.2) + ARTIFACT_LARGE, 10),
            ("Verification",     vc_l, "sonnet", PROMPT_BASE + SKILL_AVG + int(src_tok * 0.15) + ARTIFACT_SMALL, 12),
            ("Report",           1, "sonnet", PROMPT_BASE + ARTIFACT_LARGE * 2, 8),
            ("Report assembler", 1, "haiku",  PROMPT_BASE + ARTIFACT_LARGE * 2, 6),
            ("Orchestrator",     1, "sonnet", orch_base, 20),
        ]

    # Core stages (Thorough appends below)
    stages = [
        ("Bake",             1, "sonnet", PROMPT_BASE + int(src_tok * 0.2), 8),
        ("Recon (opus)",     2, "opus",   PROMPT_BASE + int(src_tok * 0.5) + ARTIFACT_SMALL, 12),
        ("Recon (sonnet)",   2, "sonnet", PROMPT_BASE + int(src_tok * 0.2) + ARTIFACT_SMALL, 10),
        ("Breadth",         bc, "sonnet", PROMPT_BASE + SKILL_AVG + src_per_agent + ARTIFACT_LARGE, 12),
        ("Inventory",        4, "sonnet", PROMPT_BASE + ARTIFACT_LARGE * 2, 8),
        ("Sem. Invariants",  1, "sonnet", PROMPT_BASE + int(src_tok * 0.3) + ARTIFACT_SMALL, 10),
        ("Depth (opus)",     3, "opus",   PROMPT_BASE + SKILL_AVG + int(src_tok * 0.2) + ARTIFACT_LARGE, 12),
        ("Depth (sonnet)",   2, "sonnet", PROMPT_BASE + SKILL_AVG + int(src_tok * 0.2) + ARTIFACT_LARGE, 10),
        ("RAG + Scoring",    3, "haiku",  PROMPT_BASE + ARTIFACT_LARGE, 6),
        ("Semantic Dedup",   1, "sonnet", PROMPT_BASE + ARTIFACT_LARGE * 2, 8),
        ("Verify (high)",    vc_high, "sonnet", PROMPT_BASE + SKILL_AVG + int(src_tok * 0.15) + ARTIFACT_SMALL, 12),
        ("Verify (medium)",  vc_med, "sonnet", PROMPT_BASE + SKILL_AVG + int(src_tok * 0.15) + ARTIFACT_SMALL, 12),
        ("Report (sonnet)",  3, "sonnet", PROMPT_BASE + ARTIFACT_LARGE * 2, 8),
        ("Report (haiku)",   2, "haiku",  PROMPT_BASE + ARTIFACT_LARGE * 2, 6),
        ("Orchestrator",     1, "opus",   orch_base, 25),
    ]

    if mode == "thorough":
        est_high_crit = max(2, int(est_findings * 0.3))
        est_judge = max(1, est_high_crit // 3)
        stages += [
            ("Graph Sweeps",     1, "sonnet", PROMPT_BASE + int(src_tok * 0.3) + ARTIFACT_LARGE, 10),
            ("Location Recov.",  1, "sonnet", PROMPT_BASE + ARTIFACT_LARGE, 8),
            ("Attention Repair", 1, "sonnet", PROMPT_BASE + int(src_tok * 0.2) + ARTIFACT_LARGE, 10),
            ("Verify (low)",     vc_low, "sonnet", PROMPT_BASE + SKILL_AVG + int(src_tok * 0.1) + ARTIFACT_SMALL, 10),
            ("Skeptic",          est_high_crit, "sonnet",
             PROMPT_BASE + SKILL_AVG + int(src_tok * 0.15) + ARTIFACT_SMALL, 10),
            ("Judge",            est_judge, "haiku",
             PROMPT_BASE + ARTIFACT_SMALL * 2, 4),
            ("Cross-batch",      1, "sonnet", PROMPT_BASE + ARTIFACT_LARGE, 8),
            ("Orch. extra",      1, "opus",   orch_base, 15),
        ]

    return stages


def estimate_cost(target: str, mode: str,
                  scope_file: str = "", scope_notes: str = "",
                  pipeline: str = "sc", backend: str = "claude",
                  subsystem_scope: str = "") -> dict:
    """Estimate audit resource usage by modeling pipeline stages with context accumulation.

    Each subagent is a multi-turn conversation where every turn re-sends the full
    prior context. A 10-turn agent with 30K base context consumes ~400-500K input
    tokens total, not 30K. This model accounts for that accumulation.

    Respects scope constraints: if scope_file or scope_notes list specific contracts,
    only those files are counted for the estimate.
    pipeline='l1' uses L1-specific phases, extensions (.go/.rs), and scaling.
    subsystem_scope: comma-separated module paths for L1 T1 (e.g. 'crates/p2p,crates/rpc').

    Returns: lines, files, agents, est_input_mtok, plan_pct (Max x5 / x20)
    """
    # ── Build scope filter ──────────────────────────────────
    # Extract filenames/contract names from scope_file or scope_notes
    scope_names = set()  # lowercase basenames or stems to match against

    if scope_file and os.path.isfile(scope_file):
        try:
            import re as _re
            with open(scope_file, 'r', errors='ignore') as sf:
                for line in sf:
                    line = line.strip()
                    if not line or line.startswith('#') or line.startswith('//'):
                        continue
                    # Extract .sol/.rs/.move filenames from any format:
                    #   bare paths: "src/contracts/Vault.sol"
                    #   markdown tables: "| MessageRouter.sol | 301 |"
                    #   bullet lists: "- contracts/Vault.sol"
                    matches = _re.findall(r'[\w/\\.-]+\.(?:sol|rs|move)', line)
                    if matches:
                        for m in matches:
                            base = os.path.basename(m)
                            scope_names.add(base.lower())
                            stem = os.path.splitext(base)[0].lower()
                            if stem:
                                scope_names.add(stem)
                    else:
                        # Fallback: treat entire line as a path
                        base = os.path.basename(line.strip().rstrip('/'))
                        if base and '.' in base:
                            scope_names.add(base.lower())
                            stem = os.path.splitext(base)[0].lower()
                            if stem:
                                scope_names.add(stem)
        except Exception:
            pass

    if scope_notes and not scope_names:
        # Parse contract names from free-text notes
        # e.g., "focus on Vault, Router, Pool contracts"
        import re
        # Match capitalized words that look like contract names
        words = re.findall(r'\b([A-Z][a-zA-Z0-9_]+)\b', scope_notes)
        for w in words:
            scope_names.add(w.lower())
            # Also add .sol/.rs/.move variants
            scope_names.add(w.lower() + '.sol')
            scope_names.add(w.lower() + '.rs')
            scope_names.add(w.lower() + '.move')

    has_scope = len(scope_names) > 0

    # ── L1 module scoping: restrict walk to subsystem paths ─
    module_roots = []
    if subsystem_scope and pipeline == "l1":
        for mod_path in subsystem_scope.split(","):
            mod_path = mod_path.strip()
            if mod_path:
                full = os.path.join(target, mod_path)
                if os.path.isdir(full):
                    module_roots.append(os.path.normpath(full))

    # ── Count source files and lines ────────────────────────
    total_files = 0
    total_lines = 0

    # Skip recursive scan on home/root dirs — too large, no useful results
    if _is_home_or_root(target):
        return {
            "files": 0, "lines": 0, "agents": 0,
            "input_mtok": 0, "output_mtok": 0, "api_cost": 0,
            "pct_x5": 0, "pct_x20": 0, "pct_pro": 0, "scoped": False,
        }

    walk_targets = module_roots if module_roots else [target]
    for walk_root in walk_targets:
        walk_root_norm = os.path.normpath(walk_root)
        for root, dirs, files in os.walk(walk_root):
            if os.path.normpath(root) == walk_root_norm and not module_roots:
                dirs[:] = [x for x in dirs if x not in _SKIP_ALWAYS and x not in _SKIP_ROOT]
            else:
                dirs[:] = [x for x in dirs if x not in _SKIP_ALWAYS]
            exts = _L1_EXTS if pipeline == "l1" else _SC_EXTS
            for fname in files:
                if os.path.splitext(fname)[1] not in exts:
                    continue

                # Apply scope filter if we have scope constraints
                if has_scope:
                    basename = fname.lower()
                    stem = os.path.splitext(basename)[0]
                    if not (basename in scope_names or stem in scope_names):
                        continue

                total_files += 1
                try:
                    with open(os.path.join(root, fname), 'r', errors='ignore') as fh:
                        total_lines += sum(1 for _ in fh)
                except Exception:
                    pass

    src_tok = total_lines * 4  # ~4 tokens per line of code
    effective_lines = total_lines
    if pipeline == "l1" and total_lines > 30_000:
        # L1 V2 does not stream the full client into every agent. Recon and
        # breadth build bounded summaries/shard packets, then later phases
        # consume those artifacts. Past estimates scaled near-linearly with
        # total LOC, which made 150k-250k LOC clients look 3x too expensive.
        # Keep a small logarithmic lift for larger clients, but cap the code
        # context used by the estimate to match the bounded driver behavior.
        import math
        effective_lines = 30_000 + int(
            min(10_000, math.log2(max(total_lines / 30_000, 1.0)) * 3_000)
        )
        src_tok = effective_lines * 4

    # ── Agent token model with context accumulation ─────────
    # Each agent turn re-sends full prior context. Total input for N turns:
    #   sum(base + i * growth for i in range(turns))
    #   = turns * base + turns*(turns-1)/2 * growth
    # base = system_prompt + CLAUDE.md + skill + artifacts + source subset
    # growth = tool result + agent output per turn (~3-5K)

    def agent_tokens(base_ctx: int, turns: int, growth: int = 4000):
        """Total input tokens for a multi-turn agent conversation."""
        total_in = int(turns * base_ctx + turns * (turns - 1) / 2 * growth)
        total_out = int(turns * 3000)  # ~3K output per turn
        return total_in, total_out

    # Base context per agent type (system + CLAUDE.md + skill + artifacts)
    PROMPT_BASE = 8_000    # system prompt + CLAUDE.md
    SKILL_AVG = 8_000      # average skill file tokens
    ARTIFACT_SMALL = 5_000   # scratchpad refs (summaries only)
    ARTIFACT_LARGE = 20_000  # scratchpad refs (full inventory, findings)

    def breadth_count(lines):
        if lines < 2000:  return 2
        if lines < 5000:  return 4
        return min(7, 3 + lines // 3000)

    bc = breadth_count(total_lines)
    est_findings = bc * 5  # ~5 findings per breadth agent
    vc = min(10, max(3, est_findings // 3))

    # ── Pipeline stages ─────────────────────────────────────
    # (name, count, model, base_context, turns)
    orch_base = PROMPT_BASE + 15_000  # CLAUDE.md + methodology prompt loaded

    if pipeline == "l1":
        stages = _l1_stages(mode, bc, vc, est_findings, src_tok, total_lines,
                            PROMPT_BASE, SKILL_AVG, ARTIFACT_SMALL, ARTIFACT_LARGE, orch_base)
    elif mode == "light":
        # Light mode: all sonnet/haiku, no opus, fewer agents, merged phases
        bc_light = min(3, max(2, bc))  # cap breadth at 3
        est_findings_light = bc_light * 4  # fewer findings from sonnet breadth
        vc_light = min(4, max(2, est_findings_light // 3))
        stages = [
            ("Recon",            2, "sonnet", PROMPT_BASE + int(src_tok * 0.5) + ARTIFACT_SMALL, 10),
            ("Breadth",          bc_light, "sonnet", PROMPT_BASE + SKILL_AVG + int(src_tok * 0.7) + ARTIFACT_LARGE, 10),
            ("Inventory",        1, "sonnet", PROMPT_BASE + ARTIFACT_LARGE * 2, 8),
            ("Depth (merged)",   2, "sonnet", PROMPT_BASE + SKILL_AVG * 2 + int(src_tok * 0.4) + ARTIFACT_LARGE, 10),
            ("Scanner+Sweep",    2, "sonnet", PROMPT_BASE + int(src_tok * 0.3) + ARTIFACT_LARGE, 8),
            ("Chain",            1, "sonnet", PROMPT_BASE + ARTIFACT_LARGE * 2, 8),
            ("Verification",     vc_light, "sonnet", PROMPT_BASE + SKILL_AVG + int(src_tok * 0.25) + ARTIFACT_SMALL, 12),
            ("Report",           1, "sonnet", PROMPT_BASE + ARTIFACT_LARGE * 2, 8),
            ("Report assembler", 1, "haiku",  PROMPT_BASE + ARTIFACT_LARGE * 2, 6),
            ("Orchestrator",     1, "sonnet", orch_base, 20),
        ]
    else:
        # Core mode (default stages — Thorough appends below)
        stages = [
            ("Recon (opus)",     2, "opus",   PROMPT_BASE + int(src_tok * 0.8) + ARTIFACT_SMALL, 12),
            ("Recon (sonnet)",   2, "sonnet", PROMPT_BASE + int(src_tok * 0.3) + ARTIFACT_SMALL, 10),
            ("Breadth",         bc, "opus",   PROMPT_BASE + SKILL_AVG + int(src_tok * 0.8) + ARTIFACT_LARGE, 12),
            ("Inventory",        1, "sonnet", PROMPT_BASE + ARTIFACT_LARGE * 2, 8),
            ("Sem. Invariants",  1, "sonnet", PROMPT_BASE + int(src_tok * 0.5) + ARTIFACT_SMALL, 10),
            ("Depth (opus)",     2, "opus",   PROMPT_BASE + SKILL_AVG + int(src_tok * 0.4) + ARTIFACT_LARGE, 12),
            ("Depth (sonnet)",   2, "sonnet", PROMPT_BASE + SKILL_AVG + int(src_tok * 0.4) + ARTIFACT_LARGE, 10),
            ("Scanners",         3, "sonnet", PROMPT_BASE + int(src_tok * 0.3) + ARTIFACT_LARGE, 8),
            ("Validation Sweep", 1, "sonnet", PROMPT_BASE + int(src_tok * 0.3) + ARTIFACT_LARGE, 8),
            ("Niche agents",     3, "sonnet", PROMPT_BASE + SKILL_AVG + int(src_tok * 0.3) + ARTIFACT_SMALL, 8),
            ("RAG + Scoring",    3, "haiku",  PROMPT_BASE + ARTIFACT_LARGE, 6),
            ("Chain Analysis",   2, "opus",   PROMPT_BASE + ARTIFACT_LARGE * 2, 8),
            ("Verification",    vc, "opus",   PROMPT_BASE + SKILL_AVG + int(src_tok * 0.25) + ARTIFACT_SMALL, 14),
            ("Report (opus)",    1, "opus",   PROMPT_BASE + ARTIFACT_LARGE * 3, 8),
            ("Report (sonnet)",  2, "sonnet", PROMPT_BASE + ARTIFACT_LARGE * 2, 8),
            ("Report (haiku)",   2, "haiku",  PROMPT_BASE + ARTIFACT_LARGE * 3, 6),
            ("Orchestrator",     1, "opus",   orch_base, 25),
        ]

    if pipeline != "l1" and mode == "thorough":
        # Estimate HIGH/CRIT findings for skeptic-judge: ~40% of findings are M+, ~30% are H/C
        est_high_crit = max(2, int(est_findings * 0.3))
        est_judge = max(1, est_high_crit // 3)  # ~1/3 of skeptics disagree
        # Per-contract clusters: ~1 per 500 lines, not 1 per file
        pc_count = min(8, max(2, total_lines // 500))

        # Apply skip probabilities for conditional stages:
        # - Re-scan: iter 2 often exits early (0 new findings) → ~60% of max agents
        # - Depth iter 2-3: ~50% chance of early exit (high confidence after iter 1)
        # - Inv/Medusa Fuzz: ~50% chance of being available/triggered
        # - Design Stress: ~40% chance budget redirect triggers
        # - Skeptic-Judge: runs only on HIGH/CRIT, ~70% agreement rate → few judges
        stages += [
            ("Re-scan",      3, "sonnet", PROMPT_BASE + int(src_tok * 0.6) + ARTIFACT_LARGE, 10),
            ("Per-contract", pc_count, "sonnet",
             PROMPT_BASE + int(src_tok * 0.25) + ARTIFACT_SMALL, 8),
            ("Sem. Pass 2",  1, "sonnet", PROMPT_BASE + int(src_tok * 0.4) + ARTIFACT_LARGE, 8),
            ("Depth iter2-3", 3, "sonnet", PROMPT_BASE + SKILL_AVG + int(src_tok * 0.2) + ARTIFACT_SMALL, 8),
            ("Inv. Fuzz",    1, "sonnet", PROMPT_BASE + int(src_tok * 0.3) + ARTIFACT_SMALL, 10),
            ("Design Stress", 1, "sonnet", PROMPT_BASE + ARTIFACT_LARGE, 8),
            ("Extra verify", 2, "sonnet", PROMPT_BASE + SKILL_AVG + int(src_tok * 0.2) + ARTIFACT_SMALL, 10),
            ("Skeptic",      est_high_crit, "sonnet",
             PROMPT_BASE + SKILL_AVG + int(src_tok * 0.25) + ARTIFACT_SMALL, 10),
            ("Judge",        est_judge, "haiku",
             PROMPT_BASE + ARTIFACT_SMALL * 2, 4),
            ("Orch. extra",  1, "opus",   orch_base, 15),
        ]

    # ── Compute totals per model ──────────────────────────────
    model_input = {"opus": 0, "sonnet": 0, "haiku": 0}
    model_output = {"opus": 0, "sonnet": 0, "haiku": 0}
    total_input = 0
    total_output = 0
    total_agents = 0

    for _name, count, model, base_ctx, turns in stages:
        ai, ao = agent_tokens(base_ctx, turns)
        model_input[model] += count * ai
        model_output[model] += count * ao
        total_input += count * ai
        total_output += count * ao
        total_agents += count

    # Sonnet 5's documented tokenizer emits about 30% more tokens for the
    # same input than Sonnet 4.6. Re-baseline only estimated Sonnet input;
    # output length is workload-driven rather than a fixed tokenizer delta.
    if backend != "codex":
        sonnet_input_delta = int(model_input["sonnet"] * 0.30)
        model_input["sonnet"] += sonnet_input_delta
        total_input += sonnet_input_delta

    input_mtok = total_input / 1_000_000
    output_mtok = total_output / 1_000_000

    # ── API cost estimate ────────────────────────────────────
    if backend == "codex":
        # OpenAI API-equivalent pricing as of 2026-05:
        # GPT-5.6 Sol $4/$20, Terra $2/$12, Luna $0.20/$1.20.
        # The launcher maps Plamen opus/sonnet/haiku tiers to those models by
        # default; env overrides may change real billing.
        pricing = {"opus": (5.0, 30.0), "sonnet": (2.5, 15.0), "haiku": (0.20, 1.25)}
    else:
        # Claude pricing per tier estimate (Opus 5 $5/$25, Sonnet 5 $2/$10,
        # Haiku 4.5 $1/$5), as of 2026-08-28.
        pricing = {"opus": (5.0, 25.0), "sonnet": (2.0, 10.0), "haiku": (1.0, 5.0)}
    api_cost = 0.0
    for m in ("opus", "sonnet", "haiku"):
        ip, op = pricing[m]
        api_cost += (model_input[m] / 1e6) * ip + (model_output[m] / 1e6) * op

    # ── Weekly plan usage estimate ───────────────────────────
    # Calibrated from empirical data:
    #   SC: A thorough audit on a ~5000-line project uses ~9% of Max x20.
    #   L1: Recent whole-client thorough runs usually land around 10-20%
    #       of Max x20, centered near ~15%, because V2 uses bounded shards
    #       rather than reading full-client LOC in every phase.
    #   Max x20 weekly allowance: 240-480h Sonnet + 24-40h Opus (resets weekly).
    #   Max x5 has 4x less capacity than x20.
    ref_tokens = 0

    if pipeline == "l1":
        ref_src = 30_000 * 4
        ref_pct = 10.5
        ref_per_agent = min(ref_src, int(ref_src * 0.3))
        ref_stages = [
            # L1 Core stages
            (1, ref_src * 0.2 + 8000, 8),                                       # Bake
            (2, ref_src * 0.5 + 13000, 12), (2, ref_src * 0.2 + 13000, 10),    # Recon
            (5, ref_per_agent + 36000, 12),                                      # Breadth
            (4, 48000, 8),                                                        # Inventory (4 chunks + merge)
            (1, ref_src * 0.3 + 13000, 10),                                      # Sem. Invariants
            (3, ref_src * 0.2 + 36000, 12), (2, ref_src * 0.2 + 36000, 10),    # Depth
            (3, 28000, 6), (1, 48000, 8),                                        # RAG + Dedup
            (5, ref_src * 0.15 + 21000, 12),                                     # Verify (high)
            (4, ref_src * 0.15 + 21000, 12),                                     # Verify (med)
            (3, 48000, 8), (2, 48000, 6),                                        # Report
            (1, 23000, 25),                                                       # Orchestrator
            # L1 Thorough-only
            (1, ref_src * 0.3 + 28000, 10),                                      # Graph Sweeps
            (1, 28000, 8),                                                        # Location Recovery
            (1, ref_src * 0.2 + 28000, 10),                                      # Attention Repair
            (3, ref_src * 0.1 + 21000, 10),                                      # Verify (low)
            (4, ref_src * 0.15 + 21000, 10), (1, 18000, 4),                     # Skeptic + Judge
            (1, 28000, 8),                                                        # Cross-batch
            (1, 23000, 15),                                                       # Orch. extra
        ]
    else:
        ref_src = 5000 * 4
        ref_pct = 9.0
        ref_stages = [
            # SC Core stages
            (2, ref_src * 0.8 + 8000, 12), (2, ref_src * 0.3 + 8000, 10),    # Recon
            (4, ref_src * 0.8 + 36000, 12), (1, 48000, 8),                     # Breadth + Inventory
            (1, ref_src * 0.5 + 13000, 10),                                     # Sem. Invariants
            (2, ref_src * 0.4 + 36000, 12), (2, ref_src * 0.4 + 36000, 10),   # Depth
            (3, ref_src * 0.3 + 28000, 8), (1, ref_src * 0.3 + 28000, 8),     # Scanners + VS
            (3, ref_src * 0.3 + 21000, 8), (3, 28000, 6), (2, 48000, 8),      # Niche(3) + RAG + Chain
            (5, ref_src * 0.25 + 21000, 14),                                    # Verification
            (1, 68000, 8), (2, 48000, 8), (2, 68000, 6),                       # Report
            (1, 23000, 35),                                                      # Orchestrator (capped)
            # SC Thorough-only stages
            (3, ref_src * 0.6 + 28000, 10), (4, ref_src * 0.25 + 13000, 8),   # Re-scan + Per-contract
            (1, ref_src * 0.4 + 28000, 8), (3, ref_src * 0.2 + 21000, 8),     # Sem. Pass 2 + Depth 2-3
            (1, ref_src * 0.3 + 13000, 10),                                     # Inv. Fuzz
            (1, 28000, 8),                                                       # Design Stress
            (2, ref_src * 0.2 + 21000, 10),                                     # Extra verify
            (4, ref_src * 0.25 + 21000, 10), (1, 18000, 4),                    # Skeptic + Judge
            (1, 23000, 15),                                                      # Orch. extra
        ]

    for c, b, t in ref_stages:
        ai, _ = agent_tokens(b, t)
        ref_tokens += c * ai

    # Plan usage percentages (Claude-specific — not applicable for Codex)
    if backend == "codex":
        pct_x20 = 0.0
        pct_x5 = 0.0
        pct_pro = 0.0
    else:
        pct_x20 = (total_input / ref_tokens) * ref_pct if ref_tokens else 0
        pct_x5 = pct_x20 * 4
        pct_pro = pct_x5 * 2.5 if mode == "light" else pct_x5 * 5

    return {
        "files": total_files,
        "lines": total_lines,
        "agents": total_agents,
        "input_mtok": round(input_mtok, 1),
        "output_mtok": round(output_mtok, 1),
        "api_cost": round(api_cost, 0),
        "effective_lines": effective_lines,
        "pct_x5": round(pct_x5, 1),
        "pct_x20": round(pct_x20, 1),
        "pct_pro": round(pct_pro, 1),
        "scoped": (has_scope or bool(module_roots)) and total_files > 0,
        "backend": backend,
    }


def _shorten(path: str, maxlen: int = 50) -> str:
    return path if len(path) <= maxlen else "..." + path[-(maxlen - 3):]


def _back_separator():
    return [Separator(), {"name": "← Go back", "value": _BACK}]


def _wrap_msg(full: str, short: str = "") -> str:
    """If full exceeds _MAX_LINE, print it above and return short for InquirerPy."""
    if len(full) <= _MAX_LINE:
        return full
    sys.stdout.write(f"\n  {_C_GRAY}{full}{_RST}\n")
    sys.stdout.flush()
    return short


def _cap(s: str, n: int = 44) -> str:
    """Truncate choice name to n chars (accounts for 4-char pointer prefix)."""
    return s if len(s) <= n else s[:n - 3] + "..."


# ── Prompts ──────────────────────────────────────────────────

def select_pipeline() -> str:
    """Returns 'sc', 'l1', 'compare', or 'setup'."""
    _drain_stdin()
    choices = [
        {"name": "Smart Contract         EVM · Solana · Soroban · Aptos · Sui",
         "value": "sc"},
        {"name": "L1 / DLT               Go or Rust node client",
         "value": "l1"},
        Separator(),
    ]
    if _find_claude_bin():
        choices.append({"name": "Compare                Diff reports", "value": "compare"})
    choices.append({"name": "Setup                  Install tools + build RAG DB", "value": "setup"})
    result = inquirer.select(
        message="What are you auditing?",
        choices=choices,
        default="sc",
        pointer="  >",
        style=_STYLE,
        qmark="⬡",
        amark="✓",
    ).execute()
    return result


def select_audit_mode(pipeline: str) -> str:
    """Returns 'light', 'core', or 'thorough' for the given pipeline."""
    if pipeline == "sc":
        choices = [
            {"name": "Light         18-22 agents  | Pro plan  | best under 3k LOC",
             "value": "light"},
            {"name": "Core          30-50 agents  | Max plan  | ALL severities",
             "value": "core"},
            {"name": "Thorough      40-100 agents | Max plan  | ALL + fuzz",
             "value": "thorough"},
            *_back_separator(),
        ]
    else:
        choices = [
            {"name": "Light         15-20 agents  | Quick scan",
             "value": "light"},
            {"name": "Core          25-40 agents  | Standard L1 depth",
             "value": "core"},
            {"name": "Thorough      35-55 agents  | Iterative + re-scan",
             "value": "thorough"},
            *_back_separator(),
        ]
    _drain_stdin()
    return inquirer.select(
        message="Select audit depth:",
        choices=choices,
        default="core",
        pointer="  >",
        style=_STYLE,
        qmark=">",
        amark="✓",
    ).execute()


def select_claude_transport(pipeline: str, mode: str) -> tuple[object, str]:
    """Choose a new Claude transport; return (bound resolution, warning)."""
    capability = _claude_headless_transport_capability()
    _drain_stdin()
    if capability.get("available") is True:
        choices = [
            {
                "name": "Contained headless   recommended; governed worker isolation",
                "value": "headless",
            },
            *_back_separator(),
        ]
        default = "headless"
    else:
        reason = str(capability.get("reason") or "authority unavailable")
        sys.stdout.write(
            f"  {_C_ORANGE}! Contained headless is unavailable on this host: "
            f"{reason}{_RST}\n"
        )
        choices = [
            *_back_separator(),
        ]
        default = _BACK
    result = inquirer.select(
        message="Claude execution transport?",
        choices=choices,
        default=default,
        pointer="  >",
        style=_STYLE,
        qmark=">",
        amark="✓",
    ).execute()
    if result == _BACK:
        return _BACK, ""
    resolution = _bind_new_claude_transport(
        pipeline, mode, "claude", result, capability=capability,
        audit_model_launch=False,
    )
    _backend, _transport, warning = _replay_new_transport_resolution(
        resolution, pipeline=pipeline, mode=mode,
    )
    if warning:
        sys.stdout.write(f"  {_C_ORANGE}! {warning}{_RST}\n")
    return resolution, warning


def select_target() -> tuple:
    """Returns (target_path, network_or_empty). Network is always empty in interactive mode."""
    cwd = os.getcwd()
    parent = os.path.dirname(cwd)

    cwd_hint = _detect_project_hint(cwd)
    parent_hint = _detect_project_hint(parent)

    subdirs = []
    for sub in ["src", "contracts", "programs"]:
        full = os.path.join(cwd, sub)
        if os.path.isdir(full):
            n = _count_source_files(full)
            subdirs.append((sub, full, f"{n} source files" if n else "no source files"))

    choices = []

    if cwd_hint:
        cwd_label = _cap(f"Current dir   {cwd_hint}")
    else:
        cwd_label = _cap(f"Current dir   {_shorten(cwd, 28)}")
    choices.append({"name": cwd_label, "value": cwd})

    for sub, full, hint in subdirs:
        choices.append({"name": _cap(f"./{sub}/        {hint}"), "value": full})

    if parent_hint:
        parent_label = _cap(f"Parent dir    {parent_hint}")
    else:
        parent_label = _cap(f"Parent dir    {_shorten(parent, 28)}")
    choices.append({"name": parent_label, "value": parent})

    choices.append(Separator())
    choices.append({"name": "Browse...    enter a different path", "value": "__browse__"})
    choices.extend(_back_separator())

    _drain_stdin()
    result = inquirer.select(
        message="Target project to audit:",
        choices=choices,
        default=cwd,
        pointer="  >",
        style=_STYLE,
        qmark=">",
        amark="✓",
    ).execute()

    if result == _BACK:
        return (_BACK, "")

    if result == "__browse__":
        path = inquirer.filepath(
            message="Path to project:",
            validate=lambda v: os.path.exists(v) or "Path not found",
            only_directories=True,
            style=_STYLE, qmark=">", amark="✓",
        ).execute()
        return (os.path.abspath(path), "")

    return (result, "")


def select_docs() -> str:
    _drain_stdin()
    result = inquirer.select(
        message=_wrap_msg(
            "Docs describing trust roles or permissions?",
            "Docs:"),
        choices=[
            {"name": "No docs      inferred from code",        "value": "none"},
            {"name": "Local files  whitepaper, spec, or docs", "value": "local"},
            {"name": "URL          link to docs",              "value": "url"},
            *_back_separator(),
        ],
        default="none",
        pointer="  >",
        style=_STYLE,
        qmark=">",
        amark="✓",
    ).execute()

    if result == _BACK:
        return _BACK
    if result == "none":
        return ""

    if result == "local":
        path = inquirer.filepath(
            message="Path to docs:",
            validate=lambda v: os.path.exists(v) or "Path not found",
            only_directories=False,
            style=_STYLE, qmark=">", amark="✓",
        ).execute()
        return os.path.abspath(path)

    if result == "url":
        _drain_stdin()
        return inquirer.text(
            message="Docs URL:",
            validate=lambda v: v.startswith("http") or "Enter a valid URL",
            style=_STYLE, qmark=">", amark="✓",
        ).execute()

    return ""


def select_scope() -> tuple:
    """Returns (scope_file_path, scope_notes). Both can be empty."""
    _drain_stdin()
    result = inquirer.select(
        message="Scope constraints?",
        choices=[
            {"name": "Full project  audit everything in target", "value": "none"},
            {"name": "Scope file    scope.txt with file list",   "value": "file"},
            {"name": "Notes         describe focus areas",       "value": "notes"},
            *_back_separator(),
        ],
        default="none",
        pointer="  >",
        style=_STYLE,
        qmark=">",
        amark="✓",
    ).execute()

    if result == _BACK:
        return (_BACK, "")
    if result == "none":
        return ("", "")

    if result == "file":
        # Try to find scope files in cwd
        cwd = os.getcwd()
        scope_files = []
        for pattern in ["scope.txt", "scope.md", "SCOPE", "scope"]:
            full = os.path.join(cwd, pattern)
            if os.path.isfile(full):
                scope_files.append(full)

        if scope_files:
            choices = [{"name": os.path.basename(f), "value": f} for f in scope_files]
            choices.append(Separator())
            choices.append({"name": "Browse...  pick a different file", "value": "__browse__"})
            _drain_stdin()
            chosen = inquirer.select(
                message="Select scope file:",
                choices=choices,
                pointer="  >",
                style=_STYLE, qmark=">", amark="✓",
            ).execute()
            if chosen == "__browse__":
                chosen = inquirer.filepath(
                    message="Path to scope file:",
                    validate=lambda v: os.path.exists(v) or "File not found",
                    only_directories=False,
                    style=_STYLE, qmark=">", amark="✓",
                ).execute()
            return (os.path.abspath(chosen), "")
        else:
            path = inquirer.filepath(
                message="Path to scope file:",
                validate=lambda v: os.path.exists(v) or "File not found",
                only_directories=False,
                style=_STYLE, qmark=">", amark="✓",
            ).execute()
            return (os.path.abspath(path), "")

    if result == "notes":
        _drain_stdin()
        notes = inquirer.text(
            message="Scope notes (e.g., 'focus on vault module, ignore governance'):",
            style=_STYLE, qmark=">", amark="✓",
        ).execute()
        return ("", notes.strip())

    return ("", "")


def select_report(message: str, allow_back: bool = True) -> str:
    """Select a markdown report file. Only .md files — PDFs cannot be diffed."""
    cwd = os.getcwd()
    report_files = []
    for f in glob.glob(os.path.join(cwd, "*.md")):
        name = os.path.basename(f)
        if any(kw in name.lower() for kw in ["audit", "report", "finding", "security"]):
            report_files.append(f)

    choices = []
    for f in report_files[:5]:
        choices.append({"name": f"  {os.path.basename(f)}", "value": f})
    if choices:
        choices.append(Separator())
    choices.append({"name": "Browse...          pick a file", "value": "__browse__"})
    if allow_back:
        choices.extend(_back_separator())

    _drain_stdin()
    result = inquirer.select(
        message=message,
        choices=choices,
        pointer="  >",
        style=_STYLE,
        qmark=">",
        amark="✓",
    ).execute()

    if result == _BACK:
        return _BACK

    if result == "__browse__":
        path = inquirer.filepath(
            message="Path to report:",
            validate=lambda v: os.path.exists(v) or "File not found",
            only_directories=False,
            style=_STYLE, qmark=">", amark="✓",
        ).execute()
        return os.path.abspath(path)

    return result


def confirm_launch() -> str:
    """Returns 'launch', 'back', or 'cancel'."""
    _drain_stdin()
    return inquirer.select(
        message="Ready to launch?",
        choices=[
            {"name": "Launch audit",                  "value": "launch"},
            {"name": "← Go back    change selections", "value": "back"},
            {"name": "Cancel       exit",              "value": "cancel"},
        ],
        default="cancel",
        pointer="  >",
        style=_STYLE,
        qmark=">",
        amark="✓",
    ).execute()


def select_l1_tier(detected_tier: str, loc: int) -> str:
    """Select L1 audit tier. Returns 't0'/'t1'/'t2'/'t3' or _BACK."""
    choices = []
    for tid, (label, desc) in _L1_TIER_LABELS.items():
        marker = " ←" if tid == detected_tier else ""
        choices.append({"name": f"{label:22s} {desc}{marker}", "value": tid})
    choices.extend(_back_separator())
    _drain_stdin()
    result = inquirer.select(
        message=f"Select audit tier (detected: {detected_tier.upper()} based on {loc:,} LOC):",
        choices=choices,
        default=detected_tier,
        pointer="  >",
        style=_STYLE,
        qmark=">",
        amark="✓",
    ).execute()
    return result


def select_l1_modules(modules: list) -> list:
    """Select modules for T1 subsystem audit. Returns list of (name, path, loc) or [_BACK]."""
    if not modules:
        return []
    choices = [
        {"name": f"{name:20s} {loc:>7,} LOC   {path}", "value": (name, path, loc)}
        for name, path, loc in modules
    ]
    _drain_stdin()
    result = inquirer.checkbox(
        message="Select modules to audit (space=toggle, enter=confirm, empty=back):",
        choices=choices,
        style=_STYLE,
        qmark=">",
        amark="✓",
        pointer="  >",
    ).execute()
    if not result:
        return [_BACK]
    return result


def select_l1_fork() -> str:
    """Select fork analysis mode. Returns 'diff'/'standalone'/'both' or _BACK."""
    _drain_stdin()
    result = inquirer.select(
        message="Fork detected. Upstream comparison?",
        choices=[
            {"name": "Diff against upstream     focus on fork-specific changes", "value": "diff"},
            {"name": "Audit as standalone       treat as independent codebase",  "value": "standalone"},
            {"name": "Both                      upstream diff + standalone",      "value": "both"},
            *_back_separator(),
        ],
        default="standalone",
        pointer="  >",
        style=_STYLE,
        qmark=">",
        amark="✓",
    ).execute()
    return result


# ── Summary ──────────────────────────────────────────────────

def show_summary(mode: str, target: str, docs: str,
                 network: str = "", scope_file: str = "", scope_notes: str = "",
                 cost_estimate: dict = None, strict: bool = False,
                 pipeline: str = "sc", language: str = "",
                 tier: str = "", modules: list = None, fork_mode: str = "",
                 backend: str = "claude", claude_exec_mode: str = "",
                 transport_warning: str = ""):
    w = sys.stdout.write
    bx = _C_BOX
    W = 52

    def row(label, value, value_color=_C_WHITE):
        lpad = 12 - len(label)
        vis_val = value[:W - 14] if len(value) > W - 14 else value
        vis = 2 + len(label) + lpad + len(vis_val)
        w(f"  {bx}│{_RST}  {_C_GRAY}{label}{_RST}{' ' * lpad}"
          f"{value_color}{vis_val}{_RST}{' ' * max(0, W - vis)}{bx}│{_RST}\n")

    console.print()
    console.print(Rule(style="color(238)"))
    w("\n")
    w(f"  {bx}╭{'─' * W}╮{_RST}\n")

    # Header
    vis = 17  # "  Launch Summary" length
    w(f"  {bx}│{_RST}  {_BOLD}{_C_WHITE}Launch Summary{_RST}"
      f"{' ' * (W - vis)}{bx}│{_RST}\n")

    # Blank line
    w(f"  {bx}│{_RST}{' ' * W}{bx}│{_RST}\n")

    mode_table = L1_MODES if pipeline == "l1" else MODES
    mode_label = mode_table.get(mode, {}).get("label", mode)
    row("Pipeline", "L1 Infrastructure" if pipeline == "l1" else "Smart Contract", _C_ORANGE)
    row("Mode", mode_label, _C_ORANGE)
    if backend == "codex":
        row("Backend", "Codex CLI (OpenAI)", _C_ORANGE)
    else:
        row("Backend", "Claude Code (Anthropic)", _C_ORANGE)
        if claude_exec_mode:
            row("Transport", "Contained headless", _C_ORANGE)
    row("AI Model", _wizard_model_summary(backend, mode), _C_ORANGE)
    row("Target", target)
    if language:
        row("Language", language.upper())
    if tier:
        tl = _L1_TIER_LABELS.get(tier, (tier, ""))[0]
        row("Tier", tl)
    if modules:
        names = ", ".join(m[0] for m in modules[:5])
        if len(modules) > 5:
            names += f" +{len(modules) - 5} more"
        row("Modules", names)
    if fork_mode and fork_mode != "standalone":
        row("Fork", fork_mode)
    if network:
        row("Network", NETWORKS.get(network, network))
    row("Docs", docs if docs else "none", _C_WHITE if docs else _C_DARK_GRAY)
    if scope_file:
        row("Scope", os.path.basename(scope_file))
    if scope_notes:
        row("Notes", scope_notes)
    if strict:
        row("Proven-only", "ON — unproven findings capped at Low", _C_ORANGE)

    if cost_estimate:
        lines = cost_estimate["lines"]
        agents = cost_estimate["agents"]
        scoped = cost_estimate.get("scoped", False)
        scope_tag = " (scoped)" if scoped else ""
        row("Codebase", f"~{lines:,} lines, {cost_estimate['files']} files{scope_tag}")
        row("Agents", f"~{agents}")
        row("Tokens", f"~{cost_estimate['input_mtok']}M in / ~{cost_estimate['output_mtok']}M out")
        api = cost_estimate.get("api_cost", 0)
        est_backend = cost_estimate.get("backend", backend)
        if est_backend == "codex":
            row("API equiv", f"~${api:.0f} USD (OpenAI)", _C_WHITE)
            row("Weekly", "N/A - Codex/OpenAI quotas differ", _C_DARK_GRAY)
        else:
            row("API cost", f"~${api:.0f} USD", _C_WHITE)
            pct_pro = cost_estimate.get("pct_pro", 0)
            pct5 = cost_estimate["pct_x5"]
            pct20 = cost_estimate["pct_x20"]
            if pct_pro > 0:
                color_pro = _C_RED if pct_pro > 80 else (_C_ORANGE if pct_pro > 40 else _C_GREEN)
                row("Pro", f"~{pct_pro:.0f}% of weekly allowance", color_pro)
            if pct5 > 0:
                color5 = _C_RED if pct5 > 80 else (_C_ORANGE if pct5 > 40 else _C_GREEN)
                color20 = _C_RED if pct20 > 80 else (_C_ORANGE if pct20 > 40 else _C_GREEN)
                row("Max x5", f"~{pct5:.0f}% of weekly allowance", color5)
                row("Max x20", f"~{pct20:.0f}% of weekly allowance", color20)

    w(f"  {bx}╰{'─' * W}╯{_RST}\n")

    if cost_estimate:
        w(f"  {_C_DARK_GRAY}Rough estimates only. Actual usage varies with protocol{_RST}\n")
        if cost_estimate.get("backend", backend) == "codex":
            w(f"  {_C_DARK_GRAY}Codex shows API-equivalent spend; weekly plan percent is not{_RST}\n")
            w(f"  {_C_DARK_GRAY}comparable to Claude Max/Pro. Run /cost after for actuals.{_RST}\n")
        else:
            w(f"  {_C_DARK_GRAY}complexity and findings count. Run /cost after for actuals.{_RST}\n")

    if transport_warning:
        w(f"  {_C_ORANGE}! {transport_warning}{_RST}\n")

    w("\n")
    sys.stdout.flush()


# ── Resume Detection ─────────────────────────────────────────

def _resolve_resume_progress(config: dict, completed: list[str]) -> dict:
    """Return last completed phase and the next active phase to run."""
    last_phase = completed[-1] if completed else "(not started)"
    pipeline = str(config.get("pipeline", "sc")).lower()
    mode = str(config.get("mode", "core")).lower()
    next_phase = "(complete)"

    try:
        scripts_dir = os.path.join(PLAMEN_HOME, "scripts")
        if scripts_dir not in sys.path:
            sys.path.insert(0, scripts_dir)
        from plamen_types import L1_PHASES, SC_PHASES  # type: ignore

        phases = L1_PHASES if pipeline == "l1" else SC_PHASES
        completed_set = set(completed or [])
        for phase in phases:
            if mode not in getattr(phase, "modes", ()):
                continue
            if phase.name not in completed_set:
                next_phase = phase.name
                break
    except Exception:
        fallback = {
            "sc": [
                "recon", "instantiate", "breadth", "rescan",
                "inventory_prepare", "inventory_chunk_a", "inventory_chunk_b",
                "inventory_chunk_c", "inventory", "invariants", "depth",
                "attention_repair", "rag_sweep", "sc_semantic_dedup",
                "chain", "chain_agent2", "sc_verify_queue",
                "sc_verify_crithigh", "sc_verify_high_b", "sc_verify_high_c",
                "sc_verify_high_d", "sc_verify_medium_a",
                "sc_verify_medium_b", "sc_verify_medium_c",
                "sc_verify_medium_d", "sc_verify_low_a", "sc_verify_low_b",
                "sc_verify_aggregate", "skeptic", "crossbatch",
                "report_index", "report_body_writer_critical_high",
                "report_body_writer_medium", "report_body_writer_low_info",
                "report_critical_high", "report_critical_high_merge",
                "report_medium", "report_medium_merge", "report_low_info",
                "report_low_info_merge", "report_assemble",
            ],
            "l1": [
                "bake", "recon", "breadth", "graph_sweeps",
                "inventory_prepare", "inventory_chunk_a", "inventory_chunk_b",
                "inventory_chunk_c", "inventory", "location_recovery",
                "invariants", "depth", "attention_repair", "rag_sweep",
                "chain", "chain_agent2", "semantic_dedup", "verify_queue",
                "verify_aggregate", "crossbatch", "skeptic", "report_index",
                "report_body_writer_critical_high",
                "report_body_writer_medium", "report_body_writer_low_info",
                "report_critical_high", "report_critical_high_merge",
                "report_medium", "report_medium_merge", "report_low_info",
                "report_low_info_merge", "report_assemble",
            ],
        }.get(pipeline, [])
        completed_set = set(completed or [])
        for name in fallback:
            if name not in completed_set:
                next_phase = name
                break

    return {
        "last_phase": last_phase,
        "next_phase": next_phase,
        "phases_done": len(completed or []),
    }


def _find_existing_audit(cwd: str = "") -> "dict | None":
    """Look for an existing audit scratchpad relative to cwd.

    Primary: .scratchpad/config.json (normal path).
    Fallback: .scratchpad exists with checkpoint or artifacts but config.json
    is missing (e.g. crash/interrupt deleted it). Tries to reconstruct config
    from the checkpoint's embedded copy (v2.6.2+) or from prompt snapshots.

    Returns dict with keys: config_path, scratchpad, mode, pipeline,
    language, target, last_phase, phases_done.
    Extra key 'config_missing' = True when config.json was reconstructed
    or is unrecoverable.
    Returns None if no existing audit found.
    """
    import json as _json

    if not cwd:
        cwd = os.getcwd()

    scratchpad_dirs = [
        os.path.join(cwd, ".scratchpad"),
        os.path.join(cwd, "src", ".scratchpad"),
        os.path.join(cwd, "contracts", ".scratchpad"),
    ]

    # First configless-but-artifacts stub seen. Only used as a LAST resort if NO
    # candidate yields a valid/recoverable config. This stops a configless stub
    # in a PARENT dir (e.g. cwd/.scratchpad, created when the wizard is launched
    # from a parent and the audit is scoped to a subdir) from masking the real
    # audit in cwd/contracts/.scratchpad or cwd/src/.scratchpad.
    best_missing = None

    for scratchpad in scratchpad_dirs:
        config_path = os.path.join(scratchpad, "config.json")
        checkpoint_path = os.path.join(scratchpad, "_v2_checkpoint.json")

        # ── Primary: config.json exists AND parses ──
        # A halt landing mid-write (or a partial reconstruct) can leave
        # config.json present but TRUNCATED/corrupt. That must NOT skip the
        # candidate: the full config is also embedded in _v2_checkpoint.json,
        # so a corrupt config.json is recoverable exactly like a missing one.
        # Treat a parse failure as "no usable config" and fall through to the
        # checkpoint-reconstruction fallback below (which self-heals
        # config.json), instead of `continue`-ing past the whole scratchpad.
        config = None
        if os.path.isfile(config_path):
            try:
                with open(config_path, encoding="utf-8") as f:
                    config = _json.load(f)
            except Exception:
                config = None

        if config is not None:
            completed = []
            checkpoint = {}
            if os.path.isfile(checkpoint_path):
                try:
                    with open(checkpoint_path, encoding="utf-8") as f:
                        checkpoint = _json.load(f)
                    completed = checkpoint.get("completed", [])
                except Exception:
                    pass
            progress = _resolve_resume_progress(config, completed)

            return {
                "config_path": config_path,
                "scratchpad": scratchpad,
                "mode": config.get("mode", "?"),
                "pipeline": config.get("pipeline", "?"),
                "language": config.get("language", "?"),
                "target": config.get("project_root", "?"),
                "last_phase": progress["last_phase"],
                "next_phase": progress["next_phase"],
                "phases_done": progress["phases_done"],
                "backend": config.get("cli_backend", "claude"),
                "models": _wizard_model_summary(config.get("cli_backend", "claude"), config.get("mode", "")),
                "degraded": list(checkpoint.get("degraded", [])),
                "runtime_debts": list((checkpoint.get("runtime_debts") or {}).keys())
                if isinstance(checkpoint.get("runtime_debts"), dict)
                else list(checkpoint.get("runtime_debts", [])),
                "report_exists": os.path.isfile(os.path.join(config.get("project_root", ""), "AUDIT_REPORT.md")),
                "modified": time.strftime(
                    "%Y-%m-%d %H:%M:%S",
                    time.localtime(os.path.getmtime(checkpoint_path if os.path.isfile(checkpoint_path) else config_path)),
                ),
            }

        # ── Fallback: scratchpad dir exists but config.json is missing OR
        #    corrupt (parse failed above) ──
        if not os.path.isdir(scratchpad):
            continue

        # Need checkpoint or at least some real artifacts
        has_checkpoint = os.path.isfile(checkpoint_path)
        try:
            artifact_files = [
                f for f in os.listdir(scratchpad)
                if not f.startswith("_") and f.endswith(".md")
                and os.path.isfile(os.path.join(scratchpad, f))
            ]
        except Exception:
            artifact_files = []

        if not has_checkpoint and not artifact_files:
            continue

        completed = []
        recovered_config = None

        if has_checkpoint:
            try:
                with open(checkpoint_path, encoding="utf-8") as f:
                    cp = _json.load(f)
                completed = cp.get("completed", [])
                recovered_config = cp.get("config")
                if recovered_config and not isinstance(recovered_config, dict):
                    recovered_config = None
            except Exception:
                pass

        # Try to reconstruct config from checkpoint's embedded copy.
        # Atomic temp+replace: a halt during this write must never leave
        # config.json truncated (that would re-create the corruption this
        # recovery exists to undo). os.replace is atomic same-volume.
        if recovered_config:
            try:
                _tmp = config_path + ".tmp"
                with open(_tmp, "w", encoding="utf-8") as f:
                    _json.dump(recovered_config, f, indent=2)
                os.replace(_tmp, config_path)
            except Exception:
                try:
                    if os.path.isfile(config_path + ".tmp"):
                        os.unlink(config_path + ".tmp")
                except Exception:
                    pass
            progress = _resolve_resume_progress(recovered_config, completed)
            return {
                "config_path": config_path,
                "scratchpad": scratchpad,
                "mode": recovered_config.get("mode", "?"),
                "pipeline": recovered_config.get("pipeline", "?"),
                "language": recovered_config.get("language", "?"),
                "target": recovered_config.get("project_root", "?"),
                "last_phase": progress["last_phase"],
                "next_phase": progress["next_phase"],
                "phases_done": progress["phases_done"],
                "recovered": True,
            }

        # Artifacts but no recoverable config. Do NOT return immediately — a
        # LATER candidate (e.g. cwd/contracts/.scratchpad) may hold the real
        # config + checkpoint. Remember the FIRST such stub only as a last-resort
        # fallback and keep scanning the remaining candidates.
        if best_missing is None:
            best_missing = {
                "config_path": None,
                "scratchpad": scratchpad,
                "mode": "?",
                "pipeline": "?",
                "language": "?",
                "target": os.path.dirname(scratchpad),
                "last_phase": completed[-1] if completed else "(unknown)",
                "next_phase": "(unknown)",
                "phases_done": len(completed),
                "config_missing": True,
            }
        continue

    # No candidate had a valid/recoverable config; fall back to the first
    # configless stub (if any) so the user still gets a Clean-up/Cancel choice.
    return best_missing


def _resume_audit_prompt(info: dict) -> str:
    """Show existing audit info and ask user what to do.

    Returns: 'resume', 'fresh', or 'new'.
    """
    config_missing = info.get("config_missing", False)
    recovered = info.get("recovered", False)

    w = sys.stdout.write
    w(f"\n  {_C_ORANGE}⬡ Existing audit detected{_RST}\n\n")
    w(f"    {_C_GRAY}Target:    {_RST}{info['target']}\n")
    w(f"    {_C_GRAY}Pipeline:  {_RST}{info['pipeline'].upper()} {info['mode']}\n")
    w(f"    {_C_GRAY}Language:  {_RST}{info['language']}\n")
    if info.get("backend"):
        w(f"    {_C_GRAY}Backend:   {_RST}{info['backend']} ({info.get('models', '?')})\n")
    if info.get("modified"):
        w(f"    {_C_GRAY}Updated:   {_RST}{info['modified']}\n")
    next_phase = info.get("next_phase", "(unknown)")
    w(f"    {_C_GRAY}Progress:  {_RST}{info['phases_done']} phases done, last = {info['last_phase']}, next = {next_phase}\n")
    w(f"    {_C_GRAY}Report:    {_RST}{'present' if info.get('report_exists') else 'not released'}\n")
    if info.get("degraded"):
        w(f"    {_C_GRAY}Degraded:  {_RST}{', '.join(info['degraded'][:6])}\n")
    if info.get("runtime_debts"):
        w(f"    {_C_GRAY}Debt:      {_RST}{', '.join(info['runtime_debts'][:6])}\n")

    if config_missing:
        w(f"    {_C_GRAY}Config:    {_RST}{_C_RED}missing (not recoverable){_RST}\n")
        w(f"\n    {_C_ORANGE}Config was lost and could not be reconstructed from checkpoint.{_RST}\n")
        w(f"    {_C_ORANGE}Scratchpad artifacts exist at: {info['scratchpad']}{_RST}\n\n")
    elif recovered:
        w(f"    {_C_GRAY}Config:    {_RST}{info['config_path']} {_C_GREEN}(recovered from checkpoint){_RST}\n\n")
    else:
        w(f"    {_C_GRAY}Config:    {_RST}{info['config_path']}\n\n")
    sys.stdout.flush()

    if config_missing:
        choices = [
            {"name": "Start new (choose a distinct clean destination; preserve this run)",
             "value": "new"},
            Separator(),
            {"name": "Cancel   (leave scratchpad intact, exit)",
             "value": "cancel"},
        ]
        default = "new"
    else:
        choices = [
            {"name": f"Resume  (next: {next_phase})",
             "value": "resume"},
            {"name": "New     (choose a distinct clean destination; preserve existing)",
             "value": "new"},
            Separator(),
            {"name": "Cancel  (leave existing run intact)",
             "value": "cancel"},
        ]
        default = "resume"

    _drain_stdin()
    result = inquirer.select(
        message="What would you like to do?",
        choices=choices,
        default=default,
        pointer="  >",
        style=_STYLE,
        qmark="⬡",
        amark="✓",
    ).execute()
    return result


_STARTUP_DECISION_RECEIPT_FIELDS = frozenset({
    "schema", "run_id", "startup_intent", "snapshot_verdict",
    "changed_components", "component_digests", "stored_snapshot_digest",
    "current_snapshot_digest", "required_action", "allowed_actions",
    "evidence_preserved", "model_launch_allowed", "exit_status",
    "decision_id",
    "receipt_mac",
})
_MIDPHASE_DRIFT_DECISION_RECEIPT_FIELDS = frozenset({
    "schema", "decision_kind", "run_id", "launch_intent", "exit_status",
    "phase", "detection_stage", "snapshot_verdict", "changed_components",
    "runtime_entry_changes", "stored_snapshot_digest",
    "current_snapshot_digest", "phase_execution_state",
    "audit_model_generation_state", "prior_phase_or_run_model_state",
    "drift_evidence_relative_path", "existing_evidence_deletion_performed",
    "driver_continued_after_detection", "required_action", "allowed_actions",
    "receipt_authentication_scope", "same_user_process_compromise_out_of_scope",
    "decision_id", "receipt_mac",
})
_STARTUP_DECISION_DARWIN_LS_TIMEOUT_SECONDS = 5.0
_STARTUP_DECISION_DARWIN_LS_OUTPUT_BYTES = 64 * 1024


def _startup_decision_darwin_ls(path):
    """Return bounded ``/bin/ls -lde`` output without invoking a shell."""
    environment = {"LC_ALL": "C", "PATH": "/usr/bin:/bin"}
    try:
        process = subprocess.Popen(
            ["/bin/ls", "-lde", os.fspath(Path(path).absolute())],
            stdin=subprocess.DEVNULL, stdout=subprocess.PIPE,
            stderr=subprocess.PIPE, env=environment, shell=False,
        )
    except (OSError, ValueError) as exc:
        raise RuntimeError("Darwin startup-decision ACL inspection failed") from exc
    if process.stdout is None or process.stderr is None:
        try:
            process.kill()
        finally:
            process.wait(timeout=1.0)
        raise RuntimeError("Darwin startup-decision ACL channels are unavailable")
    output = {"stdout": bytearray(), "stderr": bytearray()}
    overflow = threading.Event()
    errors = []

    def drain(label, stream):
        try:
            while True:
                block = stream.read(4096)
                if not block:
                    return
                remaining = (
                    _STARTUP_DECISION_DARWIN_LS_OUTPUT_BYTES
                    - len(output[label])
                )
                if len(block) > remaining:
                    if remaining:
                        output[label].extend(block[:remaining])
                    overflow.set()
                    return
                output[label].extend(block)
        except BaseException as exc:
            errors.append(exc)
            overflow.set()
        finally:
            try:
                stream.close()
            except Exception:
                pass

    workers = [
        threading.Thread(target=drain, args=("stdout", process.stdout), daemon=True),
        threading.Thread(target=drain, args=("stderr", process.stderr), daemon=True),
    ]
    for worker in workers:
        worker.start()
    deadline = time.monotonic() + _STARTUP_DECISION_DARWIN_LS_TIMEOUT_SECONDS
    timed_out = False
    while process.poll() is None and not overflow.is_set():
        if time.monotonic() >= deadline:
            timed_out = True
            break
        overflow.wait(0.01)
    if timed_out or overflow.is_set():
        try:
            process.kill()
        except OSError:
            pass
    try:
        returncode = process.wait(timeout=1.0)
    except subprocess.TimeoutExpired as exc:
        try:
            process.kill()
        except OSError:
            pass
        process.wait(timeout=1.0)
        raise RuntimeError("Darwin startup-decision ACL inspection did not stop") from exc
    for worker in workers:
        worker.join(timeout=1.0)
    if any(worker.is_alive() for worker in workers) or errors:
        raise RuntimeError("Darwin startup-decision ACL output could not be bounded")
    if timed_out:
        raise RuntimeError("Darwin startup-decision ACL inspection timed out")
    if overflow.is_set():
        raise RuntimeError("Darwin startup-decision ACL output exceeds its bound")
    return returncode, bytes(output["stdout"]), bytes(output["stderr"])


def _startup_decision_darwin_acl_authority(path):
    """Reject ACL-bearing or ambiguous Darwin directory authority."""
    returncode, stdout, stderr = _startup_decision_darwin_ls(path)
    if returncode != 0 or stderr or not stdout.endswith(b"\n"):
        raise RuntimeError("Darwin startup-decision ACL inspection is ambiguous")
    lines = stdout.splitlines()
    if len(lines) != 1:
        raise RuntimeError("Darwin startup-decision directory carries an ACL")
    match = re.match(rb"^[bcdlps-][rwxStTs-]{9}([+@]?)\s", lines[0])
    if match is None:
        raise RuntimeError("Darwin startup-decision ACL marker is ambiguous")
    if match.group(1) == b"+":
        raise RuntimeError("Darwin startup-decision directory carries an ACL")
    return "DARWIN_NO_ACL"


def _startup_decision_posix_directory_row(path, info, *, effective_uid):
    mode = stat.S_IMODE(info.st_mode)
    owner = int(info.st_uid)
    if (
        not stat.S_ISDIR(info.st_mode)
        or stat.S_ISLNK(info.st_mode)
        or _python_dependency_census_reparse(info)
        or int(info.st_nlink) <= 0
        or owner not in {0, int(effective_uid)}
        or (
            mode & (stat.S_IWGRP | stat.S_IWOTH)
            and not mode & stat.S_ISVTX
        )
    ):
        raise RuntimeError(
            f"startup-decision directory ancestry is unsafe: {path}"
        )
    return (
        str(path), int(info.st_dev), int(info.st_ino), int(info.st_nlink),
        mode, owner, int(getattr(info, "st_ctime_ns", 0)),
    )


def _startup_decision_directory_chain_authority(
    directory, *, platform_name=None, effective_uid=None,
):
    """Bind canonical receipt ancestry and reject cross-user replacement."""
    platform_name = platform_name or (
        "darwin" if sys.platform == "darwin" else os.name
    )
    raw = Path(os.path.abspath(os.fspath(directory)))
    canonical = raw.resolve(strict=True)
    if os.path.normcase(os.fspath(raw)) != os.path.normcase(os.fspath(canonical)):
        raise RuntimeError("startup-decision directory ancestry is indirect")
    chain = []
    cursor = canonical
    while True:
        chain.append(cursor)
        if cursor.parent == cursor:
            break
        cursor = cursor.parent
    rows = []
    for path in reversed(chain):
        info = os.stat(path, follow_symlinks=False)
        if (
            not stat.S_ISDIR(info.st_mode)
            or stat.S_ISLNK(info.st_mode)
            or _python_dependency_census_reparse(info)
            or int(info.st_nlink) <= 0
        ):
            raise RuntimeError(
                f"startup-decision directory ancestry is indirect: {path}"
            )
        if platform_name == "nt":
            _win_launcher_require_persistent_acls(path)
            security = _win_launcher_security_snapshot_path(
                path, directory=True,
                dangerous_mask=_WIN_LAUNCHER_ANCESTOR_DANGEROUS,
                additional_trusted_sids=_WIN_STARTUP_ANCESTOR_TRUSTED_SIDS,
                reject_inherit_only=False,
            )
            rows.append((
                str(path), int(info.st_dev), int(info.st_ino),
                int(info.st_nlink), int(info.st_mode), security,
            ))
        else:
            uid = os.geteuid() if effective_uid is None else int(effective_uid)
            row = _startup_decision_posix_directory_row(
                path, info, effective_uid=uid,
            )
            if platform_name == "darwin":
                row += (_startup_decision_darwin_acl_authority(path),)
            rows.append(row)
    return tuple(rows)


def _startup_decision_directory_chain_replays(before, after):
    """Compare stable directory identity and access authority across creation."""
    if len(before) != len(after):
        return False
    for left, right in zip(before, after):
        if (
            (left[0], left[1], left[2], left[4], left[5])
            != (right[0], right[1], right[2], right[4], right[5])
            or len(left) != len(right)
            or (len(left) > 7 and left[7:] != right[7:])
        ):
            return False
    return True


@contextlib.contextmanager
def _startup_decision_retain_windows_chain(authority):
    """Keep admitted Windows ancestors non-replaceable through publication."""
    if os.name != "nt":
        yield
        return
    handles = []
    try:
        for row in authority:
            handle = _win_launcher_open_security(row[0], directory=True)
            handles.append(handle)
            security = _win_launcher_security_snapshot_handle(
                handle, directory=True,
                dangerous_mask=_WIN_LAUNCHER_ANCESTOR_DANGEROUS,
                additional_trusted_sids=_WIN_STARTUP_ANCESTOR_TRUSTED_SIDS,
                reject_inherit_only=False,
            )
            if security != row[5]:
                raise RuntimeError(
                    "retained startup-decision ancestor authority differs"
                )
        yield
        for row, handle in zip(authority, handles):
            security = _win_launcher_security_snapshot_handle(
                handle, directory=True,
                dangerous_mask=_WIN_LAUNCHER_ANCESTOR_DANGEROUS,
                additional_trusted_sids=_WIN_STARTUP_ANCESTOR_TRUSTED_SIDS,
                reject_inherit_only=False,
            )
            if security != row[5]:
                raise RuntimeError(
                    "retained startup-decision ancestor authority changed"
                )
    finally:
        if handles:
            api = _win_launcher_security_api()
            for handle in reversed(handles):
                api["kernel32"].CloseHandle(handle)


def _startup_decision_user_base():
    return Path.home().absolute() / ".plamen-state" / "startup-decisions"


def _startup_decision_canonical_temp_base(raw_base):
    """Resolve platform temp aliases before applying ancestry authority."""
    return Path(os.path.abspath(os.fspath(raw_base))).resolve(strict=True)


def _startup_decision_paths_overlap(left, right):
    """Return whether either canonical path contains the other."""
    left = Path(left)
    right = Path(right)
    try:
        right.relative_to(left)
        return True
    except ValueError:
        pass
    try:
        left.relative_to(right)
        return True
    except ValueError:
        return False


def _startup_decision_protected_roots(config_path, target):
    config = Path(os.path.abspath(os.fspath(config_path))).resolve(strict=False)
    roots = [config, config.parent]
    if target:
        roots.append(
            Path(os.path.abspath(os.fspath(target))).resolve(strict=False)
        )
    return tuple(roots)


def _startup_decision_base_is_protected(base, protected):
    return any(
        _startup_decision_paths_overlap(base, root) for root in protected
    )


def _startup_decision_ensure_user_base():
    """Create the preferred per-user receipt base with private authority."""
    base = _startup_decision_user_base()
    home = Path.home().absolute()
    home_authority = _startup_decision_directory_chain_authority(home)
    with _startup_decision_retain_windows_chain(home_authority):
        current = home
        for component in (".plamen-state", "startup-decisions"):
            current = current / component
            if not os.path.lexists(current):
                if os.name == "nt":
                    _win_launcher_create_directory_secure(current)
                else:
                    os.mkdir(current, 0o700)
            info = os.stat(current, follow_symlinks=False)
            if (
                not stat.S_ISDIR(info.st_mode)
                or stat.S_ISLNK(info.st_mode)
                or _python_dependency_census_reparse(info)
            ):
                raise RuntimeError("startup-decision user base is indirect")
    if os.name == "nt":
        _win_launcher_security_snapshot_path(
            base, directory=True,
            dangerous_mask=_WIN_LAUNCHER_EXACT_DANGEROUS,
            require_exact=True,
        )
    else:
        info = os.stat(base, follow_symlinks=False)
        if int(info.st_uid) != os.geteuid() or stat.S_IMODE(info.st_mode) != 0o700:
            raise RuntimeError("startup-decision user base is not private")
    _startup_decision_directory_chain_authority(base)
    return base


def _resume_startup_decision_destination(config_path: str, target: str) -> Path:
    """Return one fresh decision-receipt path outside protected audit evidence."""
    import tempfile as _tempfile

    protected = _startup_decision_protected_roots(config_path, target)
    bases = []
    preferred = _startup_decision_user_base().resolve(strict=False)
    if not _startup_decision_base_is_protected(preferred, protected):
        try:
            admitted = Path(_startup_decision_ensure_user_base()).resolve(strict=True)
            if _startup_decision_base_is_protected(admitted, protected):
                raise RuntimeError(
                    "startup-decision user base changed into protected evidence"
                )
            bases.append(admitted)
        except (OSError, RuntimeError):
            pass
    try:
        temporary = _startup_decision_canonical_temp_base(_tempfile.gettempdir())
    except (OSError, RuntimeError):
        temporary = None
    if (
        temporary is not None
        and not _startup_decision_base_is_protected(temporary, protected)
    ):
        bases.append(temporary)
    for base in bases:
        try:
            base_authority = _startup_decision_directory_chain_authority(base)
        except (OSError, RuntimeError):
            continue
        with _startup_decision_retain_windows_chain(base_authority):
            try:
                private_parent = Path(_tempfile.mkdtemp(
                    prefix="plamen-startup-decision-", dir=str(base),
                )).resolve(strict=True)
            except OSError:
                continue
            info = os.stat(private_parent, follow_symlinks=False)
            if (
                not stat.S_ISDIR(info.st_mode)
                or stat.S_ISLNK(info.st_mode)
                or _python_dependency_census_reparse(info)
                or int(info.st_nlink) <= 0
            ):
                raise RuntimeError("startup-decision private directory is indirect")
            if os.name == "nt":
                _win_launcher_require_persistent_acls(private_parent)
                _win_launcher_security_snapshot_path(
                    private_parent,
                    directory=True,
                    dangerous_mask=_WIN_LAUNCHER_EXACT_DANGEROUS,
                )
            elif (
                int(info.st_uid) != os.geteuid()
                or stat.S_IMODE(info.st_mode) != 0o700
            ):
                raise RuntimeError(
                    "startup-decision private directory permissions are unsafe"
                )
            if not _startup_decision_directory_chain_replays(
                base_authority,
                _startup_decision_directory_chain_authority(base),
            ):
                raise RuntimeError(
                    "startup-decision base authority changed during publication"
                )
            _startup_decision_directory_chain_authority(private_parent)
            destination = private_parent / "decision.json"
            escaped = not _startup_decision_base_is_protected(
                destination, protected,
            )
            if escaped and not os.path.lexists(destination):
                return destination
    raise RuntimeError(
        "no fresh startup-decision receipt destination exists outside the audit"
    )


def _resume_startup_decision_read_location(path: Path, *, platform_name=None):
    """Return the retained authority root/components for one receipt path."""
    path = Path(os.path.abspath(os.fspath(path)))
    if not path.anchor:
        raise ValueError("startup-decision receipt path is not absolute")
    if (platform_name or os.name) == "nt":
        root = Path(path.anchor)
        components = tuple(path.relative_to(root).parts)
    else:
        root = path.parent
        components = (path.name,)
    return path, root, components


def _load_authenticated_audit_decision_receipt(
    path: Path, *, receipt_mac_key: bytes,
) -> dict:
    """Retain, bound, canonically decode, and authenticate one decision."""
    path, root, components = _resume_startup_decision_read_location(path)
    try:
        descriptor, raw = _codex_install_committed_read(
            root,
            components,
            maximum=1024 * 1024,
        )
        if (
            descriptor.get("kind") != "file"
            or descriptor.get("links") != 1
            or descriptor.get("reparse_tag") != 0
            or not raw
            or len(raw) > 1024 * 1024
            or descriptor.get("size") != len(raw)
        ):
            raise ValueError("receipt is not one bounded ordinary file")
    except (OSError, RuntimeError, ValueError) as exc:
        raise ValueError("startup-decision receipt is unavailable") from exc
    try:
        value = json.loads(raw.decode("utf-8"))
    except (UnicodeError, ValueError, TypeError) as exc:
        raise ValueError("audit-decision receipt is not valid JSON") from exc
    expected_raw = (
        json.dumps(value, indent=2, sort_keys=True, ensure_ascii=False) + "\n"
    ).encode("utf-8")
    if not isinstance(value, dict) or raw != expected_raw:
        raise ValueError("audit-decision receipt is not canonical JSON")
    receipt_mac = value.get("receipt_mac")
    authenticated = dict(value)
    authenticated.pop("receipt_mac", None)
    if (
        type(receipt_mac_key) is not bytes
        or len(receipt_mac_key) != 32
        or type(receipt_mac) is not str
        or re.fullmatch(r"[0-9a-f]{64}", receipt_mac) is None
        or not hmac.compare_digest(
            receipt_mac,
            hmac.new(
                receipt_mac_key,
                json.dumps(
                    authenticated, sort_keys=True, separators=(",", ":"),
                    ensure_ascii=False,
                ).encode("utf-8"),
                hashlib.sha256,
            ).hexdigest(),
        )
    ):
        raise ValueError("audit-decision receipt authentication differs")
    return value


def _load_resume_startup_decision(
    path: Path, *, receipt_mac_key: bytes,
    _authenticated_value: dict | None = None,
) -> dict:
    """Strictly replay one driver-authored startup-decision receipt."""
    value = (
        _load_authenticated_audit_decision_receipt(
            path, receipt_mac_key=receipt_mac_key,
        )
        if _authenticated_value is None else _authenticated_value
    )
    if (
        not isinstance(value, dict)
        or set(value) != _STARTUP_DECISION_RECEIPT_FIELDS
        or value.get("schema") != "plamen.startup-decision.v3"
        or value.get("startup_intent") != "RESUME_EXISTING"
        or value.get("evidence_preserved") is not True
        or value.get("model_launch_allowed") is not False
        or type(value.get("exit_status")) is not int
        or value.get("exit_status") != 5
        or value.get("allowed_actions") != [
            "RESUME_EXISTING", "START_NEW_RUN", "MIGRATE_EXISTING",
        ]
    ):
        raise ValueError("startup-decision receipt authority differs")
    changed = value.get("changed_components")
    components = value.get("component_digests")
    if (
        not isinstance(changed, list)
        or not changed
        or any(
            type(name) is not str
            or re.fullmatch(r"[a-zA-Z0-9_.-]{1,96}", name) is None
            for name in changed
        )
        or len(changed) != len(set(changed))
        or not isinstance(components, dict)
        or not set(changed).issubset(components)
    ):
        raise ValueError("startup-decision component roster differs")
    nullable_digest = lambda item: (
        item is None
        or (
            type(item) is str
            and re.fullmatch(r"[0-9a-f]{64}", item) is not None
        )
    )
    required_digest = lambda item: (
        type(item) is str
        and re.fullmatch(r"[0-9a-f]{64}", item) is not None
    )
    if not nullable_digest(value.get("stored_snapshot_digest")) or not required_digest(
        value.get("current_snapshot_digest")
    ):
        raise ValueError("startup-decision snapshot digest differs")
    for name, row in components.items():
        if (
            type(name) is not str
            or re.fullmatch(r"[a-zA-Z0-9_.-]{1,96}", name) is None
            or type(row) is not dict
            or set(row) != {"stored_digest", "current_digest", "changed"}
            or not nullable_digest(row["stored_digest"])
            or not nullable_digest(row["current_digest"])
            or type(row["changed"]) is not bool
            or row["changed"] != (name in changed)
        ):
            raise ValueError("startup-decision component authority differs")

    run_id = value.get("run_id")
    valid_run_id = False
    if type(run_id) is str:
        try:
            if str(uuid.UUID(run_id)) != run_id:
                raise ValueError
            valid_run_id = True
        except (ValueError, TypeError, AttributeError) as exc:
            raise ValueError("startup-decision run identity differs") from exc
    elif run_id is not None:
        raise ValueError("startup-decision run identity differs")

    verdict = value.get("snapshot_verdict")
    required_action = value.get("required_action")
    if verdict == "MISMATCH":
        if (
            required_action
            != "RESTORE_EXACT_INPUTS_OR_USE_DISTINCT_RUN_DESTINATION"
            or not required_digest(value.get("stored_snapshot_digest"))
            or not valid_run_id
        ):
            raise ValueError("startup-decision mismatch relationship differs")
    elif verdict == "LEGACY_UNBOUND":
        if required_action == (
            "AUTHORIZE_VERSIONED_MIGRATION_OR_USE_DISTINCT_RUN_DESTINATION"
        ):
            if run_id is None and changed != ["run_identity"]:
                raise ValueError("startup-decision legacy relationship differs")
        elif required_action == "USE_EMPTY_CHECKPOINT_FOR_NEW_DESTINATION":
            if not valid_run_id or changed != ["run_identity_collision"]:
                raise ValueError("startup-decision legacy relationship differs")
        else:
            raise ValueError("startup-decision required action differs")
    else:
        raise ValueError("startup-decision verdict differs")

    decision_id = value.get("decision_id")
    unsigned = dict(value)
    unsigned.pop("decision_id", None)
    unsigned.pop("receipt_mac", None)
    expected_id = hashlib.sha256(
        json.dumps(
            unsigned, sort_keys=True, separators=(",", ":"),
            ensure_ascii=False,
        ).encode("utf-8")
    ).hexdigest()
    if decision_id != expected_id:
        raise ValueError("startup-decision identity differs")
    return value


def _load_midphase_audit_input_drift_decision(
    path: Path, *, receipt_mac_key: bytes,
    _authenticated_value: dict | None = None,
) -> dict:
    """Strictly validate one authenticated stage-aware drift decision."""
    value = (
        _load_authenticated_audit_decision_receipt(
            path, receipt_mac_key=receipt_mac_key,
        )
        if _authenticated_value is None else _authenticated_value
    )
    nullable_digest = lambda item: (
        item is None
        or (
            type(item) is str
            and re.fullmatch(r"[0-9a-f]{64}", item) is not None
        )
    )
    if (
        type(value) is not dict
        or set(value) != _MIDPHASE_DRIFT_DECISION_RECEIPT_FIELDS
        or value.get("schema") != "plamen.audit-input-drift-decision.v1"
        or value.get("decision_kind") != "MID_PHASE_AUDIT_INPUT_DRIFT"
        or value.get("launch_intent") not in {
            "RESUME_EXISTING", "START_NEW_RUN",
        }
        or type(value.get("exit_status")) is not int
        or value.get("exit_status") != 5
        or value.get("snapshot_verdict") not in {
            "MISMATCH", "UNBOUND_RUNTIME_SNAPSHOT",
        }
        or not nullable_digest(value.get("stored_snapshot_digest"))
        or not nullable_digest(value.get("current_snapshot_digest"))
        or value.get("prior_phase_or_run_model_state") != "NOT_ASSERTED"
        or value.get("drift_evidence_relative_path") != "audit_input_drift.json"
        or value.get("existing_evidence_deletion_performed") is not False
        or value.get("driver_continued_after_detection") is not False
        or value.get("required_action")
        != "RESTORE_EXACT_INPUTS_OR_USE_DISTINCT_RUN_DESTINATION"
        or value.get("allowed_actions") != [
            "RESTORE_EXACT_INPUTS", "USE_DISTINCT_RUN_DESTINATION",
        ]
        or value.get("receipt_authentication_scope")
        != "ONE_FRONTEND_CHILD_INVOCATION"
        or value.get("same_user_process_compromise_out_of_scope") is not True
    ):
        raise ValueError("mid-phase drift decision authority differs")

    try:
        run_id = value.get("run_id")
        if type(run_id) is not str or str(uuid.UUID(run_id)) != run_id:
            raise ValueError
    except (ValueError, TypeError, AttributeError) as exc:
        raise ValueError("mid-phase drift run identity differs") from exc

    phase = value.get("phase")
    changed = value.get("changed_components")
    if (
        type(phase) is not str
        or re.fullmatch(r"[a-zA-Z0-9_.-]{1,96}", phase) is None
        or type(changed) is not list
        or not changed
        or len(changed) > 256
        or changed != sorted(changed)
        or len(changed) != len(set(changed))
        or any(
            type(name) is not str
            or re.fullmatch(r"[a-zA-Z0-9_.-]{1,96}", name) is None
            for name in changed
        )
    ):
        raise ValueError("mid-phase drift component/phase roster differs")

    runtime_changes = value.get("runtime_entry_changes")
    if type(runtime_changes) is not list or len(runtime_changes) > 256:
        raise ValueError("mid-phase runtime-entry roster differs")
    identities = []
    for row in runtime_changes:
        if type(row) is not dict or set(row) != {
            "component", "identity", "stored", "current",
        }:
            raise ValueError("mid-phase runtime-entry shape differs")
        identity = row.get("identity")
        if (
            row.get("component") != "toolchain"
            or type(identity) is not str
            or not identity.startswith("@runtime/")
            or len(identity.encode("utf-8")) > 512
            or any(character in identity for character in "\x00\r\n")
        ):
            raise ValueError("mid-phase runtime-entry identity differs")
        for side in ("stored", "current"):
            entry = row.get(side)
            if entry is None:
                continue
            if (
                type(entry) is not dict
                or set(entry) != {"sha256", "byte_count"}
                or type(entry.get("sha256")) is not str
                or re.fullmatch(r"[0-9a-f]{64}", entry["sha256"]) is None
                or type(entry.get("byte_count")) is not int
                or entry["byte_count"] < 0
            ):
                raise ValueError("mid-phase runtime-entry digest/size differs")
        if row.get("stored") is None and row.get("current") is None:
            raise ValueError("mid-phase runtime-entry has no observation")
        identities.append(identity)
    if identities != sorted(identities) or len(identities) != len(set(identities)):
        raise ValueError("mid-phase runtime-entry ordering differs")
    if runtime_changes and "toolchain" not in changed:
        raise ValueError("mid-phase runtime-entry component relationship differs")

    stage = value.get("detection_stage")
    stage_relationships = {
        "PRE_PHASE_EXECUTION": (
            "NOT_ENTERED_IN_THIS_INVOCATION",
            "NO_CURRENT_PHASE_GENERATION_LAUNCHED_IN_THIS_INVOCATION",
        ),
        "POST_PHASE_EXECUTION": (
            "EXECUTION_OR_RECOVERY_PATH_ENTERED",
            "UNKNOWN_MAY_HAVE_LAUNCHED",
        ),
    }
    if stage not in stage_relationships or (
        value.get("phase_execution_state"),
        value.get("audit_model_generation_state"),
    ) != stage_relationships[stage]:
        raise ValueError("mid-phase drift stage relationship differs")

    decision_id = value.get("decision_id")
    unsigned = dict(value)
    unsigned.pop("decision_id", None)
    unsigned.pop("receipt_mac", None)
    expected_id = hashlib.sha256(
        json.dumps(
            unsigned, sort_keys=True, separators=(",", ":"),
            ensure_ascii=False,
        ).encode("utf-8")
    ).hexdigest()
    if decision_id != expected_id:
        raise ValueError("mid-phase drift decision identity differs")
    return value


def _render_resume_startup_decision(path: Path, *, receipt_mac_key: bytes) -> bool:
    """Render one verified startup or stage-aware stop; False if invalid."""
    try:
        authenticated = _load_authenticated_audit_decision_receipt(
            path, receipt_mac_key=receipt_mac_key,
        )
        if authenticated.get("schema") == "plamen.startup-decision.v3":
            decision = _load_resume_startup_decision(
                path, receipt_mac_key=receipt_mac_key,
                _authenticated_value=authenticated,
            )
            decision_kind = "startup"
        elif authenticated.get("schema") == (
            "plamen.audit-input-drift-decision.v1"
        ):
            decision = _load_midphase_audit_input_drift_decision(
                path, receipt_mac_key=receipt_mac_key,
                _authenticated_value=authenticated,
            )
            decision_kind = "midphase"
        else:
            return False
    except (OSError, ValueError, TypeError):
        return False
    if decision_kind == "midphase":
        w = sys.stdout.write
        phase = decision["phase"]
        stage = decision["detection_stage"]
        w("\n  This audit stopped after authenticated audit-input drift detection.\n")
        if stage == "PRE_PHASE_EXECUTION":
            w(f"  Phase {phase} was not entered in this frontend invocation.\n")
            w(
                "  No current-phase audit-model generation was launched in "
                "this frontend invocation.\n"
            )
        else:
            w(f"  Phase {phase} entered an execution or recovery path.\n")
            w(
                "  A current-phase audit-model generation may have launched; "
                "the receipt does not assert either outcome.\n"
            )
        w("  Prior phase or prior run model activity is not asserted.\n")
        w("  The driver reported no existing-evidence deletion.\n")
        w("  The driver reported that it did not continue after detecting drift.\n")
        w(
            "  Changed input component(s): "
            + ", ".join(decision["changed_components"]) + "\n"
        )
        for row in decision["runtime_entry_changes"]:
            old = row["stored"]
            new = row["current"]
            old_text = (
                "absent" if old is None
                else f"{old['sha256']} ({old['byte_count']} bytes)"
            )
            new_text = (
                "absent" if new is None
                else f"{new['sha256']} ({new['byte_count']} bytes)"
            )
            w(f"    {row['identity']}: {old_text} -> {new_text}\n")
        w("  Restore the exact original inputs or use a distinct clean destination.\n")
        w(f"  Decision receipt retained at: {path}\n")
        return True
    changed = ", ".join(decision["changed_components"])
    w = sys.stdout.write
    w("\n  This resume attempt stopped during startup.\n")
    w(
        "  The driver reported that it launched no new audit-model "
        "generation.\n"
    )
    w("  The driver reported that existing audit evidence was preserved.\n")
    w(
        "  The one-use local authenticator binds this receipt to this frontend "
        "invocation; it does not defend against same-user process compromise.\n"
    )
    w(f"  Changed input component(s) reported by the driver: {changed}\n")
    w("\n  Choose one safe action:\n")
    w("    1. Restore the exact original input bytes identified above.\n")
    w("    2. Create a distinct clean scratchpad/config destination and start it ")
    w("with `plamen start-config <new-config.json>`.\n")
    w("  Versioned in-place audit migration is not implemented.\n")
    w("  Repeating the current resume without restoring exact inputs will stop again.\n")
    w(f"  Decision receipt retained at: {path}\n")
    return True


def _render_driver_result(
    returncode: int, config_path: str, target: str, *,
    decision_receipt_path: Path | None = None,
    decision_mac_key: bytes | None = None,
) -> int:
    """Render the driver's typed exit state without claiming false success."""
    report = os.path.join(target, "AUDIT_REPORT.md")
    scratchpad = os.path.dirname(config_path)
    resume_cmd = f'plamen resume "{config_path}"'
    w = sys.stdout.write
    if returncode == 0 and os.path.isfile(report):
        w("\n  Pipeline completed and released a report.\n")
        w(f"  Report: {report}\n")
        return 0
    if returncode == 0:
        w("\n  Pipeline execution ended, but NO DELIVERABLE was released.\n")
        w("  Treat this run as degraded; inspect report-integrity/runtime debt.\n")
        w(f"  Scratchpad: {scratchpad}\n  Resume: {resume_cmd}\n")
        return 3
    if returncode == 5:
        if (
            decision_receipt_path is not None
            and decision_mac_key is not None
            and _render_resume_startup_decision(
                decision_receipt_path,
                receipt_mac_key=decision_mac_key,
            )
        ):
            return 5
        w("\n  Pipeline stopped with exit 5, but no valid typed startup-decision ")
        w("receipt was available.\n")
        w("  The frontend cannot certify whether audit execution began or whether ")
        w("a model was launched.\n")
        w("  The frontend did not alter or delete existing evidence; do not ")
        w("repeat resume blindly.\n")
        if decision_receipt_path is not None:
            w(f"  Expected decision receipt: {decision_receipt_path}\n")
        else:
            w("  No decision-receipt destination was supplied.\n")
        w("  Restore exact original inputs or use a distinct clean destination.\n")
        return 5
    labels = {
        2: "paused by a rate/usage limit",
        3: "completed in a degraded state",
        4: "stopped because its configuration is missing",
        42: "hibernating until its recorded wake time",
        130: "interrupted; artifacts were preserved",
    }
    label = labels.get(returncode, f"stopped with error exit {returncode}")
    w(f"\n  Pipeline {label}.\n")
    if os.path.isfile(report):
        w(f"  Current report: {report}\n")
    w(f"  Scratchpad: {scratchpad}\n  Resume: {resume_cmd}\n")
    return returncode


def resume_v2(config_path: str):
    """Resume an existing audit via the non-destructive driver contract."""
    driver = os.path.join(PLAMEN_HOME, "scripts", "plamen_driver.py")
    if not os.path.isfile(driver):
        sys.stdout.write(f"  {_C_RED}✗ Driver not found: {driver}{_RST}\n")
        sys.exit(1)

    import json as _json
    with open(config_path, encoding="utf-8") as f:
        config = _json.load(f)
    target = config.get("project_root", "")
    pipeline = config.get("pipeline", "sc").upper()
    mode = config.get("mode", "core")

    console.print(Rule(style="color(238)"))
    w = sys.stdout.write
    w(f"\n  {_BOLD}{_C_WHITE}Resuming audit driver ({pipeline} {mode})...{_RST}\n\n")
    sys.stdout.flush()

    decision_receipt_path = _resume_startup_decision_destination(
        config_path, target,
    )
    decision_mac_key = bytearray(secrets.token_bytes(32))
    cmd = [
        sys.executable, driver,
        "--startup-intent", "RESUME_EXISTING",
        "--startup-decision-receipt",
        str(decision_receipt_path),
        config_path,
    ]

    if sys.platform == "win32":
        os.system("")
    child_env = os.environ.copy()
    child_env["PLAMEN_STARTUP_DECISION_MAC_KEY"] = bytes(
        decision_mac_key
    ).hex()
    try:
        result = subprocess.run(cmd, env=child_env)
        rendered = _render_driver_result(
            result.returncode, config_path, target,
            decision_receipt_path=decision_receipt_path,
            decision_mac_key=bytes(decision_mac_key),
        )
    finally:
        child_env.pop("PLAMEN_STARTUP_DECISION_MAC_KEY", None)
        for index in range(len(decision_mac_key)):
            decision_mac_key[index] = 0
    sys.exit(rendered)


def start_config_v2(config_path: str):
    """Start a pre-created clean config via the locked managed runtime."""
    import json as _json

    config_path = os.path.abspath(config_path)
    if not os.path.isfile(config_path):
        sys.stdout.write(
            f"  {_C_RED}Config not found: {config_path}{_RST}\n"
        )
        sys.exit(1)
    try:
        with open(config_path, encoding="utf-8") as handle:
            config = _json.load(handle)
    except (OSError, ValueError) as exc:
        sys.stdout.write(f"  {_C_RED}Invalid config: {exc}{_RST}\n")
        sys.exit(1)

    scratchpad = os.path.abspath(str(config.get("scratchpad") or ""))
    project_root = os.path.abspath(str(config.get("project_root") or ""))
    if (
        not scratchpad
        or not project_root
        or not os.path.isdir(project_root)
        or os.path.normcase(os.path.dirname(config_path))
        != os.path.normcase(scratchpad)
        or os.path.basename(config_path) != "config.json"
    ):
        sys.stdout.write(
            f"  {_C_RED}Config path/project/scratchpad authority is invalid.{_RST}\n"
        )
        sys.exit(1)
    try:
        entries = sorted(os.listdir(scratchpad))
    except OSError as exc:
        sys.stdout.write(
            f"  {_C_RED}Cannot inspect run destination: {exc}{_RST}\n"
        )
        sys.exit(1)
    if entries != ["config.json"]:
        sys.stdout.write(
            f"  {_C_RED}Refusing non-clean new-run destination: {scratchpad}{_RST}\n"
            f"  {_C_GRAY}Use `plamen resume` for an existing run.{_RST}\n"
        )
        sys.exit(1)

    driver = os.path.join(PLAMEN_HOME, "scripts", "plamen_driver.py")
    if not os.path.isfile(driver):
        sys.stdout.write(f"  {_C_RED}Driver not found: {driver}{_RST}\n")
        sys.exit(1)
    console.print(Rule(style="color(238)"))
    sys.stdout.write(
        f"\n  {_BOLD}{_C_WHITE}Launching pre-created audit config...{_RST}\n\n"
        f"  {_C_GRAY}Config: {config_path}{_RST}\n"
        f"  {_C_GRAY}If interrupted, resume with:{_RST}\n"
        f"  {_C_WHITE}  plamen resume \"{config_path}\"{_RST}\n\n"
    )
    sys.stdout.flush()
    decision_receipt_path = _resume_startup_decision_destination(
        config_path, project_root,
    )
    decision_mac_key = bytearray(secrets.token_bytes(32))
    cmd = [
        sys.executable,
        driver,
        "--startup-intent",
        "START_NEW_RUN",
        "--startup-decision-receipt",
        str(decision_receipt_path),
        config_path,
    ]
    if sys.platform == "win32":
        os.system("")
    child_env = os.environ.copy()
    child_env["PLAMEN_STARTUP_DECISION_MAC_KEY"] = bytes(
        decision_mac_key
    ).hex()
    try:
        result = subprocess.run(cmd, env=child_env)
        rendered = _render_driver_result(
            result.returncode, config_path, project_root,
            decision_receipt_path=decision_receipt_path,
            decision_mac_key=bytes(decision_mac_key),
        )
    finally:
        child_env.pop("PLAMEN_STARTUP_DECISION_MAC_KEY", None)
        for index in range(len(decision_mac_key)):
            decision_mac_key[index] = 0
    sys.exit(rendered)


# ── Launch ───────────────────────────────────────────────────

def _launch_v2_bound_config_value(
    pipeline, mode, target, language, *, cli_backend,
    docs="", scope_file="", scope_notes="", proven_only=False,
    tier="", subsystem_scope="", fork_mode="standalone",
    allow_model_fallback=False, claude_exec_mode="",
    transport_resolution,
):
    """Render config from one authenticated, context-bound transport result."""
    bound_backend, bound_exec_mode, _warning = _replay_new_transport_resolution(
        transport_resolution, pipeline=pipeline, mode=mode,
    )
    if cli_backend != bound_backend or claude_exec_mode != bound_exec_mode:
        raise RuntimeError("bound transport differs from launch arguments")
    cli_backend = bound_backend
    claude_exec_mode = bound_exec_mode
    if cli_backend == "claude":
        _admitted_claude_model_environment()
    target = os.path.abspath(target)
    scratchpad = os.path.join(target, ".scratchpad")
    config = {
        "project_root": target, "scratchpad": scratchpad, "mode": mode,
        "pipeline": pipeline, "language": language,
        "cli_backend": cli_backend,
        "claude_exec_mode": claude_exec_mode,
        "allow_model_fallback": bool(allow_model_fallback),
    }
    if pipeline == "sc":
        config.update({
            "docs_path": docs, "scope_file": scope_file,
            "scope_notes": scope_notes, "proven_only": proven_only,
        })
    elif pipeline == "l1":
        config.update({
            "tier": tier, "subsystem_scope": subsystem_scope,
            "fork_mode": fork_mode, "docs_path": docs,
        })
    else:
        raise RuntimeError("unknown Plamen pipeline")
    return config


def _launch_v2_config_value(
    pipeline, mode, target, language, *, cli_backend,
    docs="", scope_file="", scope_notes="", proven_only=False,
    tier="", subsystem_scope="", fork_mode="standalone",
    allow_model_fallback=False, claude_exec_mode="",
):
    """Resolve raw launch input once and render its new-run config."""
    resolution = _bind_new_claude_transport(
        pipeline, mode, cli_backend, claude_exec_mode,
    )
    bound_backend, bound_exec_mode, _warning = _replay_new_transport_resolution(
        resolution, pipeline=pipeline, mode=mode,
    )
    return _launch_v2_bound_config_value(
        pipeline, mode, target, language,
        cli_backend=bound_backend, docs=docs, scope_file=scope_file,
        scope_notes=scope_notes, proven_only=proven_only, tier=tier,
        subsystem_scope=subsystem_scope, fork_mode=fork_mode,
        allow_model_fallback=allow_model_fallback,
        claude_exec_mode=bound_exec_mode,
        transport_resolution=resolution,
    )


def launch_v2(pipeline: str, mode: str, target: str, language: str,
              docs: str = "", scope_file: str = "", scope_notes: str = "",
              proven_only: bool = False, tier: str = "",
              subsystem_scope: str = "", fork_mode: str = "standalone",
              cli_backend: str = "", allow_model_fallback: bool = False,
              claude_exec_mode: str = "", *, _transport_resolution=None):
    """Write config.json and run plamen_driver.py (deterministic driver)."""
    import json as _json

    target = os.path.abspath(target)
    if not cli_backend and _transport_resolution is None:
        detected_backends = _detect_cli_backends()
        cli_backend = (
            detected_backends[0]
            if len(detected_backends) == 1
            else _ambient_backend(detected_backends)
        )
    try:
        if _transport_resolution is None:
            config = _launch_v2_config_value(
                pipeline, mode, target, language, cli_backend=cli_backend,
                docs=docs, scope_file=scope_file, scope_notes=scope_notes,
                proven_only=proven_only, tier=tier,
                subsystem_scope=subsystem_scope, fork_mode=fork_mode,
                allow_model_fallback=allow_model_fallback,
                claude_exec_mode=claude_exec_mode,
            )
        else:
            config = _launch_v2_bound_config_value(
                pipeline, mode, target, language, cli_backend=cli_backend,
                docs=docs, scope_file=scope_file, scope_notes=scope_notes,
                proven_only=proven_only, tier=tier,
                subsystem_scope=subsystem_scope, fork_mode=fork_mode,
                allow_model_fallback=allow_model_fallback,
                claude_exec_mode=claude_exec_mode,
                transport_resolution=_transport_resolution,
            )
    except (RuntimeError, TypeError) as exc:
        sys.stdout.write(
            f"  {_C_RED}Refusing unsafe audit launch: {exc}{_RST}\n"
        )
        sys.exit(1)

    scratchpad = os.path.join(target, ".scratchpad")
    os.makedirs(scratchpad, exist_ok=True)
    try:
        prior_entries = os.listdir(scratchpad)
    except OSError as exc:
        sys.stdout.write(
            f"  {_C_RED}âœ— Cannot inspect run destination: {exc}{_RST}\n"
        )
        sys.exit(1)
    if prior_entries:
        sys.stdout.write(
            f"  {_C_RED}âœ— Refusing to overwrite an existing run destination.{_RST}\n"
            f"  {_C_GRAY}Existing scratchpad preserved: {scratchpad}{_RST}\n"
            f"  {_C_GRAY}Choose a distinct clean project/destination for a new run.{_RST}\n"
        )
        sys.exit(1)

    config_path = os.path.join(scratchpad, "config.json")
    # The clean-destination proof and exclusive config creation are one launch
    # authority.  Never replace an existing config or unrelated scratch byte.
    if os.listdir(scratchpad):
        sys.stdout.write(
            f"  {_C_RED}Refusing changed run destination: {scratchpad}{_RST}\n"
        )
        sys.exit(1)
    _config_raw = _json.dumps(config, indent=2).encode("utf-8")
    try:
        _config_fd = os.open(
            _fs_path(config_path),
            os.O_CREAT | os.O_EXCL | os.O_WRONLY,
            0o600,
        )
    except FileExistsError:
        sys.stdout.write(
            f"  {_C_RED}Refusing existing config: {config_path}{_RST}\n"
        )
        sys.exit(1)
    try:
        os.write(_config_fd, _config_raw)
        os.fsync(_config_fd)
    finally:
        os.close(_config_fd)

    driver = os.path.join(PLAMEN_HOME, "scripts", "plamen_driver.py")
    if not os.path.isfile(driver):
        sys.stdout.write(f"  {_C_RED}✗ Driver not found: {driver}{_RST}\n")
        sys.exit(1)

    console.print(Rule(style="color(238)"))
    w = sys.stdout.write
    w(f"\n  {_BOLD}{_C_WHITE}Launching audit driver ({pipeline.upper()} mode)...{_RST}\n\n")
    w(f"  {_C_GRAY}Config: {config_path}{_RST}\n")
    w(f"  {_C_GRAY}If interrupted, resume with:{_RST}\n")
    w(f"  {_C_WHITE}  plamen resume \"{config_path}\"{_RST}\n\n")
    sys.stdout.flush()

    if sys.platform == "win32":
        os.system("")
    # The destination was proven empty before config creation. START_NEW_RUN is
    # explicit and cannot reinterpret any later collision as overwrite authority.
    _driver_cmd = [
        sys.executable, driver,
        "--startup-intent", "START_NEW_RUN",
        config_path,
    ]
    result = subprocess.run(_driver_cmd)
    sys.exit(_render_driver_result(result.returncode, config_path, target))


def launch_claude(mode: str, target: str, docs: str,
                  network: str = "", scope_file: str = "", scope_notes: str = "",
                  **kwargs):
    """Launch 'compare' mode — runs /plamen compare in a Claude Code session."""
    claude_bin = shutil.which("claude")
    if not claude_bin:
        cw = sys.stdout.write
        cw(f"  {_C_RED}✗ `plamen compare` requires the Claude backend (`claude` CLI), which is not on PATH.{_RST}\n")
        cw(f"    {_C_GRAY}Compare runs as an in-session /plamen compare workflow and is not available on the{_RST}\n")
        cw(f"    {_C_GRAY}Codex backend. Install + authenticate Claude Code, or run a standard audit{_RST}\n")
        cw(f"    {_C_GRAY}(`plamen core` / `plamen thorough`), which both backends support.{_RST}\n")
        sys.exit(1)

    parts = ["/plamen compare"]
    if target:
        parts.append(f"report: {target}")
    if docs:
        parts.append(f"ground_truth: {docs}")
    prompt = " ".join(parts)

    console.print(Rule(style="color(238)"))
    w = sys.stdout.write
    w(f"\n  {_BOLD}{_C_WHITE}Launching Claude Code...{_RST}\n\n")
    sys.stdout.flush()

    if sys.platform == "win32":
        os.system("")
    result = subprocess.run([claude_bin, prompt])
    sys.exit(result.returncode)


# ── Main: state machine with back support ────────────────────

def _cli_usage_error(message: str):
    sys.stderr.write(f"plamen: {message}\nRun `plamen help` for usage.\n")
    raise SystemExit(2)


def _parse_cli_opts(args=None) -> dict:
    """Strictly parse public audit/plan arguments.

    Unknown flags, missing values, conflicting backends, and extra positional
    arguments are errors. Silent acceptance is dangerous for an audit tool.
    """
    args = list(sys.argv[1:] if args is None else args)
    opts = {
        "docs": "", "network": "", "scope_file": "", "scope_notes": "",
        "proven_only": False, "tier": "", "modules": "", "cli_backend": "",
        "claude_exec_mode": "",
        "allow_model_fallback": False, "yes": False, "json": False,
        "l1": False, "explain_routes": False, "positionals": [],
    }
    value_flags = {
        "--docs": "docs", "--network": "network", "--scope": "scope_file",
        "--notes": "scope_notes", "--tier": "tier", "--modules": "modules",
        "--claude-exec-mode": "claude_exec_mode",
    }
    bool_flags = {
        "--proven-only": "proven_only", "--strict": "proven_only",
        "--allow-model-fallback": "allow_model_fallback", "--yes": "yes",
        "--json": "json", "--l1": "l1", "--explain-routes": "explain_routes",
    }
    index = 0
    while index < len(args):
        token = args[index]
        if token in value_flags:
            if index + 1 >= len(args) or args[index + 1].startswith("--"):
                _cli_usage_error(f"{token} requires a value")
            option_name = value_flags[token]
            option_value = args[index + 1]
            if (
                option_name == "claude_exec_mode"
                and opts[option_name]
                and opts[option_name].lower() != option_value.lower()
            ):
                _cli_usage_error("Claude transport options are mutually exclusive")
            opts[option_name] = option_value
            index += 2
            continue
        if token in bool_flags:
            opts[bool_flags[token]] = True
            index += 1
            continue
        if token in {"--codex", "--claude"}:
            backend = token[2:]
            if opts["cli_backend"] and opts["cli_backend"] != backend:
                _cli_usage_error("--codex and --claude are mutually exclusive")
            opts["cli_backend"] = backend
            index += 1
            continue
        if token == "--claude-headless":
            transport = "headless"
            if opts["claude_exec_mode"] and opts["claude_exec_mode"] != transport:
                _cli_usage_error("Claude transport options are mutually exclusive")
            if opts["cli_backend"] == "codex":
                _cli_usage_error("Claude transport options conflict with --codex")
            opts["cli_backend"] = "claude"
            opts["claude_exec_mode"] = transport
            index += 1
            continue
        if token.startswith("-"):
            _cli_usage_error(f"unknown option: {token}")
        opts["positionals"].append(token)
        index += 1
    if len(opts["positionals"]) > 1:
        _cli_usage_error(
            "expected one target path, got: " + ", ".join(opts["positionals"])
        )
    if opts["tier"]:
        opts["tier"] = opts["tier"].lower()
        if opts["tier"] not in {"t0", "t1", "t2", "t3"}:
            _cli_usage_error("--tier must be one of T0, T1, T2, or T3")
    if opts["claude_exec_mode"]:
        opts["claude_exec_mode"] = opts["claude_exec_mode"].lower()
        if opts["claude_exec_mode"] != "headless":
            _cli_usage_error("--claude-exec-mode must be exactly headless")
        if opts["cli_backend"] == "codex":
            _cli_usage_error("--claude-exec-mode conflicts with --codex")
        opts["cli_backend"] = "claude"
    return opts


def _public_plan(mode: str, args) -> dict:
    """Resolve an audit launch without writing files or invoking a provider."""
    if mode not in {"light", "core", "thorough"}:
        _cli_usage_error("plan mode must be light, core, or thorough")
    opts = _parse_cli_opts(args)
    if not opts["positionals"]:
        _cli_usage_error("plan requires a target path")
    target = os.path.abspath(opts["positionals"][0])
    if not os.path.isdir(target):
        _cli_usage_error(f"target directory does not exist: {target}")
    if opts["scope_file"] and not os.path.isfile(os.path.abspath(opts["scope_file"])):
        _cli_usage_error(f"scope file does not exist: {opts['scope_file']}")
    docs = opts["docs"]
    if docs and not re.match(r"^https?://", docs, re.IGNORECASE) and not os.path.exists(docs):
        _cli_usage_error(f"docs path does not exist: {docs}")

    backends = _detect_cli_backends()
    backend = opts["cli_backend"] or _ambient_backend(backends)
    if backend not in backends:
        _cli_usage_error(f"requested backend is unavailable: {backend}")
    pipeline = "l1" if opts["l1"] else "sc"
    try:
        transport_resolution = _bind_new_claude_transport(
            pipeline, mode, backend, opts["claude_exec_mode"],
        )
        backend, claude_exec_mode, transport_warning = (
            _replay_new_transport_resolution(
                transport_resolution, pipeline=pipeline, mode=mode,
            )
        )
    except RuntimeError as exc:
        _cli_usage_error(str(exc))
    language = _detect_language(target)
    if pipeline == "l1":
        if language not in {"go", "rust"}:
            _cli_usage_error("L1 plan target must detect as Go or Rust")
        exts = {".go"} if language == "go" else {".rs"}
        tier = opts["tier"] or _detect_l1_tier(_count_loc(target, exts))
    else:
        if language in {"go", "rust"}:
            language = "evm"
        tier = ""

    scripts_dir = os.path.join(PLAMEN_HOME, "scripts")
    if scripts_dir not in sys.path:
        sys.path.insert(0, scripts_dir)
    from plamen_types import L1_PHASES, SC_PHASES, phase_model

    config = _launch_v2_bound_config_value(
        pipeline, mode, target, language, cli_backend=backend,
        docs=docs, scope_file=opts["scope_file"],
        scope_notes=opts["scope_notes"], proven_only=opts["proven_only"],
        tier=tier, subsystem_scope=opts["modules"],
        allow_model_fallback=opts["allow_model_fallback"],
        claude_exec_mode=claude_exec_mode,
        transport_resolution=transport_resolution,
    )
    phases = L1_PHASES if pipeline == "l1" else SC_PHASES
    active = [phase for phase in phases if mode in phase.modes]
    routes = [
        {"phase": phase.name, "model": phase_model(phase, mode, config)}
        for phase in active
    ]
    estimate = estimate_cost(
        target, mode, opts["scope_file"], opts["scope_notes"],
        backend=backend, pipeline=pipeline,
    )
    scratchpad = os.path.join(target, ".scratchpad")
    issues = []
    if os.path.isdir(scratchpad):
        try:
            if os.listdir(scratchpad):
                issues.append("run destination is not clean; resume or choose a distinct target")
        except OSError as exc:
            issues.append(f"run destination is unreadable: {exc}")
    return {
        "schema": "plamen.public_plan.v1",
        "pipeline": pipeline,
        "mode": mode,
        "target": target,
        "language": language,
        "tier": tier,
        "backend": backend,
        "claude_exec_mode": claude_exec_mode,
        "transport_warning": transport_warning,
        "phase_count": len(routes),
        "routes": routes,
        "model_fallback_authorized": bool(opts["allow_model_fallback"]),
        "config_path": os.path.join(scratchpad, "config.json"),
        "report_path": os.path.join(target, "AUDIT_REPORT.md"),
        "estimate": estimate,
        "launchable": not issues,
        "issues": issues,
        "provider_invocations": 0,
    }


def _print_public_plan(plan: dict, *, explain_routes: bool, as_json: bool) -> None:
    if as_json:
        print(json.dumps(plan, sort_keys=True, indent=2))
        return
    print("Plamen audit plan (no files written; no provider calls)")
    print(f"  Pipeline: {plan['pipeline'].upper()} {plan['mode']}")
    print(f"  Target:   {plan['target']}")
    print(f"  Backend:  {plan['backend']}")
    if plan["backend"] == "claude":
        print(f"  Transport: {plan['claude_exec_mode']}")
        if plan.get("transport_warning"):
            print(f"  Warning:  {plan['transport_warning']}")
    print(f"  Language: {plan['language']}")
    print(f"  Phases:   {plan['phase_count']}")
    print(f"  Fallback: {'explicitly authorized' if plan['model_fallback_authorized'] else 'disabled'}")
    print(f"  Report:   {plan['report_path']}")
    print(f"  Ready:    {'yes' if plan['launchable'] else 'no'}")
    for issue in plan["issues"]:
        print(f"  Issue:    {issue}")
    print("  Provider invocations: 0")
    if explain_routes:
        print("\nResolved model routes:")
        for route in plan["routes"]:
            print(f"  {route['phase']}: {route['model']}")


def _dry_config_native(project_root, *, action, payload=None):
    """Create/read/refuse the real launch config through retained native handles."""
    project_root = Path(project_root).absolute()
    root_handle, root_close = _codex_dispatcher_open_root(
        project_root, full_mutation=False,
    )
    scratch = None; config_handle = None
    try:
        try:
            scratch = _codex_native_open_relative(
                root_handle, ".scratchpad", directory=True, create=True,
                access=0x80000000 | 0x40000000 | 0x00100000,
                share_delete=False,
            )
        except FileExistsError:
            scratch = _codex_native_open_relative(
                root_handle, ".scratchpad", directory=True, create=False,
                access=0x80000000 | 0x40000000 | 0x00100000,
                share_delete=False,
            )
        scratch_identity = _codex_native_exact_component(scratch, ".scratchpad")
        if not scratch_identity["attributes"] & 0x10:
            raise RuntimeError("dry config scratchpad is not a directory")
        if action == "create":
            if not isinstance(payload, dict):
                raise RuntimeError("dry config payload is malformed")
            raw = json.dumps(payload, indent=2).encode("utf-8")
            config_handle = _codex_native_open_relative(
                scratch, "config.json", directory=False, create=True,
                access=0x80000000 | 0x40000000 | 0x00010000 | 0x00100000,
                share_delete=False,
            )
            _codex_native_exact_component(config_handle, "config.json")
            _codex_native_write(config_handle, raw)
        elif action in {"resume", "overwrite-refusal"}:
            config_handle = _codex_native_open_relative(
                scratch, "config.json", directory=False, create=False,
                access=0x80000000 | 0x00000080 | 0x00100000,
                share_delete=False,
            )
            _codex_native_exact_component(config_handle, "config.json")
            raw = _codex_native_read(config_handle)
            if action == "overwrite-refusal" and payload is not None:
                expected = json.dumps(payload, indent=2).encode("utf-8")
                if raw != expected:
                    raise RuntimeError("overwrite refusal config differs from requested config")
        else:
            raise RuntimeError("unknown dry config action")
        descriptor = _CodexInstallMutationDispatcher._native_handle_descriptor(config_handle)
        parsed = _strict_json_bytes(raw)
        if _codex_native_read(config_handle) != raw:
            raise RuntimeError("dry config changed during retained read")
        return parsed, raw, descriptor
    finally:
        if config_handle is not None: _codex_native_close(config_handle)
        if scratch is not None: _codex_native_close(scratch)
        root_close()


def _run_private_config_route(argv):
    if len(argv) == 7 and argv[1] in {"--create", "--overwrite-refusal"}:
        _verb, action, project, pipeline, mode, language, backend = argv
        if pipeline not in {"sc", "l1"} or mode not in {"light", "core", "thorough"}:
            raise RuntimeError("dry config pipeline/mode is invalid")
        if backend != "codex":
            raise RuntimeError("dry config route is provider-capable or foreign")
        payload = _launch_v2_config_value(
            pipeline, mode, project, language, cli_backend=backend,
        )
        native_action = "create" if action == "--create" else "overwrite-refusal"
        parsed, raw, descriptor = _dry_config_native(
            project, action=native_action, payload=payload,
        )
        return {
            "schema": "plamen.config_dry.v1", "action": native_action,
            "config": parsed, "config_sha256": hashlib.sha256(raw).hexdigest(),
            "config_authority": descriptor, "provider_invocations": 0,
            "refused": native_action == "overwrite-refusal",
        }
    if len(argv) == 3 and argv[1] == "--resume":
        config_path = Path(argv[2]).absolute()
        if config_path.name != "config.json" or config_path.parent.name != ".scratchpad":
            raise RuntimeError("resume config path is noncanonical")
        project = config_path.parent.parent
        parsed, raw, descriptor = _dry_config_native(project, action="resume")
        if Path(parsed.get("project_root", "")).absolute() != project:
            raise RuntimeError("resume config project root differs")
        return {
            "schema": "plamen.config_dry.v1", "action": "resume",
            "config": parsed, "config_sha256": hashlib.sha256(raw).hexdigest(),
            "config_authority": descriptor, "provider_invocations": 0,
            "refused": False,
        }
    raise RuntimeError("private config route argv is malformed")


def _run_private_wizard_dry(argv, *, pipeline):
    prefix = (
        ["wizard", "--dry-run", "--codex"] if pipeline == "sc"
        else ["l1", "wizard", "--dry-run", "--codex"]
    )
    if argv[:len(prefix)] != prefix:
        raise RuntimeError("wizard dry argv prefix differs")
    tail = argv[len(prefix):]; resume = False
    if tail and tail[0] == "--resume":
        resume = True; tail = tail[1:]
    if len(tail) > 1:
        raise RuntimeError("wizard dry argv has extra fields")
    config_path = (
        Path(tail[0]).absolute() if tail
        else Path.cwd() / ".scratchpad" / "config.json"
    )
    if config_path.name != "config.json" or config_path.parent.name != ".scratchpad":
        raise RuntimeError("wizard dry config path is noncanonical")
    project = config_path.parent.parent
    config, config_raw, config_authority = _dry_config_native(project, action="resume")
    if config.get("pipeline") != pipeline or config.get("cli_backend") != "codex":
        raise RuntimeError("wizard dry config pipeline/backend differs")
    if config.get("mode") not in {"light", "core", "thorough"}:
        raise RuntimeError("wizard dry config mode differs")
    codex_home = Path(os.path.expanduser("~/.codex")).absolute()
    resource_name = "plamen-wizard.md" if pipeline == "sc" else "plamen-l1-wizard.md"
    resource = codex_home / "skills" / "plamen" / resource_name
    _resource_authority, resource_raw = _codex_install_committed_read(
        codex_home, ("skills", "plamen", resource_name), directory=False,
    )
    if not resource_raw or b"plamen" not in resource_raw.lower():
        raise RuntimeError("installed wizard resource is invalid")
    driver = Path(PLAMEN_HOME) / "scripts" / "plamen_driver.py"
    _driver_authority, driver_raw = _codex_install_committed_read(
        Path(PLAMEN_HOME), ("scripts", "plamen_driver.py"), directory=False,
    )
    if not driver_raw:
        raise RuntimeError("installed driver is unavailable")
    driver_argv = (
        [sys.executable, str(driver), str(config_path)] if resume else
        [sys.executable, str(driver), "--startup-intent", "START_NEW_RUN", str(config_path)]
    )
    return {
        "schema": "plamen.wizard_dry.v1", "pipeline": pipeline,
        "intent": "RESUME" if resume else "START_NEW_RUN",
        "resource": str(resource),
        "resource_sha256": hashlib.sha256(resource_raw).hexdigest(),
        "config": str(config_path),
        "config_sha256": hashlib.sha256(config_raw).hexdigest(),
        "config_authority": config_authority,
        "driver_sha256": hashlib.sha256(driver_raw).hexdigest(),
        "driver_argv": driver_argv,
        "driver_argv_sha256": hashlib.sha256(
            _borrowed_reader_canonical_bytes(driver_argv)
        ).hexdigest(),
        "provider_invocations": 0,
    }


def main():
    if len(sys.argv) <= 1:
        _enforce_public_claude_projection_preflight()
    # Fast path: CLI args skip the interactive UI
    if len(sys.argv) > 1:
        arg = sys.argv[1].lower()

        if (
            arg != "install" and not arg.startswith("--codex-install-")
            and arg not in {
                "--recover-codex-install",
                "mcp-selection", "mcp-launch", "backend-launch",
            }
        ):
            _enforce_public_claude_projection_preflight()

        if arg == "--codex-install-assert-claude-projection-current":
            if sys.argv[1:] != [
                "--codex-install-assert-claude-projection-current",
            ]:
                sys.stderr.write(
                    "Claude projection assertion argv differs.\n"
                )
                raise SystemExit(75)
            try:
                result = _assert_claude_projection_current()
            except (OSError, RuntimeError, ValueError, TypeError) as exc:
                sys.stderr.write(
                    "Claude projection admission denied: " + str(exc) + "\n"
                )
                raise SystemExit(75)
            output = getattr(sys.stdout, "buffer", None)
            if output is None:
                sys.stderr.write(
                    "Claude projection assertion requires binary stdout.\n"
                )
                raise SystemExit(75)
            raw = json.dumps(
                result, sort_keys=True, separators=(",", ":"),
            ).encode("utf-8") + b"\n"
            view = memoryview(raw); offset = 0
            while offset < len(view):
                count = output.write(view[offset:])
                if (
                    not isinstance(count, int) or isinstance(count, bool)
                    or count <= 0 or count > len(view) - offset
                ):
                    raise SystemExit(75)
                offset += count
            output.flush()
            return

        if arg in {"mcp-selection", "mcp-launch"}:
            try:
                raise SystemExit(_mcp_public_route(sys.argv[1:]))
            except (OSError, RuntimeError, ValueError, TypeError, KeyError) as exc:
                sys.stderr.write("MCP runtime admission denied: " + str(exc) + "\n")
                raise SystemExit(75)

        if arg == "backend-launch":
            try:
                raise SystemExit(_backend_public_route(sys.argv[1:]))
            except (OSError, RuntimeError, ValueError, TypeError, KeyError) as exc:
                sys.stderr.write("Backend runtime admission denied: " + str(exc) + "\n")
                raise SystemExit(75)

        if arg == "--codex-install-census-child":
            if len(sys.argv) != 2:
                raise RuntimeError("install census child argv differs")
            raise SystemExit(_run_codex_install_census_child())

        if arg == "--codex-install-keeper":
            raise SystemExit(_run_codex_install_keeper(sys.argv[1:]))

        if arg == "--recover-codex-install":
            if len(sys.argv) != 3 or not re.fullmatch(r"[0-9a-f]{32}", sys.argv[2]):
                raise RuntimeError(
                    "--recover-codex-install requires one exact 32-hex transaction id"
                )
            recovered = _recover_codex_package_transaction(sys.argv[2])
            sys.stdout.write(
                f"Recovered transaction: {recovered['transaction_id']}\n"
            )
            return

        if arg == "--detect-language" and len(sys.argv) == 3:
            print(json.dumps({
                "schema": "plamen.front_detect.v1",
                "project": sys.argv[2],
                "language": _detect_language(sys.argv[2]),
                "provider_invocations": 0,
            }, sort_keys=True, separators=(",", ":")))
            return

        if arg == "config" and len(sys.argv) > 2 and sys.argv[2] in {
            "--create", "--resume", "--overwrite-refusal",
        }:
            print(json.dumps(
                _run_private_config_route(sys.argv[1:]),
                sort_keys=True, separators=(",", ":"),
            ))
            return

        if arg == "wizard" and "--dry-run" in sys.argv[2:]:
            print(json.dumps(
                _run_private_wizard_dry(sys.argv[1:], pipeline="sc"),
                sort_keys=True, separators=(",", ":"),
            ))
            return

        if (
            arg == "l1" and len(sys.argv) > 2 and sys.argv[2] == "wizard"
            and "--dry-run" in sys.argv[3:]
        ):
            print(json.dumps(
                _run_private_wizard_dry(sys.argv[1:], pipeline="l1"),
                sort_keys=True, separators=(",", ":"),
            ))
            return

        # ── Help ──────────────────────────────────────────────
        if arg in ("help", "--help", "-h"):
            w = sys.stdout.write
            show_banner()
            w(f"  {_C_WHITE}Usage:{_RST}\n")
            w(f"    {_C_ORANGE}plamen{_RST}                              Interactive wizard\n")
            w(f"\n  {_C_WHITE}Smart Contract (auto-detect language):{_RST}\n")
            w(f"    {_C_ORANGE}plamen{_RST} {_C_GRAY}core{_RST} /path/to/project        SC audit in Core mode\n")
            w(f"    {_C_ORANGE}plamen{_RST} {_C_GRAY}thorough{_RST} /path/to/project    SC audit in Thorough mode\n")
            w(f"    {_C_ORANGE}plamen{_RST} {_C_GRAY}light{_RST} /path/to/project       SC audit in Light mode\n")
            w(f"\n  {_C_WHITE}L1 Infrastructure:{_RST}\n")
            w(f"    {_C_ORANGE}plamen{_RST} {_C_GRAY}l1 core{_RST} /path/to/project     L1 audit in Core mode\n")
            w(f"    {_C_ORANGE}plamen{_RST} {_C_GRAY}l1 thorough{_RST} /path             L1 audit in Thorough mode\n")
            w(f"    {_C_ORANGE}plamen{_RST} {_C_GRAY}l1 light{_RST} /path                L1 audit in Light mode\n")
            w(f"\n  {_C_WHITE}Other:{_RST}\n")
            w(f"    {_C_ORANGE}plamen{_RST} {_C_GRAY}resume{_RST}                       Resume interrupted audit\n")
            w(f"    {_C_ORANGE}plamen{_RST} {_C_GRAY}resume{_RST} path/config.json      Resume specific config\n")
            w(f"    {_C_ORANGE}plamen{_RST} {_C_GRAY}start-config{_RST} path/config.json Start a pre-created clean config\n")
            w(f"    {_C_ORANGE}plamen{_RST} {_C_GRAY}compare{_RST}                      Diff reports\n")
            w(f"    {_C_ORANGE}plamen{_RST} {_C_GRAY}install{_RST}                      Non-interactive install (symlinks + config)\n")
            w(f"    {_C_ORANGE}plamen{_RST} {_C_GRAY}setup{_RST}                        Install + interactive toolchain wizard + RAG\n")
            w(f"    {_C_ORANGE}plamen{_RST} {_C_GRAY}migrate{_RST}                      Migrate v1.x install (~/.claude) to v2.x (~/.plamen)\n")
            w(f"    {_C_ORANGE}plamen{_RST} {_C_GRAY}doctor{_RST}                       Verify install (no audit run, no API calls)\n")
            w(f"    {_C_ORANGE}plamen{_RST} {_C_GRAY}rag{_RST}                          Rebuild RAG database only\n")
            w(f"    {_C_ORANGE}plamen{_RST} {_C_GRAY}uninstall{_RST}                    Remove from ~/.claude\n")
            w(f"    {_C_ORANGE}plamen{_RST} {_C_GRAY}install --codex{_RST}             Install Codex adapter\n")
            w(f"\n  {_C_WHITE}Options:{_RST}\n")
            w(f"    {_C_GRAY}--docs{_RST} PATH              Whitepaper or spec file\n")
            w(f"    {_C_GRAY}--scope{_RST} PATH             Scope file listing contracts\n")
            w(f"    {_C_GRAY}--notes{_RST} TEXT             Scope notes (free text)\n")
            w(f"    {_C_GRAY}--network{_RST} NAME           Target network (SC only)\n")
            w(f"    {_C_GRAY}--proven-only{_RST}            Cap unproven findings at Low (SC only)\n")
            w(f"    {_C_GRAY}--tier{_RST} T0|T1|T2|T3      L1 tier override\n")
            w(f"    {_C_GRAY}--modules{_RST} a,b,c          L1 T1 module selection\n")
            w(f"    {_C_GRAY}--codex{_RST}                  Use Codex CLI backend\n")
            w(f"    {_C_GRAY}--claude{_RST}                 Use Claude Code backend (default)\n")
            w(f"    {_C_GRAY}--claude-exec-mode{_RST} MODE  Claude transport: headless only\n")
            w(f"    {_C_GRAY}--claude-headless{_RST}        Request contained headless (SC Thorough)\n")
            w(f"\n")
            return

        # ── Estimate subcommand (for /plamen command) ────────
        if arg == "plan":
            if len(sys.argv) < 3:
                _cli_usage_error("plan requires MODE and PATH")
            plan_mode = sys.argv[2].lower()
            plan_opts = _parse_cli_opts(sys.argv[3:])
            plan = _public_plan(plan_mode, sys.argv[3:])
            _print_public_plan(
                plan,
                explain_routes=plan_opts["explain_routes"],
                as_json=plan_opts["json"],
            )
            raise SystemExit(0 if plan["launchable"] else 1)

        if arg == "--estimate":
            import json as _json
            est_target = sys.argv[2] if len(sys.argv) > 2 else "."
            est_mode = sys.argv[3] if len(sys.argv) > 3 else "core"
            est_pipeline = "sc"
            est_scope = ""
            est_notes = ""
            for i, a in enumerate(sys.argv):
                if a == "--scope" and i + 1 < len(sys.argv):
                    est_scope = sys.argv[i + 1]
                if a == "--scope-notes" and i + 1 < len(sys.argv):
                    est_notes = sys.argv[i + 1]
                if a == "--l1":
                    est_pipeline = "l1"
            r = estimate_cost(est_target, est_mode, est_scope, est_notes,
                              pipeline=est_pipeline)
            print(_json.dumps(r))
            return

        # ── Install / setup / migrate / uninstall subcommands ─
        # `install` is non-interactive (symlinks + config + Python deps + hook
        # self-heal). Safe in Claude Code Bash, Codex shell, and CI. Exits 0.
        # `setup` runs install, then the interactive toolchain checkbox + RAG.
        # `--codex` runs only the Codex adapter generator (non-interactive).
        if arg in ("install", "setup"):
            if "--codex" in sys.argv:
                show_banner()
                w = sys.stdout.write
                console.print(Rule(title="Codex Adapter", style="color(238)"))
                if not _install_codex_adapter(w, enable_claude_projection=False):
                    sys.exit(1)
                return
            show_banner()
            if arg == "install":
                raise SystemExit(run_install() or 0)
            else:
                raise SystemExit(run_setup() or 0)
            return

        if arg == "uninstall":
            show_banner()
            run_uninstall()
            return

        if arg == "migrate":
            run_migrate()
            return

        if arg in ("doctor", "verify", "check"):
            rc = run_doctor()
            sys.exit(rc)

        if arg == "resume":
            if (
                len(sys.argv) > 3
                or (len(sys.argv) == 3 and sys.argv[2].startswith("-"))
            ):
                _cli_usage_error(
                    "resume accepts zero or one non-option config.json path"
                )
            show_banner()
            # Accept explicit config path or auto-detect
            config_path = sys.argv[2] if len(sys.argv) > 2 else None
            if config_path and os.path.isfile(config_path):
                resume_v2(config_path)
            else:
                existing = _find_existing_audit(config_path or "")
                if existing and existing.get("config_path"):
                    resume_v2(existing["config_path"])
                elif existing and existing.get("config_missing"):
                    sys.stdout.write(
                        f"  {_C_RED}✗ Audit found but config.json is missing and"
                        f" could not be recovered.{_RST}\n"
                        f"  {_C_GRAY}Scratchpad: {existing['scratchpad']}{_RST}\n"
                        f"  {_C_GRAY}Run interactively to clean up or start fresh.{_RST}\n"
                    )
                    sys.exit(1)
                else:
                    sys.stdout.write(f"  {_C_RED}✗ No existing audit found to resume.{_RST}\n")
                    sys.exit(1)
            return

        if arg == "start-config":
            show_banner()
            if len(sys.argv) != 3:
                _cli_usage_error("start-config requires exactly one config.json path")
            start_config_v2(sys.argv[2])
            return

        if arg == "rag":
            show_banner()
            w = sys.stdout.write
            w(f"\n  {_BOLD}{_C_WHITE}Building RAG vulnerability database...{_RST}\n\n")
            sys.stdout.flush()
            _build_rag_db(w)
            return

        # ── L1 CLI: plamen l1 <mode> [path] [--opts] ─────────
        if arg == "l1":
            _check_claude_md_version()
            l1_mode = sys.argv[2].lower() if len(sys.argv) > 2 else "core"
            if l1_mode not in ("light", "core", "thorough"):
                sys.stdout.write(f"  {_C_RED}Unknown L1 mode: {l1_mode}{_RST}\n")
                sys.exit(1)
            opts = _parse_cli_opts(sys.argv[3:])
            target = opts["positionals"][0] if opts["positionals"] else ""
            if not target:
                if not (sys.stdin.isatty() and sys.stdout.isatty()):
                    _cli_usage_error("l1 audit requires an explicit target path")
                show_banner()
                target, _ = select_target()
            target = os.path.abspath(target)
            if not os.path.isdir(target):
                _cli_usage_error(f"target directory does not exist: {target}")
            language = _detect_language(target)
            if language not in ("go", "rust"):
                language = "go"  # default for L1
            exts = {".go"} if language == "go" else {".rs"}
            loc = _count_loc(target, exts)
            tier = opts["tier"] or _detect_l1_tier(loc)
            subsystem_scope = ""
            if tier == "t1" and opts["modules"]:
                subsystem_scope = opts["modules"]
            elif tier == "t1" and sys.stdin.isatty() and sys.stdout.isatty():
                modules = _scan_modules(target, language)
                if modules:
                    selected = select_l1_modules(modules)
                    subsystem_scope = ",".join(m[1] for m in selected)
            fork_mode = "standalone"
            if _detect_fork(target) and sys.stdin.isatty() and sys.stdout.isatty():
                fork_mode = select_l1_fork()
            requested_backend = opts["cli_backend"] or _ambient_backend(
                _detect_cli_backends()
            )
            try:
                transport_resolution = _bind_new_claude_transport(
                        "l1", l1_mode, requested_backend,
                        opts["claude_exec_mode"],
                    )
                requested_backend, claude_exec_mode, transport_warning = (
                    _replay_new_transport_resolution(
                        transport_resolution, pipeline="l1", mode=l1_mode,
                    )
                )
            except RuntimeError as exc:
                _cli_usage_error(str(exc))
            if not opts["yes"] and not (sys.stdin.isatty() and sys.stdout.isatty()):
                _cli_usage_error("non-interactive audit launch requires --yes; use `plamen plan` first")
            if not opts["yes"]:
                show_summary(
                    l1_mode, target, opts["docs"], pipeline="l1",
                    language=language, tier=tier,
                    backend=requested_backend,
                    claude_exec_mode=claude_exec_mode,
                    transport_warning=transport_warning,
                )
                if confirm_launch() != "launch":
                    return
            launch_v2("l1", l1_mode, target, language,
                       docs=opts["docs"], tier=tier,
                       subsystem_scope=subsystem_scope, fork_mode=fork_mode,
                       cli_backend=requested_backend,
                       claude_exec_mode=claude_exec_mode,
                       allow_model_fallback=opts["allow_model_fallback"],
                       _transport_resolution=transport_resolution)
            return

        # ── SC CLI: plamen <mode> [path] [--opts] ─────────────
        if arg in ("light", "core", "thorough"):
            _check_claude_md_version()
            opts = _parse_cli_opts(sys.argv[2:])
            target = opts["positionals"][0] if opts["positionals"] else ""
            if not target:
                if not (sys.stdin.isatty() and sys.stdout.isatty()):
                    _cli_usage_error("audit requires an explicit target path")
                show_banner()
                target, _ = select_target()
            target = os.path.abspath(target)
            if not os.path.isdir(target):
                _cli_usage_error(f"target directory does not exist: {target}")
            language = _detect_language(target)
            if language in ("go", "rust"):
                language = "evm"  # SC mode, force SC language
            requested_backend = opts["cli_backend"] or _ambient_backend(
                _detect_cli_backends()
            )
            try:
                transport_resolution = _bind_new_claude_transport(
                        "sc", arg, requested_backend,
                        opts["claude_exec_mode"],
                    )
                requested_backend, claude_exec_mode, transport_warning = (
                    _replay_new_transport_resolution(
                        transport_resolution, pipeline="sc", mode=arg,
                    )
                )
            except RuntimeError as exc:
                _cli_usage_error(str(exc))
            if not opts["yes"] and not (sys.stdin.isatty() and sys.stdout.isatty()):
                _cli_usage_error("non-interactive audit launch requires --yes; use `plamen plan` first")
            if not opts["yes"]:
                show_summary(
                    arg, target, opts["docs"], opts["network"],
                    opts["scope_file"], opts["scope_notes"],
                    pipeline="sc", language=language,
                    strict=opts["proven_only"],
                    backend=requested_backend,
                    claude_exec_mode=claude_exec_mode,
                    transport_warning=transport_warning,
                )
                if confirm_launch() != "launch":
                    return
            launch_v2("sc", arg, target, language,
                       docs=opts["docs"], scope_file=opts["scope_file"],
                       scope_notes=opts["scope_notes"],
                       proven_only=opts["proven_only"],
                       cli_backend=requested_backend,
                       claude_exec_mode=claude_exec_mode,
                       allow_model_fallback=opts["allow_model_fallback"],
                       _transport_resolution=transport_resolution)
            return

        # ── Compare ──────────────────────────────────────────
        if arg == "compare":
            _check_claude_md_version()
            opts = _parse_cli_opts(sys.argv[2:])
            if opts["cli_backend"] == "codex":
                _cli_usage_error("compare requires Claude Code and does not support --codex")
            if not opts["positionals"]:
                _cli_usage_error("compare requires a report path")
            target = os.path.abspath(opts["positionals"][0])
            if not os.path.isfile(target):
                _cli_usage_error(f"report file does not exist: {target}")
            launch_claude("compare", target, opts["docs"])
            return

        _cli_usage_error(f"unknown command: {sys.argv[1]}")

    # ── Interactive flow (state machine) ─────────────────────
    if not (sys.stdin.isatty() and sys.stdout.isatty()):
        sys.stderr.write(
            "Plamen's interactive wizard needs a real terminal.\n"
            "Use `plamen plan MODE PATH` to validate a run, or run `plamen help`.\n"
        )
        raise SystemExit(2)

    show_banner()
    _check_claude_md_version()

    # ── Resume detection: check for existing audit before anything else ──
    existing = _find_existing_audit()
    if existing:
        decision = _resume_audit_prompt(existing)
        if decision == "cancel":
            sys.stdout.write(f"\n  {_C_GRAY}Exiting. Scratchpad left intact.{_RST}\n")
            return
        elif decision == "resume":
            resume_v2(existing["config_path"])
            return
        else:
            # "new" preserves the old run and falls through to the wizard so
            # the operator can select a distinct clean destination.
            sys.stdout.write(
                f"\n  {_C_GREEN}✓{_RST} Previous audit preserved."
                f"  {_C_GRAY}Choose a distinct clean destination for the new audit.{_RST}\n\n"
            )
            sys.stdout.flush()

    show_hint_panel()

    if not _quick_check_required():
        check_dependencies()
        sys.stdout.write(f"  {_C_RED}Cannot proceed without required tools.{_RST}\n")
        sys.stdout.write(
            f"  {_C_GRAY}Install Claude Code or Codex CLI, plus python, npm, and git, then retry.{_RST}\n"
        )
        sys.exit(1)

    # ── Non-TTY guard for the interactive wizard ─────────────
    # `plamen` (no args), `plamen compare`, and any path that falls into
    # the InquirerPy-driven wizard need a controlling terminal. Without
    # one, `inquirer.select(...).execute()` crashes inside
    # prompt_toolkit/input/vt100.py with
    # `OSError: [Errno 22] Invalid argument`. Catch it here with an
    # actionable message instead of a traceback.
    if not (sys.stdin.isatty() and sys.stdout.isatty()):
        show_banner()
        w = sys.stdout.write
        w(f"\n  {_C_ORANGE}!{_RST} Plamen wizard needs a real terminal.\n")
        w(f"    {_C_GRAY}Detected non-TTY (Claude Code Bash / Codex shell / CI / piped stdio).{_RST}\n\n")
        w(f"  {_C_WHITE}Choose one:{_RST}\n")
        w(f"    {_C_ORANGE}plamen{_RST} {_C_GRAY}install{_RST}                    Non-interactive install (safe here)\n")
        w(f"    {_C_ORANGE}plamen{_RST} {_C_GRAY}core{_RST} /path/to/project      Skip wizard with explicit mode + path\n")
        w(f"    {_C_ORANGE}plamen{_RST} {_C_GRAY}thorough{_RST} /path/to/project  Same, Thorough mode\n")
        w(f"    {_C_ORANGE}plamen{_RST} {_C_GRAY}light{_RST} /path/to/project     Same, Light mode\n")
        w(f"    {_C_ORANGE}plamen{_RST} {_C_GRAY}migrate{_RST}                    Migrate v1.x install layout\n")
        w(f"    {_C_ORANGE}plamen{_RST} {_C_GRAY}help{_RST}                       Full subcommand list\n\n")
        w(f"  {_C_GRAY}Or open a real terminal and run `plamen` again.{_RST}\n\n")
        return

    pipeline = mode = target = docs = network = scope_file = scope_notes = ""
    language = tier = fork_mode = subsystem_scope = ""
    cli_backend = ""
    claude_exec_mode = ""
    transport_warning = ""
    transport_resolution = None
    is_fork = False
    l1_modules = []
    report = ground_truth = ""
    strict = False
    step = 0

    # Helper: build breadcrumbs from current state for clear+rebanner
    def _sc_crumbs_to(step_id):
        """Breadcrumbs for SC flow up to (not including) step_id."""
        c = [("Pipeline", "Smart Contract"), ("Mode", mode)]
        if step_id > 1:
            c.append(("Target", _shorten(target, 40)))
        if step_id > 2:
            c.append(("Docs", docs if docs else "none"))
        if step_id > 3:
            sc = scope_file or scope_notes or "full project"
            c.append(("Scope", _shorten(sc, 40) if scope_file else sc))
        if step_id > 35:
            c.append(("Proven-only", "yes" if strict else "no"))
        return c

    def _l1_crumbs_to(step_id):
        """Breadcrumbs for L1 flow up to (not including) step_id."""
        c = [("Pipeline", "L1 Infrastructure"), ("Mode", mode)]
        if step_id > 1:
            c.append(("Target", f"{_shorten(target, 30)} ({language.upper()}, {loc:,} LOC)"))
        if step_id > 12:
            tl = _L1_TIER_LABELS.get(tier, (tier, ""))[0]
            c.append(("Tier", tl))
        if step_id > 13 and tier == "t1" and l1_modules:
            names = ", ".join(m[0] for m in l1_modules[:4])
            c.append(("Modules", names))
        if step_id > 14:
            c.append(("Fork", fork_mode))
        if step_id > 15:
            c.append(("Docs", docs if docs else "none"))
        return c

    def _cmp_crumbs_to(step_id):
        """Breadcrumbs for Compare flow."""
        c = [("Mode", "Compare")]
        if step_id > 1:
            c.append(("Report", _shorten(report, 40)))
        if step_id > 2:
            c.append(("Ground truth", _shorten(ground_truth, 40)))
        return c

    loc = 0  # needed by _l1_crumbs_to before L1 step 1 sets it
    detected_tier = "t2"

    while True:
        # ── Step 0: Pipeline selection ────────────────────────
        if step == 0:
            pipeline = select_pipeline()
            sys.stdout.write("\n"); sys.stdout.flush()
            if pipeline == "setup":
                run_setup()
                step = 0; continue
            if pipeline == "compare":
                mode = "compare"
                step = 1; continue
            step = 5; continue

        # ── Step 0.5: Audit depth selection ──────────────────
        if step == 5:
            mode = select_audit_mode(pipeline)
            if mode == _BACK:
                _clear_and_rebanner()
                step = 0; continue
            sys.stdout.write("\n"); sys.stdout.flush()
            step = 6; continue

        # ── Step 6: Backend selection (only if multiple runtimes exist) ──
        if step == 6:
            detected_backends = _detect_cli_backends()
            if _skip_backend_prompt() or len(detected_backends) <= 1:
                cli_backend = (
                    detected_backends[0]
                    if len(detected_backends) == 1
                    else _ambient_backend(detected_backends)
                )
                step = 65; continue
            choices = []
            if "claude" in detected_backends:
                choices.append({
                    "name": "Claude Code    Anthropic Claude",
                    "value": "claude",
                })
            if "codex" in detected_backends:
                choices.append({
                    "name": "Codex CLI      OpenAI GPT-5.6 Sol / Terra / Luna",
                    "value": "codex",
                })
            choices.extend(_back_separator())
            _drain_stdin()
            result = inquirer.select(
                message="AI runtime?",
                choices=choices,
                default=_ambient_backend(detected_backends),
                pointer="  >",
                style=_STYLE,
                qmark=">",
                amark="✓",
            ).execute()
            if result == _BACK:
                _clear_and_rebanner()
                step = 5; continue
            cli_backend = result
            sys.stdout.write("\n"); sys.stdout.flush()
            step = 65; continue

        # ── Step 6.5: Claude transport (SC Thorough only) ──────────────
        if step == 65:
            if cli_backend == "claude" and pipeline == "sc" and mode == "thorough":
                transport_resolution, transport_warning = select_claude_transport(
                    pipeline, mode,
                )
                if transport_resolution == _BACK:
                    transport_resolution = None
                    claude_exec_mode = ""
                    transport_warning = ""
                    _clear_and_rebanner()
                    step = 6; continue
                cli_backend, claude_exec_mode, transport_warning = (
                    _replay_new_transport_resolution(
                        transport_resolution, pipeline=pipeline, mode=mode,
                    )
                )
                sys.stdout.write("\n"); sys.stdout.flush()
            elif cli_backend == "claude":
                sys.stdout.write(
                    f"  {_C_RED}Authenticated contained Claude headless is "
                    f"not available for {pipeline.upper()} {mode} audits.{_RST}\n"
                    f"  {_C_GRAY}Choose Codex explicitly; no audit config or "
                    f"scratchpad has been created.{_RST}\n"
                )
                return
            else:
                transport_resolution = _bind_new_claude_transport(
                        pipeline, mode, cli_backend,
                        audit_model_launch=False,
                    )
                cli_backend, claude_exec_mode, transport_warning = (
                    _replay_new_transport_resolution(
                        transport_resolution, pipeline=pipeline, mode=mode,
                    )
                )
            step = 1; continue

        # ── SC audit flow ────────────────────────────────────
        if pipeline == "sc" and mode in ("light", "core", "thorough"):
            if step == 1:
                result = select_target()
                if result[0] == _BACK:
                    _clear_and_rebanner()
                    step = 5; continue
                target, network = result
                language = _detect_language(target)
                if language in ("go", "rust"):
                    language = "evm"
                sys.stdout.write(f"  {_C_GRAY}Detected: {language.upper()}{_RST}\n")
                sys.stdout.write("\n"); sys.stdout.flush()
                step = 2; continue

            if step == 2:
                result = select_docs()
                if result == _BACK:
                    _crumb_set(_sc_crumbs_to(1))
                    _clear_and_rebanner()
                    step = 1; continue
                docs = result
                sys.stdout.write("\n"); sys.stdout.flush()
                step = 3; continue

            if step == 3:
                result = select_scope()
                if result[0] == _BACK:
                    _crumb_set(_sc_crumbs_to(2))
                    _clear_and_rebanner()
                    step = 2; continue
                scope_file, scope_notes = result
                sys.stdout.write("\n"); sys.stdout.flush()
                step = 35; continue

            if step == 35:
                _drain_stdin()
                result = inquirer.select(
                    message="Proven-only mode?",
                    choices=[
                        {"name": "No        standard severity rules",          "value": False},
                        {"name": "Yes       unproven findings capped at Low",  "value": True},
                        *_back_separator(),
                    ],
                    default=False,
                    pointer="  >",
                    style=_STYLE,
                    qmark=">",
                    amark="✓",
                ).execute()
                if result == _BACK:
                    _crumb_set(_sc_crumbs_to(3))
                    _clear_and_rebanner()
                    step = 3; continue
                strict = result
                sys.stdout.write("\n"); sys.stdout.flush()
                step = 4; continue

            if step == 4:
                cost_est = None
                if os.path.isdir(target):
                    cost_est = estimate_cost(target, mode, scope_file, scope_notes,
                                            backend=cli_backend or "claude")
                show_summary(mode, target, docs, network, scope_file, scope_notes, cost_est,
                             strict=strict, pipeline="sc", language=language,
                             backend=cli_backend or "claude",
                             claude_exec_mode=claude_exec_mode,
                             transport_warning=transport_warning)
                decision = confirm_launch()
                if decision == "back":
                    _crumb_set(_sc_crumbs_to(35))
                    _clear_and_rebanner()
                    step = 35; continue
                if decision == "cancel":
                    sys.stdout.write(f"  {_C_DARK_GRAY}Cancelled.{_RST}\n")
                    return
                launch_v2("sc", mode, target, language,
                          docs=docs, scope_file=scope_file,
                          scope_notes=scope_notes, proven_only=strict,
                          cli_backend=cli_backend,
                          claude_exec_mode=claude_exec_mode,
                          _transport_resolution=transport_resolution)
                return

        # ── L1 audit flow ────────────────────────────────────
        if pipeline == "l1" and mode in ("light", "core", "thorough"):
            if step == 1:
                result = select_target()
                if result[0] == _BACK:
                    _clear_and_rebanner()
                    step = 5; continue
                target, _ = result
                language = _detect_language(target)
                if language not in ("go", "rust"):
                    language = "go"
                exts = {".go"} if language == "go" else {".rs"}
                loc = _count_loc(target, exts)
                detected_tier = _detect_l1_tier(loc)
                sys.stdout.write(f"  {_C_GRAY}Detected: {language.upper()}, {loc:,} LOC{_RST}\n")
                sys.stdout.write("\n"); sys.stdout.flush()
                step = 12; continue

            if step == 12:
                result = select_l1_tier(detected_tier, loc)
                if result == _BACK:
                    _crumb_set(_l1_crumbs_to(1))
                    _clear_and_rebanner()
                    step = 1; continue
                tier = result
                sys.stdout.write("\n"); sys.stdout.flush()
                if tier == "t1":
                    step = 13; continue
                step = 14; continue

            if step == 13:
                l1_modules = _scan_modules(target, language)
                if l1_modules:
                    selected = select_l1_modules(l1_modules)
                    if selected == [_BACK]:
                        _crumb_set(_l1_crumbs_to(12))
                        _clear_and_rebanner()
                        step = 12; continue
                    subsystem_scope = ",".join(m[1] for m in selected)
                    total_mod_loc = sum(m[2] for m in selected)
                    if total_mod_loc > 30000:
                        sys.stdout.write(
                            f"  {_C_ORANGE}⚠ Selected modules total {total_mod_loc:,} LOC "
                            f"(T1 target: 5-30k){_RST}\n")
                    l1_modules = selected
                sys.stdout.write("\n"); sys.stdout.flush()
                step = 14; continue

            if step == 14:
                is_fork = _detect_fork(target)
                if is_fork:
                    result = select_l1_fork()
                    if result == _BACK:
                        _crumb_set(_l1_crumbs_to(13 if tier == "t1" else 12))
                        _clear_and_rebanner()
                        step = 12 if tier != "t1" else 13; continue
                    fork_mode = result
                else:
                    fork_mode = "standalone"
                sys.stdout.write("\n"); sys.stdout.flush()
                step = 15; continue

            if step == 15:
                result = select_docs()
                if result == _BACK:
                    # Step 14 (fork) is a no-op when no fork — skip it
                    if is_fork:
                        back_step = 14
                    elif tier == "t1":
                        back_step = 13
                    else:
                        back_step = 12
                    _crumb_set(_l1_crumbs_to(back_step))
                    _clear_and_rebanner()
                    step = back_step; continue
                docs = result
                sys.stdout.write("\n"); sys.stdout.flush()
                step = 16; continue

            if step == 16:
                cost_est = None
                if os.path.isdir(target):
                    cost_est = estimate_cost(target, mode, pipeline="l1",
                                            backend=cli_backend or "claude",
                                            subsystem_scope=subsystem_scope)
                show_summary(mode, target, docs, cost_estimate=cost_est,
                             pipeline="l1", language=language,
                             tier=tier, modules=l1_modules, fork_mode=fork_mode,
                             backend=cli_backend or "claude",
                             claude_exec_mode=claude_exec_mode,
                             transport_warning=transport_warning)
                decision = confirm_launch()
                if decision == "back":
                    _crumb_set(_l1_crumbs_to(15))
                    _clear_and_rebanner()
                    step = 15; continue
                if decision == "cancel":
                    sys.stdout.write(f"  {_C_DARK_GRAY}Cancelled.{_RST}\n")
                    return
                launch_v2("l1", mode, target, language,
                          docs=docs, tier=tier,
                          subsystem_scope=subsystem_scope, fork_mode=fork_mode,
                          cli_backend=cli_backend,
                          claude_exec_mode=claude_exec_mode,
                          _transport_resolution=transport_resolution)
                return

        # ── Compare flow ─────────────────────────────────────
        if mode == "compare":
            if step == 1:
                result = select_report("Your Plamen audit report (.md):")
                if result == _BACK:
                    _clear_and_rebanner()
                    step = 0; continue
                report = result
                sys.stdout.write("\n"); sys.stdout.flush()
                step = 2; continue

            if step == 2:
                result = select_report("Ground truth report (.md):")
                if result == _BACK:
                    _crumb_set(_cmp_crumbs_to(1))
                    _clear_and_rebanner()
                    step = 1; continue
                ground_truth = result
                sys.stdout.write("\n"); sys.stdout.flush()
                step = 3; continue

            if step == 3:
                show_summary(mode, report, ground_truth)
                decision = confirm_launch()
                if decision == "back":
                    _crumb_set(_cmp_crumbs_to(2))
                    _clear_and_rebanner()
                    step = 2; continue
                if decision == "cancel":
                    sys.stdout.write(f"  {_C_DARK_GRAY}Cancelled.{_RST}\n")
                    return
                launch_claude(mode, report, ground_truth)
                return


if __name__ == "__main__":
    try:
        main()
    except KeyboardInterrupt:
        sys.stdout.write(f"\n\n  {_C_DARK_GRAY}Interrupted.{_RST}\n")
        sys.exit(130)
    except EOFError:
        if sys.stdin.isatty():
            sys.stdout.write(f"\n\n  {_C_DARK_GRAY}Cancelled.{_RST}\n")
            sys.exit(0)
        sys.stdout.write(
            f"\n\n  {_C_RED}Input or recovery channel ended unexpectedly.{_RST}\n"
        )
        sys.exit(2)
